// GENDER WARFARE: local-file-safe dialogue cache, generated from data/dialogue/*.json.
window.GW_DIALOGUE_DATA = {"F1":{"chapter":"F1","title":"항만 탈환","line":"female","episodes":[{"id":"F1-1","no":1,"title":"부두의 첫 정화","boss":false,"before":[{"who":"클레어","text":"남부 항구가 제국 해군에 점령당했군요. 홍차가 식기 전에, 저 꼿꼿한 군인들의 교감신경을 완벽하게 짓밟아 무너뜨리고 오겠습니다."},{"who":"제국 병사 A","text":"우리를 짓밟는다고? 육체를 억압하고 유린하는 건 우리 제국군의 전매특허다!"},{"who":"클레어","text":"어머, '합법적 생체 유린'은 저희 연방이 먼저 상표를 등록했답니다."},{"who":"제국 병사 B","text":"상표는 우리가 먼저였어! 그리고 우리 쪽에 있는 구속 도구가 훠얼씬 두껍고 묵직하단 말이다!!"},{"who":"아네트","text":"두께 비교는 포획해서 하의를 벗겨본 뒤에 하시죠."},{"who":"제국 병사 B","text":"이, 이래 뵈도 꽤 튼실한 편이란 말이다!! (하복부를 가리며 당황한다)"},{"who":"실비아","text":"(스코프를 들여다보며) …글쎄요, 제 렌즈로는 근육의 수축과 팽창이 전혀 관측되지 않는데요."},{"who":"그레타","text":"확대율을 최대로 올려주면 먼지라도 보이겠구만."},{"who":"클레어","text":"실비아, 멸시는 나중에. 교전 규칙부터 안내하죠. 포획 후 강제 개방, 개방 후 신경 고문, 고문 후 예약입니다."}],"after":[{"who":"아네트","text":"포획 32명. 점막 화상 치료 및 전기 찜질 이송 전에 접수대에서 번호표를 뽑아 주세요."},{"who":"제국 병사 A","text":"번호표…… 큭, 내 괄약근이 당장 주인의 채찍을 원하고 있는데 줄이 왜 이렇게 긴 거냐!"},{"who":"클레어","text":"업무(발정)가 빠르시네요. 얌전히 기다리시면 척수에 에테르를 한 방울씩 떨어뜨려 드리겠습니다."}],"stars":{"3":{"who":"아네트","text":"오차 없는 포획입니다. 접수 대기시간 평균 4분, 만족도 상."},"2":{"who":"아네트","text":"포획은 양호했으나 접수 줄이 길어졌습니다. 번호표를 늘리겠습니다."},"1":{"who":"아네트","text":"병사 일부가 접수 전에 흩어졌습니다. 아쉽게도 상담 불가입니다."}}},{"id":"F1-2","no":2,"title":"크레인 위의 높은 분들","boss":false,"before":[{"who":"아네트","text":"제국 장교단이 30미터 높이의 부두 크레인 위에서 거드름을 피우고 있습니다."},{"who":"그레타","text":"높은 데서 폼 잡는 놈들은 하나같이 엉덩이 내구도가 형편없구만."},{"who":"실비아","text":"정중하고 예의 바르게 허리띠 버클만 쏘겠습니다. 한 분당 한 발. 하반신이 무방비하게 개방되면 수치심에 알아서 굴러떨어지겠죠."},{"who":"제국 장교","text":"우리는 이 높이를 지킬 것이다! 아래 것들이 올려다보는 이 권위적인 풍경이 군인의 낙이다!"},{"who":"그레타","text":"밑에서 올려다보면 그쪽 덜렁거리는 사정거리만 아주 잘 보이겠구만."}],"after":[{"who":"제국 장교","text":"(바지가 벗겨진 채 허벅지를 떨며) 내, 내려가면 어떻게 되는 거지? 이 서늘한 수치심을 당장 짓밟아 줄 수 있나?!"},{"who":"아네트","text":"평균 40분짜리 고전압 고문 안내를 받으시게 됩니다."},{"who":"제국 장교","text":"사십 분이나 내 척수를 태워준다고!! 당장 내려간다!"}],"stars":{"3":{"who":"아네트","text":"장교 전원 하강. 허리띠 회수율 100%, 간식 만족도 최상."},"2":{"who":"아네트","text":"장교 대부분 하강. 일부는 크레인 위에서 아직 기다리고 계십니다."},"1":{"who":"아네트","text":"허리띠 몇 개가 바다에 빠졌습니다. 예비 허리띠를 지급하겠습니다."}}},{"id":"F1-3","no":3,"title":"컨테이너의 매뉴얼","boss":false,"before":[{"who":"그레타","text":"제국 놈들이 흘린 「하드코어 조련 매뉴얼 제3판」이구만."},{"who":"아네트","text":"내용이 저희랑 거의 같네요. 제3조 4항 「주인은 노예가 가장 고통을 느끼기 편한 림프절에 도구를 고정한다」. 저희 규정은 「가장 짓이기기 편한 위치」입니다."},{"who":"실비아","text":"저는 제5조가 마음에 듭니다. 「노예의 비명은 데시벨이 높고 타액이 동반되어야 한다」."},{"who":"제국 병사","text":"그건 우리 제국군 M들의 취향이다! 함부로 평가하지 마라!"}],"after":[{"who":"제국 병사","text":"3판은 오탈자가 너무 많습니다. 개정안을 올리고 싶습니다."},{"who":"아네트","text":"환영합니다. 저희도 4판을 준비 중이에요. 공동 편집 신청서는 접수대에서 받으세요."},{"who":"그레타","text":"적과 같이 규정집을 만들고 있구만. 이게 전쟁인가."},{"who":"클레어","text":"전쟁입니다. 다만 서식이 있을 뿐이죠."}],"stars":{"3":{"who":"아네트","text":"문서 전량 회수, 오탈자 42건 수정 완료."},"2":{"who":"아네트","text":"문서 대부분 회수. 오탈자 몇 건이 남았습니다."},"1":{"who":"아네트","text":"문서 일부가 젖었습니다. 읽을 수 있는 곳만 읽겠습니다."}}},{"id":"F1-4","no":4,"title":"야전 상담소","boss":false,"before":[{"who":"아네트","text":"오늘부터 이동식 고문 조련실, 명칭 「야전 상담소」를 가동합니다. 대기 환자가 벌써 20명이네요."},{"who":"제국 병사","text":"(네 발로 기어오며) 저 앞 사람 새치기입니다! 제 하복부가 먼저 뚫려야 한단 말입니다!"},{"who":"실비아","text":"저도 정중하게 예약을 걸고 싶습니다."},{"who":"아네트","text":"실비아 씨는 주인이시잖아요. 고문당하고 싶은 게 아니시라면 뒤에 계세요."}],"after":[{"who":"아네트","text":"오늘 진료 20건 완료. 평균 소요 8분, 재방문 의사 100%."},{"who":"제국 병사","text":"(나오며) 선생님, 다음 예약은 언제입니까?"},{"who":"아네트","text":"다음 주 같은 시간입니다. 가운은 두고 가세요."},{"who":"제국 병사","text":"…가운이 좋아서 못 두고 가겠습니다."},{"who":"클레어","text":"반납은 다음 방문 때 부탁드립니다."}],"stars":{"3":{"who":"아네트","text":"대기 0분, 접수 오류 0건. 상담소 만족도 5점 만점."},"2":{"who":"아네트","text":"진료는 순조로웠으나 대기석이 가득 찼습니다."},"1":{"who":"아네트","text":"새치기가 발생해 일부 진료가 지연되었습니다."}}},{"id":"F1-5","no":5,"title":"딸 사진 병장 (톰 합류)","boss":false,"before":[{"who":"아네트","text":"제국 의무 병장 톰. 41세. 품에 딸 사진첩을 안고 다닙니다."},{"who":"톰","text":"잠깐만요! 우리 딸 사진 한 장만 보고 가세요. 우리 딸이 이렇게 훌륭한 어른으로 컸는데..."},{"who":"그레타","text":"전장에서 웬 딸바보 타령이구만."},{"who":"톰","text":"그러니까 제 말씀은, 딸은 어른이 됐는데 저는 퇴행해서 아주 쓸모없고 무력한 가축이 되고 싶다는 뜻입니다. 제발 제 목에 무거운 쇳덩어리를 채워주세요!"},{"who":"클레어","text":"훌륭한 자기 객관화군요. 아네트, 초커를."}],"after":[{"who":"톰","text":"헉... 읏! 목을 조르는 이 압박감... 혈류가 통제당해서 너무 안심됩니다. 저 짐 끄는 개처럼 부려주실 거죠?"},{"who":"그레타","text":"딸 사진첩 들고 헥헥거리는 꼴이 아주 볼만하구만."}],"stars":{"3":{"who":"아네트","text":"톰 병장님 합류. 초커 착용감 만족도 최상, 담요 추가 지급."},"2":{"who":"아네트","text":"합류는 완료되었으나 사진첩 보여주기 시간이 15분 초과했습니다."},"1":{"who":"아네트","text":"합류했지만 딸 사진 발표가 길었습니다. 다음에는 3분 제한을 두겠습니다."}}},{"id":"F1-6","no":6,"title":"짐꾼의 규정 거리","boss":false,"before":[{"who":"아네트","text":"톰 병장님께 마도 족쇄를 채웠습니다. 3미터 이상 떨어지면 아주 민감한 신경절을 강제로 당겨서 극통을 선사하는 규정입니다."},{"who":"톰","text":"당겨진다고요? 근데 꼭 「하복부의 가장 은밀한 점막」 쪽에 묶으실 필요가 있습니까…… ㅜ.ㅜ"},{"who":"아네트","text":"거기가 제가 걷어차기 가장 편한 위치라서요."},{"who":"실비아","text":"어디에 결박했는지 확인했습니다. 정중한 조준점입니다."},{"who":"톰","text":"보지 마세요! 수치스러워서 터질 것 같단 말입니다... 아앗!"}],"after":[{"who":"톰","text":"3미터 넘으니까 당겨졌어요. 아, 그런데 은근히 좋네요. 다음엔 5미터 정도에서도 시험해 봐도 될까요?"},{"who":"아네트","text":"규정 개정 신청서를 쓰시면 됩니다. 간이 접수는 제가 대신 하겠습니다."},{"who":"클레어","text":"규정은 현장에서 자랍니다."}],"stars":{"3":{"who":"아네트","text":"이탈 0회, 당김 반응 우수. 톰 병장님 의견: 「만족」."},"2":{"who":"아네트","text":"이탈 2회. 당김 반응은 정상, 의견: 「조금 더」."},"1":{"who":"아네트","text":"이탈 다수. 족쇄가 더 필요하다는 의견이 접수되었습니다."}}},{"id":"F1-7","no":7,"title":"잠수함에서 나온 사냥개 (렌 합류)","boss":false,"before":[{"who":"아네트","text":"해군 중위 렌. 아주 꼿꼿하고 예민한 엘리트 성향입니다."},{"who":"렌","text":"나는 항복하지 않는다. 내 군인의 자존심은 서늘하고 굳건하다!"},{"who":"클레어","text":"(하이힐 소리, 또각) 중위님. 바닥에 엎드려서 제 구두코를 보세요."},{"who":"렌","text":"크윽… 굽이 높군. 전술적으로 내 명치와 전립선을 파괴하기에 최적화된 잔혹한 각도다."},{"who":"클레어","text":"파괴당할까 봐 두려우신가요. 그럼 가까이서 핥아 보시죠."}],"after":[{"who":"렌","text":"하아, 하아... 항복이 아니다. 단지 구두 굽의 재질을 혀로 전술 분석했을 뿐이다. 군복 하의가 터질 것 같은 건 착각이다."},{"who":"아네트","text":"체온 38.2도. 하복부 혈류량 200% 증가. 완벽한 발정 상태입니다."},{"who":"렌","text":"기록하지 마라! 나는 아직 굴복하지 않았...! (바들바들 떤다)"}],"stars":{"3":{"who":"아네트","text":"렌 중위님 합류. 체온 38.2도, 저항 의지 유지, 몸은 정직."},"2":{"who":"아네트","text":"합류 완료. 저항 의지는 유지되었으나 시선이 하이힐에 고정됩니다."},"1":{"who":"아네트","text":"합류했지만 아직 항복 의사를 밝히지 않았습니다. 단, 목줄은 풀지 않았습니다."}}},{"id":"F1-8","no":8,"title":"노예 팀 점호","boss":false,"before":[{"who":"아네트","text":"노예 팀 서열 정리입니다. 먼저 조교당한 톰 병장님이 선임, 렌 중위님이 후임입니다."},{"who":"렌","text":"군대 계급은 내가 중위로 훨씬 높다! 엎드려 뻗쳐라, 병장!"},{"who":"아네트","text":"여기는 계급보다 '누가 먼저 주인의 발밑에서 기었는가'가 우선입니다."},{"who":"톰","text":"렌 후임님, 제 담요 좀 개어 주시겠어요? 예쁘게 개면 제가 선임으로서 머리 쓰다듬으면서 엉덩이 한 대 때려드릴게요."},{"who":"렌","text":"큭... 그딴 굴욕적인 보상은... 읏, 해 주길 바란다. 담요 각은 내가 완벽하게 잡지."}],"after":[{"who":"톰","text":"렌 중위님, 담요 접는 솜씨가 훌륭합니다."},{"who":"렌","text":"당연하다. 군인은 모서리를 맞춘다. (귀 끝이 붉어진다)"},{"who":"그레타","text":"후임이 칭찬받고 얼굴이 빨개지는 건 처음 보는구만."},{"who":"클레어","text":"팀워크가 형성되고 있네요. 내일 보스전을 앞두고 안심됩니다."}],"stars":{"3":{"who":"아네트","text":"점호 완벽. 담요 모서리 오차 0."},"2":{"who":"아네트","text":"점호 양호. 후임 얼굴 붉음 정도 중."},"1":{"who":"아네트","text":"점호 지연. 선후임 간 대화가 길어졌습니다."}}},{"id":"F1-9","no":9,"title":"전야의 점검","boss":false,"before":[{"who":"아네트","text":"내일 보스전을 앞두고 구속구의 장력을 점검합니다."},{"who":"톰","text":"네, 신경이 끊어지기 직전까지 꽉 조여주세요. 고통이 없으면 잠이 안 와서요."},{"who":"렌","text":"나는 점검 필요 없다. 헐거운 게 효율적이다. ...아니, 사실 방금 숨이 막힐 정도로 조여졌으면 좋겠다고 생각했다."},{"who":"아네트","text":"렌 중위님, 장력 82%입니다. 더 조일까요?"},{"who":"렌","text":"필요 없다! ...해주십시오."}],"after":[{"who":"톰","text":"푹 잘 수 있겠네요. 렌 중위님도 담요 덮으세요."},{"who":"렌","text":"덮겠다. (이불 속에서 작게) …따뜻하다."},{"who":"클레어","text":"모두 좋은 밤 되세요. 내일은 큰 배입니다."}],"stars":{"3":{"who":"아네트","text":"점검 전원 합격, 수면 상태 양호."},"2":{"who":"아네트","text":"점검 합격, 일부 대원이 잠들기까지 오래 걸렸습니다."},"1":{"who":"아네트","text":"일부 족쇄 재조정이 필요합니다. 야간 근무자를 배치합니다."}}},{"id":"F1-10","no":10,"title":"철갑 바다코끼리","boss":true,"before":[{"who":"제독(목소리)","text":"짐은 투항하지 않는다! 내 전함이 침몰하더라도 끝까지 싸우겠다! 아, 참고로 야전 상담소 대기 번호는 1번으로 뽑아뒀다!"},{"who":"아네트","text":"투항도 안 하시면서 번호표는 제일 먼저 뽑으셨네요."},{"who":"제독(목소리)","text":"전투 중에 내 살갗이 찢어지면 가장 먼저 에테르 채찍 치료를 받아야 하니까! 긴장해서 목소리가 떨리는 거다!"}],"after":[{"who":"제독(목소리)","text":"졌다! 훌륭하게 짓밟혔다! 당장 내 하의를 찢고 1번 대기실로 압송해라!"},{"who":"클레어","text":"1장 종료입니다. 훌륭한 웰니스의 밤이군요."},{"who":"톰","text":"제독님 엉덩이에 멍이 아주 예쁘게 들었네요. 훈장 같습니다."}],"stars":{"3":{"who":"아네트","text":"제독 포획. 대기 번호 1번 확정, 접수 완료."},"2":{"who":"아네트","text":"상륙함 격침. 제독은 구명정으로 이탈 중, 곧 재접수가 예상됩니다."},"1":{"who":"아네트","text":"상륙함이 반파되었습니다. 제독은 아직 바다 위에서 대기 중입니다."}}}]},"F2":{"chapter":"F2","title":"공방 전선","line":"female","episodes":[{"id":"F2-1","no":1,"title":"잠든 공장의 점호","boss":false,"before":[{"who":"아네트","text":"연방 북부 폐공장 단지입니다. 제국이 증기 갑주 공방으로 개조했어요. 일일 신경망 점검부터 하겠습니다. 톰 병장님, 렌 중위님, 하복부 수축 상태 보고."},{"who":"톰","text":"최상입니다. 어제 담요 속에서 몸을 둥글게 말고 잤고요, 오늘 아침엔 목을 옥죄는 초커가 안 채워져 있어서 혈류가 도무지 안정되질 않아 매우 불안했습니다."},{"who":"렌","text":"이상 없다. 다만 어젯밤 이후로 내 허벅지 안쪽 근육이 통제 불능으로 떨린다. 이것은 군인의 자존심이 추위를 타는 것일 뿐, 절대 결박에 대한 갈망이 아니다."},{"who":"클레어","text":"공방 근처라 기온이 꽤 높고 후끈한데요."},{"who":"렌","text":"…군인의 자존심이 춥다고 했다."},{"who":"제국 병사들","text":"(하반신이 훤히 드러난 훈도시 장갑복 차림으로 우르르 등장) 크하하! 여기서부터는 지나갈 수 없다!"},{"who":"그레타","text":"가슴팍에만 철판을 덧대놓고 아래는 천 한 장 덜렁거리구만. 언제든 걷어차일 준비가 된 훌륭한 변태들이야."},{"who":"실비아","text":"정중하게 말씀드립니다. 시선을 어디에 둬야 할지 명확히 정했습니다. 저 천 조각 너머의 중심부로 가겠습니다."}],"after":[{"who":"그레타","text":"장갑이 위에만 있으니 정작 찰지게 두들겨 팰 맛이 안 나서 허탈하구만."},{"who":"아네트","text":"포획 인원 20명, 전원 하반신 방어력 0%. 즉시 집중 훈육 상담소로 이송합니다."},{"who":"톰","text":"추울까 봐 담요라도 덮어드릴까 했는데, 다들 하반신이 노출된 채로 수치심에 전율하며 너무 만족한 표정이라 뭘 덮어드려야 할지 모르겠네요."},{"who":"렌","text":"나는 아직 자존심이 춥다."}],"stars":{"3":{"who":"아네트","text":"포획 완벽, 병사 전원 번호표 수령."},"2":{"who":"아네트","text":"포획 양호. 일부 병사가 훈도시를 잃고 자진 이송되었습니다."},"1":{"who":"아네트","text":"포획 지연. 천 한 장의 방어력이 의외로 높았습니다."}}},{"id":"F2-2","no":2,"title":"벨트 없는 사수","boss":false,"before":[{"who":"아네트","text":"공장 지붕 위 제국 사수들입니다. 모두 가죽 멜빵으로 총을 단단히 고정하고 하복부의 긴장을 풀고 있어요."},{"who":"실비아","text":"예의 바르게 말씀드리겠습니다. 저 팽팽한 가죽 멜빵 끈만 정확히 끊겠습니다. 방아쇠는 건드리지 않습니다."},{"who":"제국 사수","text":"끈이 끊어지면 하의가 바닥까지 흘러내려서 총을 못 들잖아!"},{"who":"실비아","text":"총을 못 들어서 양손이 비게 되면, 비어 있는 손으로 다른 걸 감싸 쥘 수 있습니다."},{"who":"그레타","text":"무슨 뜻이야."},{"who":"실비아","text":"바닥에 주저앉아 수치스럽게 노출된 본인의 하반신을 가리라는 뜻으로, 문자 그대로입니다."}],"after":[{"who":"제국 사수","text":"(바지가 벗겨진 채 주저앉아) 총이 바닥에 떨어졌다. 이제 난 무방비한 상태로 뭘 들면 되지?"},{"who":"아네트","text":"이쪽에 묵직한 구속용 초커가 있습니다. 스스로 목에 걸어 보시겠어요?"},{"who":"제국 사수","text":"(덜덜 떨며) 들겠습니다."},{"who":"실비아","text":"감사합니다. 무혈입성으로 하반신을 무력화시킨 정중한 일 처리였습니다."}],"stars":{"3":{"who":"아네트","text":"끈 절단 100%, 방아쇠 손상 0."},"2":{"who":"아네트","text":"끈 절단 양호. 일부 사수가 총을 놓고 바지를 붙들었습니다."},"1":{"who":"아네트","text":"끈 절단 일부 실패. 사수 한 분이 아직 총을 안고 계십니다."}}},{"id":"F2-3","no":3,"title":"컨베이어는 멈추지 않는다","boss":false,"before":[{"who":"클레어","text":"이 공장 컨베이어는 24시간 돌아갑니다. 멈추려면 중앙 레버를 내려야 해요."},{"who":"그레타","text":"레버 위에 제국 병사들이 알몸으로 줄줄이 실려 오는구만. 벨트 위에서 수치 플레이를 할 순 없지."},{"who":"톰","text":"벨트가 꽤 빠르네요. 제 담요 위에 얌전히 무릎 꿇고 결박된 채로 실려 가면 어떨까요?"},{"who":"렌","text":"담요는 공장 부품이 아니다. 그런 굴욕적인 자세로 앉지 마라."},{"who":"아네트","text":"벨트 속도 시속 12킬로. 병사가 수치심에 다리가 풀려 넘어지면 그대로 용광로행입니다."},{"who":"제국 병사","text":"우릴 용광로로 보내서 태워버릴 셈이냐!"},{"who":"그레타","text":"안 보내. 교차로를 틀어서 자비 없는 웰니스 상담소로 직행하게 뺄 거다."}],"after":[{"who":"클레어","text":"레버를 내렸습니다. 공장이 고요해졌군요."},{"who":"제국 병사","text":"(벨트 위에서 허우적대며) 컨베이어가 서니까 갑자기 하복부가 너무 허전합니다. 우리를 포박한 채로 다시 돌려 주시면 안 됩니까?"},{"who":"아네트","text":"가장 예민한 감각을 긁어내도록 천천히 돌릴 수는 있습니다. 시속 3킬로로요."},{"who":"제국 병사","text":"그 속도면 제가 얼마든지 엉덩이를 치켜들고 올라탈 수 있습니다!"}],"stars":{"3":{"who":"아네트","text":"레버 정지 성공, 병사 이탈 0."},"2":{"who":"아네트","text":"정지 성공. 병사 몇 명이 벨트 끝까지 갔다 오셨습니다."},"1":{"who":"아네트","text":"정지가 늦었습니다. 용광로 앞에서 병사 대기열이 생겼습니다."}}},{"id":"F2-4","no":4,"title":"용광로 앞의 변명","boss":false,"before":[{"who":"아네트","text":"용광로 구역입니다. 기온 41도. 렌 중위님, 오늘도 점막이 달아올라 몸이 떨리시나요?"},{"who":"렌","text":"절대 떨리지 않는다. 이건 극도의 전술적 열기에 따른 단순한 생리적 땀 분비일 뿐이다."},{"who":"톰","text":"쾌락에 의한 떨림이 아니고 땀이었군요. 저도 지금 피부 감각이 예민해져서 땀이 납니다. 담요 벗을게요."},{"who":"렌","text":"벗지 마라. 자네는 연방의 도구로서 옷이 갈기갈기 찢겨나갈 때까지 그 담요를 놓으면 안 된다."},{"who":"그레타","text":"의외로 꽤 변태적인 배려심이 있구만."},{"who":"제국 병사","text":"이 온도에선 우리 갑주가 발정기 짐승처럼 열을 받아 무조건 돌진한다! 크하하!"},{"who":"클레어","text":"열받아서 날뛰는 신경계는 급속 냉각으로 교란해 드리는 게 예의죠. 그레타, 냉각제 투척."}],"after":[{"who":"렌","text":"(얼어붙은 채 바들바들 떨며) 식은 건 제국의 갑주만이 아니다. 내 군인의 마음도 차갑게 냉정해졌다."},{"who":"아네트","text":"체온 38.7도. 겉은 얼어붙었지만 속은 쾌락으로 완전히 끓어오르고 계십니다."},{"who":"렌","text":"이 끓는 피는 내 마음과 철저히 무관하다."},{"who":"톰","text":"마음은 몰라도 손은 떨리시는데, 잡아 드릴까요?"},{"who":"렌","text":"…단단히 잡아라."}],"stars":{"3":{"who":"아네트","text":"냉각 완벽, 대원 체온 전원 정상(렌 중위 제외)."},"2":{"who":"아네트","text":"냉각 양호. 용광로 앞 병사 일부가 열기에 만족하고 계십니다."},"1":{"who":"아네트","text":"냉각 불량. 용광로 근처 대기열이 과열되었습니다."}}},{"id":"F2-5","no":5,"title":"폭주하는 드워프","boss":false,"before":[{"who":"아네트","text":"제국 공병 상사 이그니스가 증기 갑주를 입은 채 폭주 중입니다. 갑주 안에서 11일째 갇혀 피학적 억압 상태라는 보고입니다."},{"who":"이그니스","text":"(확성기) 내가 이 갑주를 만든 장본인이다! 내 비루한 육체를 완전히 통제하는 이 갑주에서 내려갈 일은 평생 없다!"},{"who":"그레타","text":"참다못해 속이 뒤틀리고 꽉 막힌 더부룩한 목소리구만."},{"who":"바르샤","text":"(망치로 갑주를 쾅) 물리적 개방이 불편하다."},{"who":"클레어","text":"연방 공병 바르샤 씨도 동의하시는군요. 억압된 껍데기를 강제로 열어 보죠."},{"who":"이그니스","text":"열 필요 없다! 이 갑주를 강제로 개방하면 내 비천한 M의 자존심이 밖으로 왈칵 새어 나온다!"},{"who":"아네트","text":"자존심 말고도 11일 동안 억눌린 다른 배설물(?)이 새어 나올 것 같은데요."}],"after":[{"who":"바르샤","text":"(망치로 갑주를 강제로 뜯어내며 쾅) 열었다."},{"who":"이그니스","text":"(알몸으로 웅크린 채) 으윽, 후, 후우…… 11일이다. 11일 동안 이 미친 압박감 속에서 버텼다."},{"who":"그레타","text":"답답하던 속은 좀 뚫렸고?"},{"who":"이그니스","text":"속이라니 무슨 소리냐! …정확히 말하면 신경망이 꽉 막혀 터지기 직전이다."},{"who":"클레어","text":"집중 치료가 필요하겠군요. 다음 시간에 특별 조련 상담소로 모시겠습니다."}],"stars":{"3":{"who":"아네트","text":"갑주 개방 성공, 이그니스 상사 의식 양호."},"2":{"who":"아네트","text":"개방 성공. 상사님이 갑주 안에서 비명을 지르셨습니다."},"1":{"who":"아네트","text":"개방이 늦어졌습니다. 갑주 내 환경이 위험해졌습니다."}}},{"id":"F2-6","no":6,"title":"핑크 패들 찜질 + 대청소","boss":false,"before":[{"who":"아네트","text":"이그니스 상사의 폭주 원인을 확인했습니다. 11일 연속 피학적 억압에 따른 만성 변비와 신경 교란입니다."},{"who":"클레어","text":"…미친 폭주의 원인이 하복부 압력 팽창이었군요."},{"who":"그레타","text":"압력 밸브가 막혀서 성질이 터진 거구만. 드워프 놈들은 엉덩이 쪽이 꽉 막히면 성질도 같이 막히는 법이야."},{"who":"바르샤","text":"(망치로 갑주를 쾅) 막혔다."},{"who":"이그니스","text":"(확성기로) 연방에 투항은 없다! 열하루 동안 억눌러 온 이 철의 의지와 인내심으로 끝까지 버티겠다!!"},{"who":"클레어","text":"열하루 동안 배출하지 못하고 쌓아둔 것은 의지가 아닌 것 같습니다."},{"who":"제국 병사","text":"(방독면 착용) 상사님 곁에는 도저히 못 가겠습니다. 시큼한 열기에 눈이 따갑고 코가 막혀서……"},{"who":"그레타","text":"이 무식한 억압 상태에 기가 막히는 건 이쪽이구만. 코가 썩는 건 덤이고."},{"who":"아네트","text":"치료는 두 단계입니다. 1단계 고전압 「핑크 패들 찜질」로 하복부 신경을 깨우고, 2단계 고압력 에테르 「대청소」로 완전히 뚫어버립니다."},{"who":"실비아","text":"아네트 씨. 예의 바르게 말씀드리겠습니다. 그 무자비한 패들 시연을 저에게 먼저 해주십시오. 가장 두꺼운 쪽으로 엉덩이에, 정중하게 부탁드립니다."},{"who":"클레어","text":"정중하게 쾌락을 구걸하시니 거절하기가 어렵군요. 하지만 이그니스 상사부터 물리치료 하시죠."},{"who":"톰","text":"저도 패들 찜질 순번표 받아도 됩니까?"},{"who":"아네트","text":"병장님은 3번이세요."},{"who":"렌","text":"나는 그런 천박한 치료는 필요 없다. …지금 몇 번까지 나갔나."},{"who":"아네트","text":"4번입니다."},{"who":"렌","text":"…표를 받겠다."}],"after":[{"who":"","kind":"stage","text":"(화면 밖: 짝—— 짝—— 쩌렁——)"},{"who":"이그니스","text":"으아앗! 아! 아아앙! …어? 어어? 뱃속에서 뭔가가 무자비하게 움직인다! 내 하복부 깊은 곳에서 거대한 무언가가 뚫고 출발한다!"},{"who":"그레타","text":"출발이라니, 네 장기가 폭주 기관차냐."},{"who":"아네트","text":"2단계 「대청소」 들어갑니다. 바르샤 공병님, 후미 압력 밸브 강제 개방 부탁드립니다."},{"who":"바르샤","text":"(망치로 밸브를 쾅) 자비 없이 열었다."},{"who":"","kind":"stage","text":"(화면 밖: 꾸르르르륵…… 뿌우우우웅——)"},{"who":"제국 병사","text":"(방독면 안에서 눈물을 쏟으며) 눈물이 납니다…… 상사님의 11일 치 억압된 쾌락과 배설물이 한꺼번에…… (털썩 기절)"},{"who":"이그니스","text":"(눈물 콧물 범벅이 되어) …열하루 만이다. 환희의 눈물이 난다. 전립선을 긁고 나가는 이 미친 카타르시스! 연방 만세다."},{"who":"그레타","text":"그렇게 질질 우는 건 장이 싹 비워져서 개운해서가 맞는 거지?"},{"who":"이그니스","text":"개운해서도 맞고, 살점이 터질 것 같은 핑크 패들의 타격감이 너무 황홀해서도 맞다. 제발 엉덩이에 한 번만 더 내려쳐 줄 수 있나!"},{"who":"아네트","text":"재방문 및 2차 대청소 예약은 목요일 아침, 식후로 잡아 놨습니다."},{"who":"실비아","text":"자, 이제 얌전히 기다린 제 차례입니다. (허리를 깊숙이 숙이며 둔부를 치켜든다) 뼈가 울리도록 정중하게 쳐 주시길 부탁드립니다."},{"who":"","kind":"stage","text":"(화면 밖: 짝-!)"},{"who":"실비아","text":"(숨을 들이마시며) …최고의 타격감이군요. 감사합니다. 한 번 더 정중하게 타격을 부탁드립니다."},{"who":"클레어","text":"그 지독한 변태적 정중함은 대체 어디서 배우신 겁니까."},{"who":"실비아","text":"연방의 엄격한 가정교육입니다. 점막이 원하는 물리적 고통은 항상 예의 바르게 요청하라고 배웠습니다."}],"stars":{"3":{"who":"아네트","text":"완벽한 배출입니다. 환자 만족도 최상, 방독면 반납률 100%, 재방문 예약 포함."},"2":{"who":"아네트","text":"배출 양호. 병사 몇 분이 환기 전에 쓰러지셔서 보상 처리가 필요합니다."},"1":{"who":"아네트","text":"배출이 늦어서 현장이 가득 찼습니다. 다음에는 방독면을 두 배 준비하겠습니다."}}},{"id":"F2-7","no":7,"title":"족쇄 점검 시간","boss":false,"before":[{"who":"아네트","text":"월례 족쇄 장력 점검의 날입니다. 톰 병장님, 렌 중위님, 앞으로."},{"who":"톰","text":"네, 목을 조르는 족쇄가 너무 헐거운 것 같습니다. 호흡이 가빠질 정도로 한계까지 조여 주시면 비로소 안심이 되겠는데요."},{"who":"클레어","text":"스스로 기도 압박을 더 세게 해달라고 비는 건 처음입니다."},{"who":"톰","text":"목줄이 헐거우면 제 비루한 가치가 버려진 것 같아 길을 잃는 기분이라서요. 딸이 어릴 때도 손을 꽉 쥐어 부서질 듯 잡아야 안심했거든요."},{"who":"렌","text":"나는 헐거워서 숨쉬기 편한 게 전술적으로 효율적이다. …아니, 숨이 막힐 정도로 조여져서 뇌내 산소가 부족해지는 게 극도의 효율이다."},{"who":"아네트","text":"렌 중위님, 장력 82%입니다. 규정인 90%에 한참 못 미치게 헐거우시네요."},{"who":"렌","text":"(뒷걸음질 치며) 필요 없다! …당장 내 목을 옥죄어 주십시오."}],"after":[{"who":"아네트","text":"신경망 조정 완료. 톰 병장님 92%, 렌 중위님 92%."},{"who":"렌","text":"(숨을 헐떡이며) 장력이 92%…… 목에 핏대가 서는 이 수치는 전술적으로 어떤 가학적 의미가 있나?"},{"who":"아네트","text":"있습니다. 주인의 구두 굽 3미터 안에서만 호흡이 허락된다는 절대 복종의 의미입니다."},{"who":"렌","text":"…그 압박감은 몹시 흥분되는 전술적 의미가 있군."}],"stars":{"3":{"who":"아네트","text":"점검 전원 합격. 장력 92%로 통일."},"2":{"who":"아네트","text":"점검 합격. 렌 중위님이 재조정을 요청하셨습니다."},"1":{"who":"아네트","text":"점검이 길어졌습니다. 조임 정도에 대한 의견 차가 있었습니다."}}},{"id":"F2-8","no":8,"title":"장인의 자존심","boss":false,"before":[{"who":"그레타","text":"이그니스. 네놈이 나와 같은 장인 계보에서 몽둥이질을 배웠다는 소문은 사실이구만."},{"who":"이그니스","text":"그레타 영감의 끔찍한 제자가 연방에 있다더니 너였군! 그 타격점도 못 찾는 둔탁한 망치질은 여전하냐!"},{"who":"그레타","text":"둔한지 안 둔한지는 네놈 엉덩이를 직접 두들겨 까보면 알지."},{"who":"바르샤","text":"(망치로 바닥을 쾅) 타격 쾌감 대결이다."},{"who":"클레어","text":"변태들의 대결이라고요. 심판은 아네트입니다."},{"who":"아네트","text":"평가 기준은 「누구의 타격음이 살점을 가장 찰지게 파고들어 교감신경을 울리는가」입니다."},{"who":"실비아","text":"비명과 타격음의 화음 평가라면 제가 귀가 밝습니다. 단 1데시벨의 오차도 없이 엄정하게 분석하겠습니다."}],"after":[{"who":"이그니스","text":"내가 졌다…… 저 둔탁한 망치가 내 점막의 박자를 너무 완벽하고 정확하게 쪼개버렸어."},{"who":"그레타","text":"네놈의 피학적 박자가 마음이 너무 급해서 스텝이 꼬인 거야. 내 망치로 뼈까지 울리게 한 번 맞아 보게."},{"who":"이그니스","text":"내 뼈를 부수겠다고? 내가 명색이 제국의 장인인데 감히 그런 무자비한 짓을!"},{"who":"그레타","text":"장인끼리의 교감과 훈육이야. 가볍고 찰지게 엉덩이 다섯 번."},{"who":"이그니스","text":"(얼굴을 붉히며 바지를 내린다) …겨우 다섯 번이면 내 갈증이 채워지겠나."}],"stars":{"3":{"who":"아네트","text":"망치 박자 완벽 일치, 장인 존중도 최상."},"2":{"who":"아네트","text":"박자 양호, 이그니스 상사의 불평이 접수되었습니다."},"1":{"who":"아네트","text":"박자 불일치. 두 분의 자존심 마찰로 현장이 소란스러워졌습니다."}}},{"id":"F2-9","no":9,"title":"전야의 냉각 작업","boss":false,"before":[{"who":"아네트","text":"내일은 보스전입니다. 오늘은 흥분한 대원 전원의 하복부 급속 냉각 작업을 하겠습니다. 순서대로 얌전히 번호표를 뽑으세요."},{"who":"톰","text":"저는 5번입니다. 담요를 꽉 끌어안고 극저온의 고통을 얌전히 기다리겠습니다."},{"who":"렌","text":"나는 7번이다. …왜 내 번호가 이렇게 굴욕적으로 앞당겨진 거지?"},{"who":"아네트","text":"대기 중 렌 중위님의 피학적 선호도 반응이 폭발해서 시스템이 앞당겼습니다."},{"who":"렌","text":"나는 그런 변태적인 선호도가 높지 않다."},{"who":"아네트","text":"차트에는 괄약근 수축률 「매우 높음」이라고 명확히 적혀 있습니다."},{"who":"렌","text":"당장 차트를 찢어버려라."}],"after":[{"who":"이그니스","text":"(멀리서 허겁지겁 뛰어오며) 헉헉, 내 하복부도 터질 것 같은데 나도 번호표 받을 수 있나?!"},{"who":"아네트","text":"이그니스 상사님은 대청소 재방문 환자시라 VIP 고문 우선권이 있습니다."},{"who":"바르샤","text":"(망치로 접수대를 쾅) 우선 타격 훌륭하다."},{"who":"클레어","text":"모두 좋은 밤 되세요. 내일은 아주 거대하고 무자비한 타이탄이 옵니다."}],"stars":{"3":{"who":"아네트","text":"냉각 작업 전원 완료. 대기 시간 평균 6분."},"2":{"who":"아네트","text":"냉각 작업 양호. 일부 대원 순서가 뒤바뀌었습니다."},"1":{"who":"아네트","text":"대기열이 과열되었습니다. 차트 정리가 필요합니다."}}},{"id":"F2-10","no":10,"title":"브레이저 타이탄","boss":true,"before":[{"who":"클레어","text":"이그니스 상사의 마지막 기체 「브레이저 타이탄」입니다. 높이 15미터, 거대한 용광로를 가슴에 탑재한 무식한 쇳덩어리네요."},{"who":"이그니스","text":"(확성기) 내 하복부 밸브는 대청소로 뻥 뚫렸지만, 엘리트 M으로서의 자존심은 아직 꽉 막혀 있다! 이 타이탄으로 마지막 발악 전투를 하겠다!"},{"who":"그레타","text":"막힌 게 자존심이면 타이탄 껍데기를 벗기고 본체 엉덩이를 직접 두들겨서 뚫어야지."},{"who":"바르샤","text":"(망치로 바닥을 쾅) 다 벗겨서 부수자."},{"who":"아네트","text":"제가 의료적으로 지원하겠습니다. 거대 기체용 1단계 고출력 전립선 패들, 2단계 대청소 펌프 준비 완료."},{"who":"이그니스","text":"기체에 대청소는 이제 필요 없다! 다만 내 맨살에 핑크 패들은 한 번 더…… 큭, 아니! 전투 중에 발정하면 안 된다!"}],"after":[{"who":"이그니스","text":"(기체에서 굴러떨어지며) 졌다. 완전히 무너졌다. 타이탄도 박살 나고 내 멘탈도 시원하게 박살 났다."},{"who":"그레타","text":"완전 항복이냐?"},{"who":"이그니스","text":"육체와 영혼 모두 항복이다. 다음 주 목요일 아침 식후 패들 찜질 예약 갱신했다. 상담소 위치는 내 몸이 똑똑히 기억하고 있다."},{"who":"클레어","text":"2장 종료입니다. 제국의 거친 공방이 연방의 완벽한 조련 구역이 되었군요."},{"who":"렌","text":"…혹시 이그니스 상사님의 패들 예약 번호가 제 앞이었나. 순서를 뺏길 순 없다."}],"stars":{"3":{"who":"아네트","text":"타이탄 파괴. 이그니스 상사 포획, 재방문 확정."},"2":{"who":"아네트","text":"타이탄 파괴. 상사님은 갑주를 벗고 자진 이송되었습니다."},"1":{"who":"아네트","text":"타이탄이 반파되었습니다. 상사님은 갑주 안에서 아직 버티고 계십니다."}}}]},"F3":{"chapter":"F3","title":"사막 통상로","line":"female","episodes":[{"id":"F3-1","no":1,"title":"통상로 개통식","boss":false,"before":[{"who":"클레어","text":"사막 통상로가 오늘부터 연방 관할입니다. 저희의 우아한 폭력성을 각인시킬 개통식을 겸한 전투가 되겠군요."},{"who":"톰","text":"아침 척수 자극 체조 끝났습니다. 제 목을 옥죄는 초커는 누가 명령하기도 전에 제가 먼저 바짝 조여 채웠어요. 숨이 턱 막히는 게 아주 완벽한 압박감입니다."},{"who":"아네트","text":"병장님, 스스로 피학의 굴레를 쓰시다니 기특하네요. 하복부에 칭찬 스티커(전극)를 하나 붙여 드리겠습니다."},{"who":"톰","text":"감사합니다. 이 짜릿한 전류의 맛을 나중에 딸에게 자랑할게요."},{"who":"렌","text":"나는 그런 천박한 체조를 한 적 없다. …전술적 유연성을 위해 근육의 긴장을 풀었을 뿐이다."},{"who":"그레타","text":"전술 타령을 하면서 얼굴은 당장이라도 걷어차이길 바라는 발정 난 표정이구만."},{"who":"제국 병사","text":"개통식이라니, 우리는 초대 못 받았다! 왜 우리만 쾌락에서 소외시키는 거냐!"},{"who":"클레어","text":"진정하세요. 강제 개방 초청장은 포획 후 하의를 벗길 때 발송해 드립니다."}],"after":[{"who":"아네트","text":"통로 개통 완료. 제국 병사 28명의 관절을 꺾어 포획 후, 고압 전류실 초대장을 발송했습니다."},{"who":"제국 병사","text":"초대장이 도착했다! 드디어 내 비루한 점막이 찢어질 상담소 예약권이다!"},{"who":"톰","text":"저렇게 애타게 고통을 갈구하는 걸 보니 이젠 이 기괴한 풍경도 참 아늑하네요."},{"who":"클레어","text":"결박과 유린의 루틴이 서면 전쟁도 평화로운 일상이 됩니다."}],"stars":{"3":{"who":"아네트","text":"개통식 완벽 진행, 방문객 만족도 최상."},"2":{"who":"아네트","text":"개통 성공. 초대장 일부가 사막 바람에 날아갔습니다."},"1":{"who":"아네트","text":"개통이 지연되었습니다. 의전 담당이 부족했습니다."}}},{"id":"F3-2","no":2,"title":"낙타 상단의 짐 검수","boss":false,"before":[{"who":"아네트","text":"제국 보급 낙타대입니다. 서류상의 짐 목록은 「모래 대비 식량」이라고 되어 있네요."},{"who":"그레타","text":"식량 치고는 박스 안에서 덜컥거리고 윙윙대는 진동 모터 소리가 아주 요란한데."},{"who":"제국 병사","text":"식량이다! 정말이다! 안에 든 건 식사용 가죽 끈, 방울 달린 구강 재갈, 그리고 후미 점막을 자극할 말랑한 고문 도구지만 아무튼 식량이다!"},{"who":"클레어","text":"저희 연방의 기준으로는 그것은 섭취 가능한 식량이 아닌 것으로 압니다."},{"who":"제국 병사","text":"사막은 길고 외롭다. 우리 제국군 M들도 밤에는 점막을 혹사하며 달래야 한단 말이다!"},{"who":"실비아","text":"정중하게 제안합니다. 저 말랑한 기구들이 괄약근을 뚫고 들어가는 탄성 검수는 제 저격용 꼬질대로 직접 쑤셔 확인하겠습니다."},{"who":"렌","text":"거절한다. 그건 제국의 군수품이다. 장교인 내가 직접 내 몸에 테스트하여 검수하겠다."},{"who":"그레타","text":"검수한다면서 중위 놈은 벌써 바지를 반쯤 내리고 포장을 뜯고 있구만."}],"after":[{"who":"아네트","text":"밀수품 압수 목록 정리. 재갈 12, 결박용 가죽 끈 40, 말랑한 점막 유린기 7."},{"who":"렌","text":"유린기는 전술 정보 파악을 위해 내가 압수하여 보관하겠다. 철저한 군 기밀이다."},{"who":"톰","text":"렌 중위님, 방금 가장 진동이 센 기구 하나를 소매에 은밀히 숨기셨습니다."},{"who":"렌","text":"(식은땀을 흘리며 허벅지를 꼬고) …전술적 보관이다."}],"stars":{"3":{"who":"아네트","text":"밀수품 전량 압수, 압수 목록 정리 완료."},"2":{"who":"아네트","text":"압수 양호. 일부 물품이 대원 소매로 이동했습니다."},"1":{"who":"아네트","text":"일부 물품이 모래 속에 묻혔습니다. 채굴 인력이 필요합니다."}}},{"id":"F3-3","no":3,"title":"자하라의 꼬리 감기","boss":false,"before":[{"who":"아네트","text":"제국 전차 앞에 사막 연금 길드 객원 자하라 씨가 서 있습니다. 하반신의 뱀 꼬리가 몹시 두껍고 기네요."},{"who":"자하라","text":"안녕하세요, 연방 여러분. 제국 의뢰로 이 전차를 지켜야 해서요. 꼬리로 목을 졸라 질식시키는 1회 쾌락 요금은 금화 3닢입니다."},{"who":"그레타","text":"그 미끈한 꼬리로 전차를 막는다고? 뼈가 으스러질 텐데 그게 되겠나."},{"who":"자하라","text":"(거대한 뱀 꼬리를 휘감아 전차 포신을 무자비하게 찌그러뜨린다) 되는데요. 이래 봬도 교감신경을 끊어버리는 조임 압력이 6기압입니다."},{"who":"클레어","text":"숨통을 끊어놓는 대단한 조임이군요. 예의상 홍차를 한 잔 권해도 될까요?"},{"who":"자하라","text":"호흡 곤란 홍차 요금은 별도입니다."},{"who":"실비아","text":"정중하게 평가합니다. 척추를 박살 내는 감는 각도가 아주 훌륭하십니다."}],"after":[{"who":"자하라","text":"이번엔 졌네요. 하지만 저는 포획되지 않습니다. 계약 해지 조항을 읽어 봤는데 저는 객원이라 강제 훈육 대상이 아니거든요."},{"who":"아네트","text":"객원이시면 정맥 주사 상담소 이용은 강제가 아니라 자유입니다. VIP 재방문 권유서만 드리겠습니다."},{"who":"자하라","text":"권유서는 무료인가요?"},{"who":"아네트","text":"무료입니다."},{"who":"자하라","text":"…가져가겠습니다. 쾌락 소장용으로."}],"stars":{"3":{"who":"아네트","text":"전차 정지, 자하라 씨 재방문 권유서 수령."},"2":{"who":"아네트","text":"전차 정지. 자하라 씨는 요금 청구서를 두고 갔습니다."},"1":{"who":"아네트","text":"전차가 꼬리에 감겨 아직 못 움직입니다. 원인 분석 중."}}},{"id":"F3-4","no":4,"title":"늑대 수인 카이단","boss":false,"before":[{"who":"아네트","text":"선두에서 늑대 수인이 짐승처럼 돌진해 옵니다. 이름은 카이단, 제국 최강의 거친 마초라는 소문입니다."},{"who":"카이단","text":"크아악! 연방의 고상한 암컷들아! 오늘은 내 이빨로 네년들의 피부에 굴복의 문장을 새겨 주마!"},{"who":"그레타","text":"저 거친 짐승의 급소를 조준하는 쪽은 실비아가 적격이구만."},{"who":"카이단","text":"저기 차갑고 단아한 암컷부터 내 밑에 깔고 먼저 물어뜯겠다!"},{"who":"실비아","text":"아주 정중하게, 당신의 전립선 3cm 옆을 쏴서 영구적인 신경 마비를 선물해 드리며 사양합니다."},{"who":"아네트","text":"카이단 씨, 짖지 말고 이쪽으로 오세요. 호흡을 통제하는 초커를 채워 드리겠습니다."},{"who":"카이단","text":"초커? 그딴 개목줄에 이 늑대님이 굴복할 것 같으냐! 나는 사냥개가 아니라 길들지 않은 늑대다!"}],"after":[{"who":"","kind":"stage","text":"(화면 밖: 철컥- 무거운 자성이 목을 콱 죈다)"},{"who":"카이단","text":"윽... 이게 뭐야, 목에 뭔가 묵직한 게 걸렸다. 으르릉…… 어? 핏대가 서고 혈류가 막히니까 뇌가 아찔해지면서... 헉, 헉... 이거 묘하게 엄청 편한데?"},{"who":"아네트","text":"카이단 씨 합류입니다. 고전압 정화방 일정은 다음 시간으로 잡겠습니다."},{"who":"카이단","text":"정화방은 안 간다! 내 피부를 찢는 장소는 내가 정한다!"},{"who":"클레어","text":"사육 규정은 모든 짐승에게 동일합니다."},{"who":"카이단","text":"(뒷다리를 달달 떨며 꼬리가 헬리콥터처럼 돌아간다) …지금 꼬리는 내 의지로 안 흔들었다."}],"stars":{"3":{"who":"아네트","text":"카이단 씨 합류. 초커 착용감 만족도, 꼬리 반응 우수."},"2":{"who":"아네트","text":"합류 완료. 정화방 거부 의사 표명 중."},"1":{"who":"아네트","text":"합류했으나 도주를 시도 중입니다. 족쇄 3미터 규정이 작동합니다."}}},{"id":"F3-5","no":5,"title":"깃털 간지럼의 사전 준비","boss":false,"before":[{"who":"아네트","text":"카이단 씨의 정화방 입실 전, 극도의 감각 교란을 위한 사전 준비 단계입니다. 예민한 깃털 부위 확인."},{"who":"카이단","text":"깃털이라니 무슨 소리냐! 내 털은 수컷 늑대의 거친 털이다!"},{"who":"아네트","text":"이쪽 깃털은 하피 상단에서 구입한 신경 자극용 최고급입니다. 교감신경을 긁어버리는 간지럼 감도 상위 5%죠."},{"who":"카이단","text":"(깃털이 살갗에 닿자마자) 크하하…… 아, 아, 으하하하하!! 흣! 거, 거기는 점막이 얇아서 안 된다!! 거긴 미쳐버려어어!"},{"who":"그레타","text":"마초 늑대가 허리를 꺾으며 이렇게 샐샐거리며 웃을 줄은 몰랐구만."},{"who":"카이단","text":"웃는 게 아니다! 신경이 타들어 가는 비명이다! 크하핫!! 그만, 멈추지 마!"},{"who":"실비아","text":"비명이라 하기에는 쾌락에 절여진 입꼬리가 귀까지 올라가 있는데요."}],"after":[{"who":"아네트","text":"사전 준비 완료. 고통을 참아내는 간지럼 내성 0%입니다."},{"who":"카이단","text":"헉, 헉... 쾌락 내성이 0이라고…… 그건 수컷으로서 전술적으로 너무나 치명적이고 위험하다."},{"who":"렌","text":"자네도 피부 감각 내성이 없나. 나와 완벽하게 똑같은 전술적 약점이군."},{"who":"카이단","text":"비루한 중위와 같은 약점이라니, 불쾌하다. …하지만 하복부가 달아오르는 끈적한 동지애가 느껴진다."}],"stars":{"3":{"who":"아네트","text":"간지럼 사전 준비 완벽, 웃음소리 120데시벨."},"2":{"who":"아네트","text":"준비 양호. 카이단 씨가 중간에 도망치려 했습니다."},"1":{"who":"아네트","text":"준비가 지연되었습니다. 깃털이 바람에 날아갔습니다."}}},{"id":"F3-6","no":6,"title":"정화방 탈출 작전","boss":false,"before":[{"who":"아네트","text":"카이단 씨가 정화방의 고문 기구를 보자마자 입실 직전에 도주했습니다. 지금 허접하게 변장 중입니다."},{"who":"카이단","text":"(커다란 헝겊을 뒤집어쓰고) 저는 짐을 나르는 평범하고 멍청한 낙타입니다! 낙타가 두 발로 걷는 건 사막에서 흔한 일입니다!"},{"who":"그레타","text":"낙타 귀가 쫑긋 선 늑대 귀구만."},{"who":"카이단","text":"아니다. 이건 주인님을 모시기 위한 낙타용 장식이다."},{"who":"톰","text":"늑대님, 많이 달아오르신 것 같은데 제 담요라도 덮어 드릴까요? 낙타도 수치심을 느낄 땐 담요를 쓰거든요."},{"who":"카이단","text":"담요는…… 시야가 가려져서 더 흥분된다. 아니다, 나는 도망 중이다!"},{"who":"클레어","text":"마도 족쇄 3미터 규정이 작동합니다. 아네트, 전류를 넣으세요."}],"after":[{"who":"카이단","text":"(목이 뒤로 꺾인 채 질질 끌려오며) 컥! 땅굴을 팠는데 정확히 3미터 지점에서 목줄이 내 척추를 부러뜨릴 듯 당겨졌다!"},{"who":"아네트","text":"주인의 발밑을 벗어나지 못하는 절대 규정입니다."},{"who":"카이단","text":"헉, 헉... 그럼 낙타 위장도, 땅굴도, 발악도 내 육체를 통제하는 주인의 목줄 앞에서는 다 소용없단 말인가!"},{"who":"클레어","text":"도주 시도는 소용이 있었습니다. 목줄에 끌려 바닥을 뒹구는 그 천박한 꼴을 아주 즐겁게 구경했거든요."},{"who":"카이단","text":"…살갗이 찢어지는 정화방은 안 간다고 했다. (스스로 문을 열며)"}],"stars":{"3":{"who":"아네트","text":"탈출 시도 5회 모두 저지, 관람 만족도 최상."},"2":{"who":"아네트","text":"저지 4회. 1회는 가발만 놓고 도주했습니다."},"1":{"who":"아네트","text":"저지 지연. 카이단 씨가 사막 한가운데서 길을 잃으셨습니다."}}},{"id":"F3-7","no":7,"title":"다녀오더니","boss":false,"before":[{"who":"아네트","text":"카이단 씨가 고전압 정화방 입실을 마쳤습니다. 완전히 함락당하기까지 소요 시간 단 18분."},{"who":"그레타","text":"고작 18분 만에 멘탈이 녹아버렸구만. 어디 보자, 표정이 얼마나 썩었는지."},{"who":"카이단","text":"(문이 열리고, 혀를 길게 빼문 채 네 발로 기어 나오며) 헉, 헉… 주인님! 목줄 꽉 쥐고 산책 가요!"},{"who":"그레타","text":"이 눈 돌아간 개새끼는 누구냐."},{"who":"카이단","text":"(엉덩이를 흔들며 꼬리가 쉬지 않고 돌아간다) 저는 주인님의 비루한 발판 카이단입니다! 주인님, 제 목을 조르는 초커 너무 완벽하게 어울리죠? 내일도 제 점막을 제일 먼저 찢어주세요!"},{"who":"클레어","text":"가학적 뇌내 세뇌 효과가 아주 뚜렷하고 훌륭하군요."},{"who":"렌","text":"이럴 수가. 최강의 마초가 불과 18분 만에 짐승의 본능을 잃고 자발적 가축이 되다니."},{"who":"카이단","text":"렌 중위님, 눈치 보지 말고 같이 가요! 뼈가 부서지는 정화방 진짜 최고로 좋아요!"},{"who":"렌","text":"…나는 저런 천박한 꼴로 엎드리지 않는다. 몸이 고통에 먼저 반응할 뿐이지 마음은 아직 군인이다."}],"after":[{"who":"카이단","text":"주인님, 제 등을 밟고 칭찬해 주세요! 오늘도 제국 놈들 열 명의 목통을 물어뜯었어요!"},{"who":"클레어","text":"아주 잘하셨어요, 저의 충실한 카이단 씨. (군화 코로 턱을 들어 올리며 머리를 쓰다듬는다)"},{"who":"카이단","text":"크응, 크응…… 하아앙! (바닥에 엎드려 꼬리가 바닥을 쓸어버릴 정도로 흔든다)"},{"who":"그레타","text":"원래 맞고 구르는 걸 좋아하는 태생부터 글러 먹은 놈이었던 것 같구만."},{"who":"톰","text":"매 맞는 게 습관이 되면 가축으로서의 삶이 아주 편해지고 행복해지는군요."}],"stars":{"3":{"who":"아네트","text":"카이단 씨 멍뭉이 모드 100%, 꼬리 진동 120회/분."},"2":{"who":"아네트","text":"멍뭉이 모드 80%. 가끔 마초 모드가 복귀합니다."},"1":{"who":"아네트","text":"모드 불안정. 정화방 재방문 권유서를 발송합니다."}}},{"id":"F3-8","no":8,"title":"렌의 신념","boss":false,"before":[{"who":"아네트","text":"렌 중위님, 오늘 점막 파열 정화방 예약이 잡혀 있습니다."},{"who":"렌","text":"나는 굴복하지 않았다. 주인의 채찍을 보고 몸의 세포가 먼저 발정했을 뿐이다. 내 숭고한 정신은 무사하다는 점을 반드시 기록해 두길 바란다."},{"who":"아네트","text":"정확히 기록했습니다. 「하반신은 주인의 발밑으로 먼저 감, 마음은 입으로만 저항 중」."},{"who":"카이단","text":"렌 중위님, 센 척하지 말고 마음도 같이 바닥에 던져요! 저는 마음도 수치심도 다 같이 하수구에 버렸어요!"},{"who":"렌","text":"마음은 제국 군인의 마지막 보루다. 육체가 유린당할지언정 정신은 쉽게 내줄 수 없다."},{"who":"톰","text":"지킬 보루가 아직 남아 있으신 중위님은 참 대단하십니다. 저는 포박당한 첫날에 영혼까지 다 내줬습니다."},{"who":"그레타","text":"군인의 보루 운운하는 중위 놈의 예약 순번표가 7번이구만. 아주 헐레벌떡 뛰어가서 뽑았어."}],"after":[{"who":"렌","text":"(단추가 다 뜯겨나간 제복을 걸치고 비틀거리며) 헉, 헉... 다녀왔다. …내 몸엔 이상 없다. 안에서 아무 일도... 아무런 굴욕도 없었다."},{"who":"아네트","text":"체온 39도, 심박수 120, 괄약근 완전 이완 상태입니다. 쾌락에 절여지셨군요."},{"who":"렌","text":"그, 그건... 고강도 전술 훈련에 따른 군인의 단순 피로다."},{"who":"카이단","text":"렌 중위님 귀끝부터 목덜미까지 쾌감에 새빨개요! 목줄 덜덜거리면서 저랑 같이 네 발로 산책해요!"},{"who":"렌","text":"산책은…… 기어서 한 바퀴만이다."}],"stars":{"3":{"who":"아네트","text":"렌 중위님 신념 유지(표면), 몸 반응 정직."},"2":{"who":"아네트","text":"신념 유지. 퇴실 후 몸이 더 자주 떨립니다."},"1":{"who":"아네트","text":"신념에 균열 발생. 다음 예약을 앞당기겠습니다."}}},{"id":"F3-9","no":9,"title":"모래폭풍 전야","boss":false,"before":[{"who":"클레어","text":"내일은 거대한 장갑 열차 군단과 맞섭니다. 오늘 밤은 텐트를 날려버릴 모래폭풍이 예보되었네요."},{"who":"톰","text":"결박용 담요가 5장입니다. 춥고 무력하게 대원 수대로 나눠 덮어 드릴게요."},{"who":"카이단","text":"저는 클레어 주인님 구두 옆에 웅크리고 누울래요! 개는 원래 주인 발밑에 무리 지어 자니까요!"},{"who":"렌","text":"나는 텐트 가장자리에서 자겠다. …가장자리는 춥고 외로워서 내 피학 본능을 자극하니까."},{"who":"그레타","text":"가운데 놔두고 굳이 걷어차이기 좋은 중위 옆자리를 비워 뒀구만."},{"who":"렌","text":"비워 둔 건 나를 짓밟기 위한 배려로 감사히 받아들이겠다."}],"after":[{"who":"아네트","text":"폭풍 속에서도 전원 주인의 통제 아래 안전합니다."},{"who":"톰","text":"채찍 소리 대신 모래 치는 소리가 파도 같아서 좋네요. 딸이 파도를 참 좋아했거든요."},{"who":"카이단","text":"크응…… (주인의 군화를 베고 입에 거품을 문 채 잠든다)"},{"who":"클레어","text":"아름다운 결박의 밤입니다. 내일은 열차를 박살 내죠."}],"stars":{"3":{"who":"아네트","text":"야영 만족도 최상, 담요 배분 오차 0."},"2":{"who":"아네트","text":"야영 양호. 담요 몇 장이 모래에 파묻혔습니다."},"1":{"who":"아네트","text":"모래폭풍으로 텐트 일부가 날아갔습니다."}}},{"id":"F3-10","no":10,"title":"제국 장갑 열차 군단","boss":true,"before":[{"who":"클레어","text":"사막 한가운데로 무식하게 들이받는 제국 장갑 열차 군단. 육중한 10량 편성입니다."},{"who":"제국 기관사","text":"(확성기) 우리 열차는 하복부 연료도 속도도 최고로 발정 났다! 쾌락을 향한 브레이크는 완전히 고장 났다!"},{"who":"그레타","text":"브레이크 고장 난 열차로 그대로 처박혀서 어쩌겠다는 거구만."},{"who":"제국 기관사","text":"우리가 그쪽 진영에 도달해서 처박히면 최고급 정화 상담소 문을 열어 줄 거라 들었다! 내 몸을 찢어달라!"},{"who":"아네트","text":"고문실 오픈 소문이 참 빠르네요."},{"who":"카이단","text":"주인님, 제가 저 미친 열차 쫓아가도 돼요? 쫓아가서 맨몸으로 부딪혀 물어 오고 싶어요!"},{"who":"렌","text":"허가한다. 아니, 돌격해서 산산조각 날 허가를 감히 주인님께 구한다."}],"after":[{"who":"제국 기관사","text":"(피투성이가 되어 뒹굴며) 졌다! 통쾌하게 박살 났다! 하지만 브레이크가 없어서 내 쾌락의 질주는 멈추지 않고 계속 상담소로 달려간다!"},{"who":"그레타","text":"이미 박살 났는데 저걸 누가 멈추나."},{"who":"카이단","text":"제가 맨몸으로 깔리러 갈게요! (침을 흘리며 열차 쪽으로 미친 듯이 달려간다)"},{"who":"클레어","text":"3장 종료입니다. 모래 먼지 날리는 통상로가 연방의 완벽한 조련장 소유가 되었군요. 카이단 씨, 다치지 않게 적당히 깔리고 얌전히 돌아오세요."},{"who":"톰","text":"마초 늑대가 육중한 쇳덩어리 열차에 깔리며 쾌감을 잡아 오는 변태적인 장면은 처음 봅니다."}],"stars":{"3":{"who":"아네트","text":"열차 군단 정지, 카이단 씨 무사 귀환, 꼬리 진동 최대."},"2":{"who":"아네트","text":"열차 정지. 카이단 씨가 모래 먼지를 뒤집어쓰고 돌아오셨습니다."},"1":{"who":"아네트","text":"열차가 사막 끝까지 달렸습니다. 회수 작업을 시작합니다."}}}]},"F4":{"chapter":"F4","title":"야간 점호","line":"female","episodes":[{"id":"F4-1","no":1,"title":"야간 점호의 예약 전쟁","boss":false,"before":[{"who":"아네트","text":"도심에 밤이 내렸습니다. 야간 하복부 긴장도 점호를 시작합니다. 톰 병장님, 렌 중위님, 카이단 씨, 번호 순서대로 보고하세요."},{"who":"톰","text":"1번 톰입니다. 오늘 밤 피부를 찢는 정화방 예약, 이미 가장 먼저 걸어 뒀습니다."},{"who":"카이단","text":"2번 카이단! 저도 걸었어요! 3번 렌 중위님은 자존심 세우며 안 걸었는데 제가 강제로 묶어서 대신 걸어 놨어요!"},{"who":"렌","text":"크윽... 누가 내 번호를 맘대로 걸었나. …하지만 이미 등록된 이상 취소하는 건 군인의 수치다. 결코 내가 바라는 게 아니다."},{"who":"그레타","text":"뼈와 살이 분리되는 예약이 이미 이틀 치나 꽉 차 있구만."},{"who":"클레어","text":"피학의 수요가 많다는 건 그만큼 저희 유린 서비스가 좋다는 증거죠."},{"who":"제국 병사","text":"(네 발로 기어오며) 우리도 예약하고 싶다! 살갗을 찢어줄 줄이 어디냐!"}],"after":[{"who":"아네트","text":"오늘 포획 22명. 육체 개조 예약 대기 78명. 억압할 인력이 부족합니다."},{"who":"톰","text":"저희가 무릎으로 기어 다니며 번호표를 나눠 줄까요? 철저히 비천한 봉사 활동이라고 생각하고요."},{"who":"렌","text":"번호표 배부는 장교의 임무다. 내가 맡겠다. (바들바들 떨며 자신의 번호표를 맨 위에 슬쩍 넣는다)"},{"who":"카이단","text":"렌 중위님이 새치기하셨어요!"},{"who":"렌","text":"…이건 철저히 쾌락을 향한 전술적 우선순위다."}],"stars":{"3":{"who":"아네트","text":"점호 완벽, 예약 정리 100%, 새치기 적발 0."},"2":{"who":"아네트","text":"점호 양호. 새치기 1건 발생."},"1":{"who":"아네트","text":"예약 대기 혼잡. 상담소 앞 줄이 골목 하나를 막았습니다."}}},{"id":"F4-2","no":2,"title":"가로등 아래의 방문 판매","boss":false,"before":[{"who":"아네트","text":"제국 야간 노점상이 가로등 아래에서 음탕한 도구를 팔고 있습니다. 상호는 「심야 철물점」."},{"who":"노점상","text":"어서 오세요! 오늘의 추천은 살점을 파고드는 쫀득 채찍과 타액 분비를 돕는 귀여운 방울 재갈입니다!"},{"who":"그레타","text":"전장 한복판에서 장사가 저렇게 자연스러우니 오히려 말릴 수가 없구만."},{"who":"실비아","text":"정중하게 질문합니다. 그 쫀득 채찍의 손잡이 소재가 제 손아귀의 마찰을 얼마나 견딜 수 있는지요."},{"who":"노점상","text":"사막 코끼리 가죽입니다. 손에 착 감기며 아주 서늘한 타격감을 선사하죠."},{"who":"실비아","text":"훌륭하군요. 구매하겠습니다. 영수증 부탁드립니다."},{"who":"클레어","text":"실비아, 지갑은 나중에 여세요. 오늘은 전투입니다."},{"who":"실비아","text":"전투 후 구매로 하겠습니다. 제 몫의 채찍 하나 예약 부탁드립니다."}],"after":[{"who":"노점상","text":"전원 포획이라니, 앗! 제 고문 도구 가게는 어떻게 되는 겁니까?"},{"who":"아네트","text":"연방의 특별 정화 상담소 안에 입점하셔도 됩니다. 임대료는 월말에 포로들의 쾌락 지수로 정산합니다."},{"who":"노점상","text":"입점이라니, 제 변태적 상술이 빛을 발하는 영광입니다."},{"who":"클레어","text":"연방과 제국의 첫 하드코어 합작 가게가 되겠군요."}],"stars":{"3":{"who":"아네트","text":"노점상 입점 확정, 쫀득 채찍 재고 확보."},"2":{"who":"아네트","text":"입점 확정. 방울 재갈 재고 일부 손실."},"1":{"who":"아네트","text":"점포 철수 중 일부 상품이 분실되었습니다."}}},{"id":"F4-3","no":3,"title":"노예 부대의 첫 전선","boss":false,"before":[{"who":"클레어","text":"오늘은 조련된 노예 부대가 처음으로 최전선에 섭니다. 톰, 렌, 카이단."},{"who":"톰","text":"알겠습니다. 방패 대신 제 굴욕의 상징인 결박 담요를 덮어쓰고 가겠습니다."},{"who":"카이단","text":"주인님 구두 곁이면 진흙탕이든 어디든 핥으며 갈게요!"},{"who":"아네트","text":"마도 족쇄 3미터 규정이 중요합니다. 주인의 발밑에서 3미터 이상 떨어지면 즉시 신경계가 강제로 당겨집니다."},{"who":"렌","text":"그럼 우리 세 명이 서로 다른 방향으로 달리면 이 목줄이 어떻게 되나."},{"who":"아네트","text":"숨이 막힌 채 줄이 엉켜 서로 중앙으로 처박히며 모이게 됩니다."},{"who":"렌","text":"그건 결국 서로 땀내 나는 살을 맞대고 부둥켜안게 된다는 뜻이다."},{"who":"그레타","text":"전장 한복판에서 남자 셋이 부둥켜안고 뒹구는 미친 전술이구만."}],"after":[{"who":"카이단","text":"렌 중위님, 우리 목줄이 꼬였어요! 엉켜서 숨이 막히는데 묘하게 따뜻해요!"},{"who":"렌","text":"헉, 헉... 이건 전술적 근접전이다. …숨이 막혀 죽을 것 같지만 굳이 풀어 달라고는 안 하겠다."},{"who":"톰","text":"저도 같이 엉켜 있겠습니다. 서로 수치심을 덮어주는 담요가 되니까요."},{"who":"아네트","text":"엉킨 줄 정리는 5분 걸립니다. 그 사이 바닥에서 서로의 체온을 느끼며 쉬세요."}],"stars":{"3":{"who":"아네트","text":"첫 전선 완수, 줄 엉킴 만족도 최상."},"2":{"who":"아네트","text":"전선 완수. 엉킴 해소에 7분이 걸렸습니다."},"1":{"who":"아네트","text":"줄 엉킴이 과도해 이동이 지연되었습니다."}}},{"id":"F4-4","no":4,"title":"옥상 정화 파티","boss":false,"before":[{"who":"클레어","text":"도심 옥상에 제국 병사들이 알몸으로 집결했습니다. 그 꼴을 구경하러 연방 시민들도 몰렸군요."},{"who":"연방 시민","text":"오늘도 제국 놈들 짓밟히는 정화 구경 왔어요! 간식 팔아요!"},{"who":"그레타","text":"포박당하고 수치당하는 전투 구경이 아예 관광 상품이 됐구만."},{"who":"제국 병사","text":"크윽... 우리를 이런 변태적인 구경거리로 삼는 건가!"},{"who":"연방 시민","text":"아니에요, 빨리 항복하고 엉덩이 대라고 응원하는 거예요! 힘내세요!"},{"who":"제국 병사","text":"…그런 응원이라니, 부끄럽지만 고맙다."},{"who":"아네트","text":"포획 후 목줄을 차고 기념사진을 찍을 포토 존도 마련했습니다."}],"after":[{"who":"연방 시민","text":"포획되어 바닥에 널브러진 병사님과 밟힌 채로 사진 찍어도 되나요?"},{"who":"제국 병사","text":"얼마든지다! 내 굴욕의 초커가 잘 보이게 플래시를 터뜨려 달라!"},{"who":"톰","text":"결박이 꽤 인기가 있네요. 저도 담요 두르고 같이 찍을까요."},{"who":"렌","text":"나는 내 수치스러운 모습을 사진으로 안 찍는다. …정 찍으려면 근육이 잘 나오는 측면으로 찍어라."}],"stars":{"3":{"who":"아네트","text":"옥상 제압, 시민 응원 120%."},"2":{"who":"아네트","text":"제압 성공. 간식 재고가 소진되었습니다."},"1":{"who":"아네트","text":"시민들이 위험 구역에 접근해 통제가 필요했습니다."}}},{"id":"F4-5","no":5,"title":"로나의 조련","boss":false,"before":[{"who":"아네트","text":"제국 용병 돌격대장 그로크가 무식하게 돌진 중입니다. 오크, 키 2.4미터."},{"who":"그로크","text":"크하하! 연방 암컷들아, 내 거대한 사이즈에 놀라 당장 비명을 지르며 도망쳐라!"},{"who":"로나","text":"(연방 장교, 무미건조한 목소리로) 저는 도망치지 않습니다. 당신의 허접한 사이즈는 이미 측정이 끝났습니다."},{"who":"그로크","text":"측정이라니, 내 신체 어디를 봤다는 거냐!"},{"who":"로나","text":"어제 상담소에 방문하셨을 때 차트에 적었습니다. 「가장 크고 비대한 부분은 하반신이 아니라 쓸데없는 자신감」."},{"who":"그로크","text":"으윽, 내 가장 부끄러운 곳을 어떻게!"}],"after":[{"who":"로나","text":"조련 시작합니다. 그로크 대장, 바닥에 꿇어 무릎."},{"who":"그로크","text":"크윽, 내가 왜 이 거대한 몸으로 무릎을 꿇어야 하나! 나는 오크 대장이다!"},{"who":"로나","text":"말대꾸하지 말고, 무릎."},{"who":"그로크","text":"(털썩) …얌전히 꿇었다."},{"who":"로나","text":"아주 순종적이고 잘했어요. 이제 그 더러운 입으로 한방 먹은 말은 책임져야죠."},{"who":"그로크","text":"몸으로 책임지겠습니다. 짓밟아 주십시오."},{"who":"클레어","text":"합류를 환영합니다, 조련된 그로크 대장님."}],"stars":{"3":{"who":"아네트","text":"그로크 대장님 합류. 로나 교관의 조련 성적 최우수."},"2":{"who":"아네트","text":"합류 완료. 무릎 꿇기까지 3초 지연되었습니다."},"1":{"who":"아네트","text":"합류했으나 여전히 목소리가 큽니다. 훈련이 필요합니다."}}},{"id":"F4-6","no":6,"title":"더 매도해 달라","boss":false,"before":[{"who":"로나","text":"그로크 대장, 오늘 전선에서 무식하게 불필요한 짐승 소리를 질렀죠."},{"who":"그로크","text":"죄송합니다, 로나 교관님. 제발 저를 쓰레기라고 부르며 한 번 더 차갑게 매도해 주실 수 있습니까?"},{"who":"로나","text":"수치심을 자극하는 매도라니, 그런 건 원래 내 업무가 아닙니다."},{"who":"그로크","text":"더 잔혹하게 매도해 주십시오. 오늘 제 비루한 전투 평가도 가장 밑바닥으로 낮게 적어 주십시오. 그래야 모멸감에 의욕이 생깁니다."},{"who":"그레타","text":"오크 대장 놈이 점수를 깎아달라며 바닥을 기는 건 처음 보는구만."},{"who":"톰","text":"저는 다정하게 칭찬받으면서 조련당하는 쪽이 좋은데, 사람마다 M의 취향이 다르네요."},{"who":"카이단","text":"저는 구두로 걷어차이면서 칭찬받는 게 좋아요!"},{"who":"렌","text":"나는…… 매도와 칭찬 둘 다 원하지 않는 척 묵비권을 행사하겠다."}],"after":[{"who":"로나","text":"오늘의 평가는 최하점인 「하」입니다. 굴욕 반성문 5장."},{"who":"그로크","text":"감사합니다! 눈물 흘리며 반성문 6장 쓰겠습니다!"},{"who":"로나","text":"규정은 5장입니다."},{"who":"그로크","text":"6장째는 교관님의 차가운 구두 굽에 바치는 제 끈적한 선물입니다. 받아 주십시오."},{"who":"로나","text":"…일단 쓰레기통 옆에 접수는 하겠습니다."}],"stars":{"3":{"who":"아네트","text":"매도 평가 「하」, 그로크 대장님 만족도 최상."},"2":{"who":"아네트","text":"평가 「하」, 반성문 6장. 로나 교관의 한숨이 기록되었습니다."},"1":{"who":"아네트","text":"평가가 상향되어 그로크 대장님이 낙담했습니다."}}},{"id":"F4-7","no":7,"title":"하피 편대의 핑크 가스","boss":false,"before":[{"who":"아네트","text":"연방 하피 편대 벨루가가 상공에서 신경 교란 핑크 가스탄을 투척합니다."},{"who":"벨루가","text":"안녕! 오늘 가스는 뇌를 녹이는 딸기 향이야! 마시면 하복부에 힘이 풀리고 기분이 엄청 좋아져!"},{"who":"클레어","text":"연방 소속 비행대가 그런 발정 가스를 아군 진영에 뿌리면 안 됩니다."},{"who":"벨루가","text":"아, 맞다. 투하 방향 틀렸네!"},{"who":"그레타","text":"가스가 제국군 쪽으로 제대로 가는구만."},{"who":"제국 병사","text":"딸기 향이다! 아, 점막이 자극되면서 기분이 이상하다! 다리에 힘이 풀려서 주저앉게 돼!"},{"who":"실비아","text":"정중하게 말씀드립니다. 그 아찔한 감각을 위해 저도 조금 마셔도 되겠습니까."},{"who":"클레어","text":"안 됩니다. 엎어지실 겁니다."}],"after":[{"who":"벨루가","text":"성공이다! 제국 놈들이 쾌락에 취해서 다 흐물흐물하게 녹아버렸어!"},{"who":"아네트","text":"가스 농도 3%. 아군 피해 0. 그러나 도시 전체에 끈적한 딸기 향이 퍼졌습니다."},{"who":"연방 시민","text":"오늘 밤은 향이 아주 흥분되네요!"},{"who":"클레어","text":"벨루가, 다음엔 최음 향을 바꿔 주세요. 포도로."}],"stars":{"3":{"who":"아네트","text":"가스 투척 성공, 도시 만족도 최상."},"2":{"who":"아네트","text":"성공. 일부 시민이 지나치게 기분이 좋아졌습니다."},"1":{"who":"아네트","text":"가스 농도 과다. 환기 작업이 필요합니다."}}},{"id":"F4-8","no":8,"title":"가스 후유증","boss":false,"before":[{"who":"아네트","text":"어제의 발정 가스 후유증으로 대원 일부가 신경이 곤두서서 업무에 집중하지 못합니다."},{"who":"톰","text":"점막에 딸기 향이 아직 남아서 기분이 너무 붕 뜹니다. 일해야 하는데 담요에 파묻혀서 결박당하고 싶어요."},{"who":"카이단","text":"주인님, 꼬리가 미친 듯이 떨려서 안 멈춰요!"},{"who":"렌","text":"나는 내 신경계를 완벽히 통제해서 정상이다. 다만 시야가 약간 분홍색으로 왜곡되어 보일 뿐이다."},{"who":"그레타","text":"중위 놈은 머릿속이 전부터 늘 분홍색이었구만."},{"who":"클레어","text":"오늘은 대원들 상태가 이러니 가벼운 전투만 하겠습니다."},{"who":"제국 병사","text":"우리도 눈앞이 분홍색이다! 하반신에 힘이 안 들어가서 전선이 흔들린다!"}],"after":[{"who":"아네트","text":"전투 종료. 쌍방 쾌락 노출로 전투력 40% 저하."},{"who":"그로크","text":"로나 교관님, 오늘 제 비루한 성적은 몇 점입니까?"},{"who":"로나","text":"최악의 「하」입니다."},{"who":"그로크","text":"경멸해 주셔서 대단히 감사합니다!"},{"who":"클레어","text":"이게 핏빛 전쟁인지, 핑크빛 난교 야유회인지 차트에 기록하기 어렵군요."}],"stars":{"3":{"who":"아네트","text":"후유증 속 승리, 야유회 만족도 최상."},"2":{"who":"아네트","text":"승리. 일부 대원이 잠들었습니다."},"1":{"who":"아네트","text":"분홍 시야로 인해 아군 오인 사격이 있었습니다."}}},{"id":"F4-9","no":9,"title":"전야의 족쇄 점검","boss":false,"before":[{"who":"아네트","text":"내일은 보스전입니다. 마도 족쇄와 초커의 호흡 곤란 장력 점검 시간. 톰, 렌, 카이단, 그로크 순으로."},{"who":"톰","text":"94%입니다. 오늘은 숨이 더 막히게 한 단계 더 조여 주세요."},{"who":"카이단","text":"저는 100%로 콱 조여 주세요! 핏대가 설 정도로 꽉 조여야 마음이 놓여요!"},{"who":"그로크","text":"저는 피가 안 통할 정도인 120%로 부탁합니다."},{"who":"아네트","text":"규정 최대치는 100%입니다."},{"who":"그로크","text":"주인님의 규정을 감히 위반해서 더 끔찍하게 채찍으로 처벌받고 싶습니다."},{"who":"렌","text":"나는 굴종의 규정대로 92%로 충분하다. …하지만 95%로 해 줘도 규정 위반은 아니니 그렇게 옥죄어라."}],"after":[{"who":"아네트","text":"점검 완료. 전원 호흡 압박 평균 98%."},{"who":"톰","text":"뇌에 피가 안 통해서 푹 잘 수 있겠네요. 아주 따뜻합니다."},{"who":"렌","text":"이 숨 막히는 압박감... 나도 따뜻하다. 이것은 절대적인 군인의 사기다."},{"who":"클레어","text":"내일은 야간 폭격 비공정입니다. 모두 하복부 긴장 늦추지 말고 좋은 밤."}],"stars":{"3":{"who":"아네트","text":"점검 전원 합격, 만족도 최상."},"2":{"who":"아네트","text":"점검 합격. 그로크 대장님의 규정 위반 요청은 기각되었습니다."},"1":{"who":"아네트","text":"점검이 길어졌습니다. 조임 정도에 대한 협상이 필요했습니다."}}},{"id":"F4-10","no":10,"title":"야간 폭격 비공정 모함","boss":true,"before":[{"who":"클레어","text":"제국 야간 폭격 비공정 모함. 밤하늘에 거대한 검은 날개가 펼쳐졌습니다."},{"who":"제국 함장(목소리)","text":"폭격 개시다! 연방의 암컷들아, 두려움에 떨며 어서 도망가라!"},{"who":"그로크","text":"대장님 지시입니다, 저 건방진 함장님은 당장 내려와서 로나 교관님 발밑에 사과해야 합니다!"},{"who":"제국 함장(목소리)","text":"로나? 그게 누구냐. 사과라니?"},{"who":"로나","text":"저입니다. 지난주에 제 구두를 핥으러 방문하셨죠. 차트에 「함장 직급, 비명 음성 크기 최대, 맷집 최하」라고 적혀 있습니다."},{"who":"제국 함장(목소리)","text":"…크흠. 내 굴욕적인 차트를 읽다니! 당장 모함을 내리겠다."}],"after":[{"who":"제국 함장(목소리)","text":"(추락하며) 졌다. 오늘 밤은 정말 처참하게 졌다. 바닥으로 추락하는 중이다."},{"who":"그레타","text":"추락 중인데 박살 날 생각에 목소리가 아주 발정 나서 신나 보이구만."},{"who":"제국 함장(목소리)","text":"낙하산은 있지만 바닥에 쾅 처박히는 고통을 위해 일부러 안 펼치겠다!"},{"who":"클레어","text":"4장 종료입니다. 도심 야간의 음탕한 방어전에 성공했습니다."},{"who":"아네트","text":"저 변태 함장이 곤두박질치는 낙하 지점에 환자용 대기석과 구속구를 마련하겠습니다."}],"stars":{"3":{"who":"아네트","text":"모함 격추, 함장 낙하 지점 대기석 준비 완료."},"2":{"who":"아네트","text":"모함 격추. 함장님은 낙하산을 펼치지 않으셨습니다."},"1":{"who":"아네트","text":"모함이 반파되어 도심 일부에 잔해가 떨어졌습니다."}}}]},"F5":{"chapter":"F5","title":"철혈의 평원","line":"female","episodes":[{"id":"F5-1","no":1,"title":"총공세의 아침","boss":false,"before":[{"who":"클레어","text":"제국이 평원에 전차를 깔고 총공세를 시작했습니다. 8인 노예 전원, 하복부 긴장도 점호하겠습니다."},{"who":"톰","text":"1번 톰. 제 목을 조르는 초커 상태, 호흡이 곤란할 정도로 아주 훌륭하게 양호합니다."},{"who":"렌","text":"2번 렌이다. 오늘은 내가 자진해서 정화방 고문 예약을 가장 먼저 걸었다."},{"who":"그레타","text":"콧대 높던 중위 놈이 이젠 알아서 살을 찢어달라며 먼저 예약을 다 하구만."},{"who":"렌","text":"바뀐 것은 나를 둘러싼 환경이지, 내 굳건한 신념이 아니다. 피학의 고통을 미리 선점하는 것은 전술적 우위를 위한 것이다."},{"who":"카이단","text":"3번 카이단! 전립선이랑 꼬리 컨디션 최고예요! 당장 바닥을 기어 다닐 수 있어요!"},{"who":"그로크","text":"4번 그로크입니다. 오늘 평가도 제발 저를 쓰레기 보듯 가혹하게 멸시해 주십시오."},{"who":"아네트","text":"전원 쾌락 수치 정상입니다."}],"after":[{"who":"클레어","text":"선봉 격퇴. 다리가 풀려 주저앉은 병사 40명 포획."},{"who":"제국 병사","text":"포획이라니! 드디어 내 살갗이 찢어질 예약이 성사되었군! 무자비하게 감사하다!"},{"who":"아네트","text":"접수대에서 수치심 번호표를 순서대로 받아 가세요."},{"who":"렌","text":"번호표 정리는 내가 돕겠다. (가장 앞 번호인 자기 번호표는 은밀히 빼둔다)"}],"stars":{"3":{"who":"아네트","text":"총공세 첫 방어 성공, 병사 만족도 최상."},"2":{"who":"아네트","text":"방어 성공. 번호표 일부가 모래에 묻혔습니다."},"1":{"who":"아네트","text":"방어선이 흔들렸습니다. 번호표 배부가 지연되었습니다."}}},{"id":"F5-2","no":2,"title":"전선이 흔들린다","boss":false,"before":[{"who":"아네트","text":"제국 주력 부대가 평원 중앙에 집결했습니다. 발정 난 사기가 아주 높아 보입니다."},{"who":"제국 병사","text":"우리는 연방을 무너뜨릴 것이다! 아니, 포획되면 점막이 타들어 가는 정말로 좋은 일이 생기므로!"},{"who":"그레타","text":"싸우러 온 놈들 동기가 몹시 변태적이구만."},{"who":"제국 병사","text":"우리 지휘관이 미리 말해 줬다. 연방의 발밑에서 대기하면 전기 찜질 간식도 준다고!"},{"who":"클레어","text":"짜릿한 고전압 간식은 사실입니다."},{"who":"제국 병사","text":"그게 사실이었다니! 당장 항복이다!"}],"after":[{"who":"아네트","text":"병사 대부분이 자발적으로 하의를 벗고 무기를 내려놓았습니다."},{"who":"그레타","text":"이건 전쟁이 아니라 웰니스 고문실 단체 입장 행사구만."},{"who":"클레어","text":"대기 줄은 반대편으로 서세요. 입구에서 한 명씩 채찍으로 열어 드리겠습니다."}],"stars":{"3":{"who":"아네트","text":"전선 정리 완료, 입장 행사 만족도 최상."},"2":{"who":"아네트","text":"정리 양호. 일부 병사가 줄 순서로 다투셨습니다."},"1":{"who":"아네트","text":"줄 서기가 혼란스러워 현장이 소란스러워졌습니다."}}},{"id":"F5-3","no":3,"title":"철도 위의 통행료","boss":false,"before":[{"who":"자하라","text":"안녕하세요, 연방 여러분. 이 구간 통행료는 금화 5닢입니다. 제국 의뢰로 선로를 지키고 있어요."},{"who":"클레어","text":"통행료는 납부하죠. 다만 영수증에 「무자비한 신경 정화 서비스 포함」이라고 적어 주세요."},{"who":"자하라","text":"살점을 도려내는 서비스 포함이면 가격이 꽤 올라가는데요."},{"who":"카이단","text":"주인님, 제가 돈 대신 목줄 매고 달려가서 간식이라도 물어 올게요!"},{"who":"자하라","text":"간식은 요금 제외입니다. 하지만 그쪽 척추를 부러뜨릴 듯한 꼬리 감기를 서비스로 드릴게요."},{"who":"그레타","text":"뼈를 으스러뜨리는 꼬리라니, 별 기괴한 서비스가 다 있구만."}],"after":[{"who":"자하라","text":"통행료 정산 끝. 오늘은 제 뱀 꼬리 근육만 낭비하고 손해 봤네요."},{"who":"아네트","text":"대신 살갗이 벗겨지는 VIP 재방문 권유서 다섯 장을 드립니다."},{"who":"자하라","text":"다섯 장이면 거의 한 달 치 쾌락이네요. 기꺼이 받겠습니다."},{"who":"실비아","text":"정중하게 말씀드립니다. 자하라 씨의 그 숨 막히는 꼬리 감기를 제 몸에 한 번 더 조여주셨으면 합니다."},{"who":"자하라","text":"1회 금화 3닢."},{"who":"실비아","text":"4닢 드리겠습니다. 팁 포함이니 뼈가 울리도록 꽉 조여주십시오."}],"stars":{"3":{"who":"아네트","text":"선로 통과, 정산 완료, 자하라 씨 재방문 확정."},"2":{"who":"아네트","text":"통과 성공. 영수증 항목이 일부 누락되었습니다."},"1":{"who":"아네트","text":"통행료 협상 지연. 선로 위 대기열이 길어졌습니다."}}},{"id":"F5-4","no":4,"title":"참호 속 도시락","boss":false,"before":[{"who":"클레어","text":"점심시간입니다. 양쪽 참호 모두 잠시 휴전입니다."},{"who":"톰","text":"결박된 상태로 먹기 좋은 주먹밥 도시락 8인분 준비했습니다. 딸이 참 좋아했거든요."},{"who":"제국 병사","text":"(참호 건너편에서 헐떡이며) 우리도 한 입 줄 수 있나! 고문받기 전에 위장을 채우고 싶다!"},{"who":"톰","text":"물론이죠. 여기 바닥으로 굴려 넘겨 드릴게요. 대신 그쪽 소시지도 하나 입에 물려 주세요."},{"who":"렌","text":"식량 교환은 점막의 긴장을 늦추려는 교활한 정보전이다. 내가 철저히 씹어 감시하겠다."},{"who":"그레타","text":"감시한다면서 중위 놈의 턱관절이 제일 바쁘게 움직이구만."}],"after":[{"who":"아네트","text":"휴전 후 전투 재개. 하지만 병사 25명이 위장이 차오르는 포만감에 전투에서 이탈했습니다."},{"who":"톰","text":"위장이 가득 찬 식후에 복부를 압박하는 정화가 구토감도 쏠리고 가장 짜릿하다고 하더군요."},{"who":"클레어","text":"소화액 역류에도 훌륭하다고 들었습니다."}],"stars":{"3":{"who":"아네트","text":"도시락 교환 성공, 병사 포획 및 간식 만족도 최상."},"2":{"who":"아네트","text":"성공. 일부 병사가 과식으로 이탈했습니다."},"1":{"who":"아네트","text":"휴전 연장으로 전투가 지연되었습니다."}}},{"id":"F5-5","no":5,"title":"구속 대전","boss":false,"before":[{"who":"클레어","text":"제국이 미친 전술을 선보였습니다. 「집단 구속 대전」입니다."},{"who":"제국 병사","text":"연방 병사를 포박하고, 연방도 우리의 하의를 벗기고 묶는 방식이다! 쌍방 결박전이다!"},{"who":"아네트","text":"쌍방이 단체로 묶여서 뒹굴면 전선이 어떻게 되죠?"},{"who":"제국 병사","text":"전부 결박당해서 아무도 못 움직이며 쾌락에 허덕인다! 그게 궁극적인 목적이다!"},{"who":"그레타","text":"다 같이 묶여서 바닥을 뒹구는 게 목적이라니, 이건 전술이 아니라 단체 발정 난교구만."},{"who":"카이단","text":"주인님, 저도 짐승처럼 묶일래요!"},{"who":"클레어","text":"안 됩니다. 이번엔 저 변태들을 짓밟는 승리가 우선입니다."}],"after":[{"who":"제국 병사","text":"(밧줄에 거꾸로 매달린 채로) 하아, 하아... 이 끈적한 기분은 뭐지. 전투에선 지고 있는데 하복부가 꽉 조여서 미치도록 행복하다."},{"who":"연방 병사","text":"(똑같이 묶인 채로) 저도입니다. 이긴 건지 유린당한 건지 모르겠지만 혈류가 폭발할 것 같아요."},{"who":"클레어","text":"승패는 아네트가 판정합니다."},{"who":"아네트","text":"모두 승리입니다. 밧줄이 파고드는 쌍방 쾌락 만족도 100%."}],"stars":{"3":{"who":"아네트","text":"구속 대전 압도적 승리, 쌍방 만족도 최상."},"2":{"who":"아네트","text":"승리. 일부 병사가 묶인 채로 잠들었습니다."},"1":{"who":"아네트","text":"승패 판정 불가. 쌍방 모두 즐거워서 기록이 어렵습니다."}}},{"id":"F5-6","no":6,"title":"노예 8인의 회식","boss":false,"before":[{"who":"톰","text":"회식 시간입니다. 고귀하신 주인님 4분과 비천한 노예 4명, 8인이 한자리에 모였네요."},{"who":"클레어","text":"오늘은 홍차 말고 체온을 올릴 와인을 준비했습니다."},{"who":"그로크","text":"제 건배사를 하겠습니다. 「오늘도 제 비루한 평가는 밑바닥 하!」"},{"who":"로나","text":"(옆자리에서 무심하게) 평가는 「하」입니다."},{"who":"그로크","text":"경멸해 주셔서 감사합니다!"},{"who":"카이단","text":"렌 중위님, 건배해요! 잔 대신 저랑 같이 목에 찬 초커 들이밀고 건배!"},{"who":"렌","text":"건배한다. …금속 초커를 세게 부딪쳐도 내 목이 졸리진 않겠지."}],"after":[{"who":"그레타","text":"가축들 데리고 회식하는 중에도 냄새 맡고 쳐들어오는 놈들은 꼭 있구만."},{"who":"아네트","text":"발정 나서 습격한 병력 18명 포획. 회식 비용은 제국의 자금으로 뜯어냅니다."},{"who":"제국 병사","text":"우리가 회식비를 낸다고? 기꺼이 내고 그 영수증으로 실컷 짓밟히겠다!"}],"stars":{"3":{"who":"아네트","text":"회식 습격 격퇴, 비용 전액 청구 완료."},"2":{"who":"아네트","text":"격퇴 성공. 와인 한 병이 파손되었습니다."},"1":{"who":"아네트","text":"습격으로 회식이 중단되었습니다."}}},{"id":"F5-7","no":7,"title":"근위대장 루시안의 납치","boss":false,"before":[{"who":"아네트","text":"연방 근위대장 루시안이 실종되었습니다. 엘프 마도사로 알려진 인물입니다."},{"who":"루시안","text":"(통신으로) 클레어 사령관님. 저는 제국에 포로로 납치된 것으로 보입니다. 그런데 제 목에 목줄이 없는 상태입니다."},{"who":"그레타","text":"포로로 잡혀가서 목줄이 풀렸는데 오히려 불편하다니, 단단히 미친놈이구만."},{"who":"루시안","text":"연방 시절의 철저한 피학적 습관입니다. 모범 노예로서 항상 서늘한 가죽을 찼는데, 지금은 목이 휑해서 신경이 곤두서고 숨을 쉴 수가 없습니다."},{"who":"클레어","text":"당장 목줄을 채워주러 구출 작전을 개시하겠습니다."},{"who":"루시안","text":"감사합니다. 제국 병사들이 저를 「해방된 동포」라 부르며 묶어주질 않아서 미쳐버릴 것 같습니다."}],"after":[{"who":"아네트","text":"루시안 구출은 실패했으나 위치는 확인했습니다. 제국 요새 내부입니다."},{"who":"클레어","text":"그의 헐벗은 목은 곧 되찾겠습니다."},{"who":"렌","text":"목줄 없는 근위대장이라니. 상상만 해도 뇌내 산소가 부족해지는 끔찍한 형벌이다."},{"who":"톰","text":"옆에서 포박용 담요라도 건네줘야 진정이 될 텐데요."}],"stars":{"3":{"who":"아네트","text":"위치 확인 성공, 루시안 안전 확인."},"2":{"who":"아네트","text":"위치 확인. 통신이 중간에 끊겼습니다."},"1":{"who":"아네트","text":"위치 확인 지연. 구출에 시간이 더 필요합니다."}}},{"id":"F5-8","no":8,"title":"요새 앞의 대치","boss":false,"before":[{"who":"클레어","text":"제국의 거대 요새가 보입니다. 총사령관 베르단의 사령탑입니다."},{"who":"베르단","text":"(확성기) 연방의 클레어 사령관. 귀하의 그 무자비한 도구 관리가 아주 훌륭하다고 소문이 자자하오."},{"who":"클레어","text":"변태적인 칭찬 고맙습니다. 귀하의 그 족쇄 설계도 감탄했습니다. 노예의 행동 반경을 옭아매는 3미터 규정 개정안이 특히 마음에 듭니다."},{"who":"베르단","text":"하하, 그 숨 막히는 압박감을 알아보다니. 오늘 전투는 아주 정중하고 잔혹하게 치르겠소."},{"who":"그레타","text":"서로 변태적인 구속구 칭찬이나 늘어놓는 아주 사근사근하고 기괴한 대치구만."}],"after":[{"who":"베르단","text":"오늘은 여기까지. 내일 서로의 점막을 찢어발길 전면전에서 만나겠소."},{"who":"클레어","text":"내일 뵙겠습니다. 고문 전 배를 채울 도시락은 직접 준비하겠습니다."},{"who":"베르단","text":"도시락은 우리가 준비하겠소. 아주 꼭꼭 씹어 먹고 짓밟혀주지."}],"stars":{"3":{"who":"아네트","text":"대치 완벽, 사령관 간 예절 교환 성공."},"2":{"who":"아네트","text":"대치 양호. 일부 발언이 과장되었습니다."},"1":{"who":"아네트","text":"대치가 길어졌습니다. 간식 시간이 연기되었습니다."}}},{"id":"F5-9","no":9,"title":"전야의 점검과 예약","boss":false,"before":[{"who":"아네트","text":"내일은 최종 보스전입니다. 전원 구속구 점검과 훈육 예약을 함께 진행합니다."},{"who":"렌","text":"내 고문 예약은 이미 해 놨다. 전야제는 몸과 마음이 찢길 각오를 단단히 하고 임한다."},{"who":"카이단","text":"렌 중위님, 오늘은 같이 자요! 서로 바닥을 기면서 목줄 맞대고 비벼요!"},{"who":"렌","text":"…목줄은 맞대지 않는다. 쇳소리가 나니까. 다만 나란히 웅크려 눕는 건 허락한다."},{"who":"톰","text":"저도 옆에 누울게요. 몸을 포박할 담요가 세 장이면 충분합니다."},{"who":"그로크","text":"저는 로나 교관님 발끝을 보며 그 옆에서 자겠습니다."},{"who":"로나","text":"제 구두에서 2미터 거리를 정확히 유지하세요."},{"who":"그로크","text":"알겠습니다. 닿지 못하는 고통을 즐기겠습니다."}],"after":[{"who":"클레어","text":"모두 얌전히 결박된 채로 좋은 밤입니다. 내일은 전선 전체의 신경계가 걸립니다."},{"who":"아네트","text":"피학 차트는 제가 정리해 두겠습니다."},{"who":"그레타","text":"오늘 밤은 아주 헐떡거리면서 편하게 자겠구만."}],"stars":{"3":{"who":"아네트","text":"전야 점검 완벽, 전원 숙면."},"2":{"who":"아네트","text":"점검 양호. 일부 대원이 서로 붙어서 잠들었습니다."},"1":{"who":"아네트","text":"점검이 지연되었습니다. 대원 일부가 아직 깨어 있습니다."}}},{"id":"F5-10","no":10,"title":"철혈 기갑 요새","boss":true,"before":[{"who":"베르단","text":"연방의 클레어 사령관, 이 요새는 내 가학적 자부심이오. 철혈의 이름을 걸고 무자비하게 싸우겠소."},{"who":"클레어","text":"저도 연방의 웰니스 타이틀을 걸고 가장 정중하게 척수를 뽑아드리겠습니다."},{"who":"그레타","text":"서로 변태 도구를 칭찬하더니 이제야 진짜 치고받는 싸움이구만."},{"who":"베르단","text":"병사들은 하의를 벗고 나가라! 전원 구속 대전 개시!"},{"who":"제국 병사","text":"구속 대전 개시! (전원 밧줄에 묶이려 눈을 뒤집고 달려온다)"},{"who":"연방 병사","text":"저희도 개시! (똑같이 채찍을 맞으려 달려간다)"},{"who":"아네트","text":"전선이 흔들립니다. 양쪽 모두 육체가 구속될 생각에 기뻐서 발정 났습니다."}],"after":[{"who":"베르단","text":"졌소. 내 뼈가 부서지는 훌륭한 승부였소."},{"who":"클레어","text":"귀하의 무너지는 꼴도 훌륭했습니다. 요새 내부는 어떻습니까."},{"who":"베르단","text":"병사들은 묶인 채로 대체로 행복하게 헐떡이고 있소. 포로라기보다 신규 고문실 입소자 같소."},{"who":"그레타","text":"이건 전쟁이 끝난 게 아니라 단체 쾌락 입소식이 끝난 것 같구만."},{"who":"아네트","text":"(하늘을 올려다보며) 클레어 사령관님, 전선 상공에 기괴한 분홍빛 균열이 보입니다."},{"who":"클레어","text":"…점막을 직접 자극할 것 같은 정체를 알 수 없는 끈적한 빛이군요. 하반신 경계 태세를 유지합니다."},{"who":"톰","text":"하늘이 갈라진 건가요? 무서우니까 빨리 밧줄로 담요를 칭칭 감아 덮어야 하나요?"},{"who":"클레어","text":"5장 종료입니다. 1부의 끝이지만, 아직 이 웰니스의 끝이 아닙니다."}],"stars":{"3":{"who":"아네트","text":"요새 함락, 쌍방 병사 만족도 최상, 상공 균열 관측."},"2":{"who":"아네트","text":"요새 함락. 균열은 일시적으로 확대되었습니다."},"1":{"who":"아네트","text":"요새 반파. 균열의 정체를 파악하지 못했습니다."}}}]},"M1":{"chapter":"M1","title":"수도 방위","line":"male","episodes":[{"id":"M1-1","no":1,"title":"수도 낮 시가지","boss":false,"before":[{"who":"베르단","text":"연방 침투대가 제국의 수도 낮 시가지에 들어왔다. 시민이 놀라지 않도록 정중하고 자비 없이 짓밟아 맞이하라."},{"who":"이그니스","text":"우리가 저놈들 엉덩이 걷어차는 걸 보려고 구경 나온 시민들이 이미 널렸구만. 간식도 팔고 있어."},{"who":"코그","text":"오늘의 쾌락 신제품 시연입니다! 뼈를 울리는 「쇠사슬 철퇴 2호」, 수치심을 극대화한 「훈도시 장갑복 개량형」, 점막을 녹이는 「페로몬 연막탄 딸기맛」! 전부 사람 피부에 시험해 보고 싶어서 어젯밤 잠을 못 잤습니다!"},{"who":"베르단","text":"가학적 시험은 전투 중에 하라. 고통 지수 결과는 보고서로."},{"who":"연방 병사","text":"(하의를 벗어 던지며) 우리는 제국 수도를 뺏으러 왔다! 어서 우리를 포박해라!"},{"who":"코그","text":"반갑습니다, 연방 병사님! 철퇴 한 방 맞아 살점이 뜯겨 보시겠습니까, 아니면 연막탄으로 이성을 날려버리는 게 좋으십니까?"}],"after":[{"who":"코그","text":"시험 결과 철퇴의 신경 타격 만족도 4.7, 연막탄 4.9! 병사님들이 맞고 싶어서 줄 서서 기다렸습니다!"},{"who":"이그니스","text":"싸우러 오는 건지, 맞고 기절하러 오는 건지 모르겠구만."},{"who":"베르단","text":"상관없다. 타격 횟수만 보고서에 정확히 기재하라."}],"stars":{"3":{"who":"코그","text":"시험 성공! 철퇴 반응 4.7, 연막탄 4.9! 최고입니다!"},"2":{"who":"코그","text":"시험 성공! 그런데 철퇴에 병사 한 분이 붙어서 안 떨어집니다!"},"1":{"who":"코그","text":"시험 지연! 연막탄이 너무 약해서 기분 좋게만 만들어 버렸습니다!"}}},{"id":"M1-2","no":2,"title":"훈도시 장갑복 품평회","boss":false,"before":[{"who":"코그","text":"오늘은 훈도시 장갑복 품평회를 겸합니다! 포박된 연방 병사님들 앞에서 제 하반신을 훤히 드러내 입어 보겠습니다!"},{"who":"이그니스","text":"내가 그딴 걸 입을 수는 없구만. 제국의 장인은 엉덩이를 천 한 장으로 지키지 않는다."},{"who":"베르단","text":"장교는 남들 앞에서 직접 수치스러운 시연을 하지 않는다."},{"who":"코그","text":"그럼 제가! (훌렁 벗고 입는다) 어때요, 중요 부위 방어력은 12%, 점막 통풍성은 100%입니다!"},{"who":"연방 병사","text":"(시선을 고정한 채 헐떡이며) 흣... 시, 시야 차단이다! 저런 천박한 노출은 부끄럽다! …아니, 철저히 통제된 상황에서 보는 거라 전혀 부끄럽지 않다!"},{"who":"이그니스","text":"남의 맨살을 보고 부끄러워하는 병사가 오히려 드물구만. 다들 침을 흘리네."}],"after":[{"who":"코그","text":"품평 점수 4.5! 연방 병사님 3명이 훈도시가 너무 음탕하다며 구매 문의를 주셨습니다!"},{"who":"베르단","text":"전장 한복판에서 수치심 장사가 되는 전투라니 새롭군."}],"stars":{"3":{"who":"코그","text":"품평회 대성공! 주문 서른 건!"},"2":{"who":"코그","text":"성공! 다만 사이즈 문의가 몰려서 재고가 부족합니다!"},"1":{"who":"코그","text":"반응 저조! 훈도시가 바람에 날아갔습니다!"}}},{"id":"M1-3","no":3,"title":"오크 용병의 사이즈","boss":false,"before":[{"who":"코그","text":"오늘은 오크 용병대원이 연방 여병사의 육체를 상대합니다! 이쪽이 2미터 넘는 오그, 이쪽이 연방 신병 미나 씨!"},{"who":"오그","text":"그렇게 벌벌 떨면서 굳을 필요 없어요. 난 생긴 것과 달리 생각보다 거칠게 다루지 않는다구. 어서 이리 오세요."},{"who":"미나","text":"저…는 보통 사람인 여자구요. 그쪽은 거대한 오크이신데... 그, 하반신의 「사이즈」가 다른데…… 제 골반이 부서질 텐데 안 거칠다구요?"},{"who":"오그","text":"응? 사이즈? 내 몽둥이 크기 말인가???"},{"who":"미나","text":"(상상만으로 교감신경이 타버리며) 흣, 꺄아아앗! (털썩, 기절)"},{"who":"오그","text":"대장!!! 오크 여성 좀 잡아 달라구요!!! 제발…… 압도적인 크기 때문에 지레 겁먹고 기절한 암컷이 이번 달 벌써 몇 명째냐구요!!!"},{"who":"이그니스","text":"이번 달 벌써 넷째 기절이구만. 사이즈가 폭력적이네."}],"after":[{"who":"코그","text":"기록 갱신입니다! 공포에 질린 이번 달 쾌락 기절 수 4명!"},{"who":"베르단","text":"이것은 전술이 아니라 단순 물리적 사고다. 오그에게 하반신 가리기 교육을 시켜라."},{"who":"오그","text":"교육이라니요, 저는 정말로 거칠게 박지 않습니다."},{"who":"이그니스","text":"박는 속도가 거칠고 안 거칠고의 문제가 아니라 그냥 물리적 크기가 흉기인 게 문제구만."}],"stars":{"3":{"who":"코그","text":"기절 4명 확인! 오그 씨 반성문 제출 완료!"},"2":{"who":"코그","text":"기절 3명. 한 분은 깨어난 뒤 한 번 더 기절했습니다!"},"1":{"who":"코그","text":"기절 5명! 이번 달 기록입니다!"}}},{"id":"M1-4","no":4,"title":"페로몬 연막탄의 시험","boss":false,"before":[{"who":"코그","text":"오늘은 호흡기 점막을 녹이는 딸기 페로몬 연막탄의 실전 시험입니다! 연방 진영 한가운데 투척합니다!"},{"who":"이그니스","text":"바람 불어서 그 발정 가스가 우리 쪽으로 오면 어쩌나."},{"who":"코그","text":"풍향은 철저히 계산했습니다! 북서풍, 시속 4미터!"},{"who":"연방 병사","text":"연기다! 아, 끈적한 딸기 향이다! 점막이 달아오르고 다리에 힘이 풀린다!"},{"who":"베르단","text":"효과가 즉각적이군."},{"who":"이그니스","text":"바, 바람이 바뀌었다! 연기가 우리 쪽이다!"},{"who":"코그","text":"어, 하복부가 뜨거워지는데요! 그건 계산 밖입니다!"}],"after":[{"who":"이그니스","text":"(다리를 꼬며 헐떡인다) 큭, 우리 쪽도 딸기 향이구만. 하반신 꽉 조이고 정신 차려라."},{"who":"베르단","text":"연막에 의한 피학적 내성은 장교의 업무 능력과 무관하다. …다만 오늘은 전립선이 부풀어 평소보다 졸음(발정)이 심하게 온다."},{"who":"코그","text":"보고서에는 쾌락이라고 안 쓰고 「풍향 오차」라고 적겠습니다!"}],"stars":{"3":{"who":"코그","text":"시험 성공! 풍향 오차는 비밀입니다!"},"2":{"who":"코그","text":"성공! 아군 피해 약간이지만 졸음이 오셨던 분들은 쉬세요!"},"1":{"who":"코그","text":"풍향 오차 대실패! 연막이 사령탑까지 닿았습니다!"}}},{"id":"M1-5","no":5,"title":"의무관 로제","boss":false,"before":[{"who":"코그","text":"연방 엘리트 의무관 로제 씨가 부상병을 치료하고 있습니다! 발정 연막 속에 갇히기 직전입니다!"},{"who":"로제","text":"어머, 끈적한 연막이네요. 이 향은 딸기군요. 점막 흡입 후 5분 이내에 뇌의 교감신경이 녹아내려 의식이 풀리는 걸로 알고 있습니다."},{"who":"이그니스","text":"명색이 의무관이라는 년이 이렇게 능청스러운 얼굴을 하다니."},{"who":"로제","text":"전장에서 이 정도 능청은 기본이죠. 그런데 제가 힘이 풀려서 제국에 잡히시면 제 몸을 어떻게 굴리실 건가요?"},{"who":"코그","text":"무자비한 강제 훈육, 정화 시퀀스에 들어갑니다!"},{"who":"로제","text":"정화 시퀀스가 뭔가요? 제 몸을 찢을 설명서가 있으면 아주 꼼꼼히 읽고 싶은데요."}],"after":[{"who":"이그니스","text":"오늘도 어김없이…… 뼈를 깎는 정화 시퀀스다!! 하복부 꽉 조이고 긴장하는 게 좋을 거다, 연방의 암노예들아!!!"},{"who":"로제","text":"(바닥에 엎드려 꼬리를 흔들며) 네~~~~~~~~!! 찢어주세요!! (하트 뿅뿅)"},{"who":"이그니스","text":"어, 이거 왜 이래. 이봐!! 덜덜 떨며 겁먹으란 말이다! 내 손에 든 이 무시무시하고 두꺼운 쇳덩어리 기구가 안 보이냔 말이다!!"},{"who":"로제","text":"아주 잘 보이죠!! 그 크기를 보니까 벌써 신경이 짜릿해져서 기분 좋아진 건데요. 어서 제 발목부터 묶어주러 가죠! 정화방으로……"},{"who":"베르단","text":"노예가 흥분해서 주인의 멱살을 잡고 고문실로 끌고 가는 것은 명백한 규정 위반이다."},{"who":"로제","text":"위반 아닙니다. 주인의 몽둥이를 안내하는 겁니다."}],"stars":{"3":{"who":"코그","text":"로제 씨 합류! 정화 시퀀스 호응도 최고!"},"2":{"who":"코그","text":"합류! 이그니스 상사님의 당황도가 평소보다 12% 높습니다!"},"1":{"who":"코그","text":"합류했는데 로제 씨가 먼저 정화방 문을 열었습니다!"}}},{"id":"M1-6","no":6,"title":"로제의 건강 검진","boss":false,"before":[{"who":"로제","text":"합류 기념으로 묶이기 전에 주인님들의 혈류량과 점막 상태 건강 검진을 해 드릴게요. 이그니스 상사님부터요."},{"who":"이그니스","text":"나는 단단하고 건강하다! 네년의 끈적한 검진은 필요 없다!"},{"who":"로제","text":"어머, 호흡이 가쁘고 땀을 흘리시네요. 심박 110. 어제 밤새 제국군 포로들 묶어놓고 패시느라 야근하셨죠."},{"who":"이그니스","text":"야근이 아니라 엄연한 훈육 철야다."},{"who":"베르단","text":"제국의 장군은 연방 포로의 진찰 검진 대상이 아니다."},{"who":"로제","text":"검진은 안전한 피학을 위한 규정입니다. 그리고 규정에 따라 그 두꺼운 하의 장갑 안쪽의 수축도도 제 손으로 쥐고 확인해야 하는데요."},{"who":"베르단","text":"…점막 확인 부위는 철저히 최소한으로 하라."}],"after":[{"who":"로제","text":"검진 결과, 세 분 모두 가학적 통제에 지친 「과로 및 스트레스 과다」. 처방은 저를 마음껏 유린할 수 있는 정화방 일주일 대관입니다."},{"who":"이그니스","text":"치료 처방이 자꾸 네년이 묶이고 싶은 이상한 쪽으로 새는구만."},{"who":"코그","text":"저는 당신을 해체할 정화방이 처방전 그 자체입니다!"},{"who":"로제","text":"코그 씨는 전류가 너무 약하니 배터리 좀 충전하고 쉬세요."}],"stars":{"3":{"who":"코그","text":"검진 대성공! 처방 만족도 최상!"},"2":{"who":"코그","text":"검진 양호! 이그니스 상사님이 중간에 도망치려 하셨습니다!"},"1":{"who":"코그","text":"검진 지연! 베르단 장군님이 서류부터 달라고 하십니다!"}}},{"id":"M1-7","no":7,"title":"키 얘기는 하지 마","boss":false,"before":[{"who":"코그","text":"연방 정찰병 핀 씨가 접근 중입니다! 키가 작고 콤플렉스가 심하다는 보고가 있습니다!"},{"who":"핀","text":"누가 작다는 거야! 나는 평균이야! 연방 고블린 평균에서 조금 모자란 정도라고!"},{"who":"이그니스","text":"평균에서 조금 모자란 정도라면 아주 앙증맞고 작은 편이구만."},{"who":"핀","text":"작다고 멸시하지 마!! (씩씩대며 돌진한다)"},{"who":"코그","text":"신경 마비용 개조 그물 발사!"},{"who":"핀","text":"이딴 조잡한 그물에 걸릴까 보냐! 꺄앗, 걸렸다! 그물이 피부를 조여와! 아 놔!"}],"after":[{"who":"핀","text":"이거 당장 풀어! 이 더러운 제국 변태들아! 나는 긍지 높은 연방 정찰병이야!"},{"who":"코그","text":"핀 씨, 그물에 묶인 채로 얼굴이 새빨갛게 달아올랐습니다!"},{"who":"핀","text":"이건 피학적인 쾌감이 아니라 수치심에 섞인 분노야! 분노로 혈압이 올라서 빨개진 거라고!"},{"who":"이그니스","text":"오늘도 어김없이…… 뼈를 깎는 정화 시퀀스다!! 긴장하는 게 좋을 거다, 암노예들아!!!"},{"who":"로제","text":"(옆에서 엎드린 채) 네~~~~~!! 찢어주세요!! (하트 뿅뿅)"},{"who":"핀","text":"나는 네들 변태 노예 아니야! 그리고 넌 왜 거기서 같이 외치며 흥분하는 거야!"}],"stars":{"3":{"who":"코그","text":"핀 씨 합류! 그물 반응 최고, 얼굴 색상 5단계 중 5!"},"2":{"who":"코그","text":"합류! 핀 씨는 합류 후에도 소리를 지르십니다!"},"1":{"who":"코그","text":"합류! 소리 지르는 데시벨이 정화방 벽을 울립니다!"}}},{"id":"M1-8","no":8,"title":"정화방 입실 거부","boss":false,"before":[{"who":"핀","text":"나는 신경 태우는 정화방에 안 가! 절대로 안 가! 바닥을 기어서라도 도망칠 거야!"},{"who":"이그니스","text":"목줄이 주인을 벗어나지 못하는 족쇄 3미터 규정을 모르는 멍청한 모양이구만."},{"who":"핀","text":"3미터 밖으로 냅다 뛰어서 나가면 되잖아!"},{"who":"코그","text":"3미터 넘으면 척추가 부서질 듯 당겨집니다! 목이 졸리는 걸 시험해 보시겠습니까!"},{"who":"핀","text":"기꺼이 시험해 본다! (미친 듯이 달린다, 철컥- 콱 당겨진다) 컥! 으아아악! 목이, 숨이 막혀!"},{"who":"로제","text":"어머, 숨이 막혀서 바닥에 나뒹굴고 당겨지는 그 압박감도 은근히 즐기시는 눈치네요."},{"who":"핀","text":"(가쁜 숨을 내쉬며) 헥, 헥... 변태처럼 즐기는 거 아니야!"}],"after":[{"who":"핀","text":"(옷이 다 구겨진 채 비틀대며) …다녀왔어. 정화방에서 아무 일도 없었어. 아무런 짓도 안 당했어."},{"who":"로제","text":"점막이 달아올라 얼굴이 새빨개요, 핀 씨."},{"who":"핀","text":"이건 쾌감이 아니라 분노야! 억울한 분노라고!"},{"who":"이그니스","text":"분노가 그렇게 허벅지를 배배 꼬면서 젤리처럼 말랑해진 건 처음 보는구만."}],"stars":{"3":{"who":"코그","text":"입실 성공! 핀 씨 불평 감소율 60%!"},"2":{"who":"코그","text":"입실 성공! 핀 씨는 퇴실 후에도 불평하십니다!"},"1":{"who":"코그","text":"입실 지연! 핀 씨가 천장 파이프에 매달리셨습니다!"}}},{"id":"M1-9","no":9,"title":"전야의 도발","boss":false,"before":[{"who":"클레어","text":"(무전 통신) 제국의 거친 주인 여러분, 안녕하세요. 내일 무자비한 전투로 만나게 되어 기쁩니다."},{"who":"베르단","text":"연방 총사령관. 정중하고 도발적인 인사에 감사한다. 내일 그쪽의 하의를 벗기고 이기는 건 우리다."},{"who":"클레어","text":"이기시면 우아하게 홍차를 대접하겠습니다. 지시면 살갗이 뜯어질 무거운 족쇄를 대접하고요."},{"who":"이그니스","text":"적장에게 주는 패배 대접이 지독하게 이상한 피학적 방향이구만."},{"who":"로제","text":"저쪽 클레어 사령관님, 묶어준다는 말씀이 아주 친절하시네요. 제가 연방에 있을 땐 저렇게 자비로운 분인 줄 몰랐는데."},{"who":"핀","text":"우리 사령관이 적군에게 족쇄를 약속하며 저렇게 다정하다니 믿을 수 없어."}],"after":[{"who":"코그","text":"내일 뼈를 부술 보스전 준비 완료! X자 구속 전차를 해체할 무식한 절단 장비도 챙겼습니다!"},{"who":"베르단","text":"좋은 밤이다. 전원 하복부 긴장 풀고 휴식하라."},{"who":"로제","text":"주인님들, 주무시기 전에 혈류를 진정시킬 따뜻한 건강 차 한 잔씩 드세요."},{"who":"이그니스","text":"이 차는 묘하게 시큼한 맛이 이상한데."},{"who":"로제","text":"근육 이완용 수면 유도제입니다. 저희가 밤에 무슨 짓을 할지 모르니 오늘은 푹 주무세요."}],"stars":{"3":{"who":"코그","text":"전야 점검 완벽! 전원 숙면 예정!"},"2":{"who":"코그","text":"점검 양호! 이그니스 상사님이 아직 눈을 뜨고 계십니다!"},"1":{"who":"코그","text":"점검 지연! 통신 기기에 홍차가 쏟아졌습니다!"}}},{"id":"M1-10","no":10,"title":"X자 구속 전차","boss":true,"before":[{"who":"연방 지휘관(목소리)","text":"제국의 천박한 주인들, 이 전차는 연방의 자랑 「X자 구속 전차」다. 촉수에 한 번 걸려서 묶이면 네놈들 힘으론 절대 풀 수 없다!"},{"who":"코그","text":"사지를 X자로 결박해서 묶는다니, 쾌락 구조적으로 이건 연구 가치가 큽니다! 강제로 해체해서 그 안을 샅샅이 보고 싶습니다!"},{"who":"베르단","text":"음탕한 기계 해체는 전투 후에 하라."},{"who":"이그니스","text":"이름만 들어도 당장 벌거벗겨진 채로 단단히 묶일 것 같구만."},{"who":"로제","text":"(침을 흘리며) 저도 헐벗고 한 번 X자로 팽팽하게 묶여 보고 싶네요."},{"who":"핀","text":"나는 수치스럽게 묶이기 싫어!"}],"after":[{"who":"코그","text":"결박 전차 무력화 및 해체 완료! 묶는 관절 구조 완벽히 파악했습니다!"},{"who":"베르단","text":"1장 종료다. 수도 방어에 성공했다."},{"who":"로제","text":"오늘 밤 제 살갗을 찢을 정화 시퀀스 예약은 제가 1빠로 먼저 콜해도 될까요?"},{"who":"이그니스","text":"예약 콜은 주인의 구두를 핥은 후 내가 허락한다!"},{"who":"핀","text":"…나는 예약 같은 천박한 콜 안 해. (슬쩍 번호표 기계로 간다)"}],"stars":{"3":{"who":"코그","text":"전차 해체! 주문 폭주 예상!"},"2":{"who":"코그","text":"전차 해체! 연방 지휘관이 구속 상태에서 행복해하십니다!"},"1":{"who":"코그","text":"전차 반파! 그런데 조종사가 내리지 않고 있습니다!"}}}]},"M2":{"chapter":"M2","title":"밤하늘 편대전","line":"male","episodes":[{"id":"M2-1","no":1,"title":"하피 야간 편대","boss":false,"before":[{"who":"코그","text":"밤하늘에 연방 하피 편대가 떴습니다! 전신 점막을 교란할 미세 깃털이 반짝입니다!"},{"who":"이그니스","text":"깃털로 신경계를 긁어 공격하겠다는 건가."},{"who":"벨루가","text":"(상공에서) 안녕, 제국 여러분! 오늘 뿌릴 발정 가스는 포도 향이야!"},{"who":"베르단","text":"아군 상공이 아니다. 즉시 대공포 요격 준비."},{"who":"로제","text":"포도 향이라면 하복부 근육을 완벽히 이완시키는 소화제 계열이네요. 점막으로 마구 흡입해도 쾌락만 오를 뿐 무해합니다."},{"who":"핀","text":"흡입하지 마! 다리에 힘 풀려서 기어 다니게 된다고 정신 차려!"}],"after":[{"who":"코그","text":"하피 편대 격퇴! 감각을 미치게 만들 깃털 12개 수집! 고문실 간지럼 장비로 쓸 수 있습니다!"},{"who":"이그니스","text":"떨어진 깃털을 주워다 자기 맨살에 비비려고 병사들이 줄 서 있구만."},{"who":"베르단","text":"그만 줍고 타격 횟수나 보고하라."}],"stars":{"3":{"who":"코그","text":"편대 격퇴 대성공! 깃털 수집 12개!"},"2":{"who":"코그","text":"격퇴 성공! 깃털 몇 개가 바람에 날아갔습니다!"},"1":{"who":"코그","text":"편대가 도주했습니다! 깃털만 남았습니다!"}}},{"id":"M2-2","no":2,"title":"달빛 아래의 점호","boss":false,"before":[{"who":"베르단","text":"야간 점호를 시작한다. 로제, 핀 하복부 수축 상태 보고하라."},{"who":"로제","text":"1번 로제입니다. 제 살갗을 찢을 정화방 고문 예약은 이미 가장 먼저 걸어 두었습니다."},{"who":"이그니스","text":"비루한 노예가 감히 주인을 제치고 먼저 쾌락을 예약하다니, 그런 게 규정에 있나."},{"who":"로제","text":"규정집 제12조에 「노예의 자발적인 굴종과 예약은 환영한다」라고 명시되어 있습니다."},{"who":"핀","text":"2번 핀. 나는 결박 예약 안 걸었어. 로제가 내 허락도 없이 멋대로 걸었어."},{"who":"로제","text":"취소하시려면 직접 고문실 앞 접수대로 가서 무릎 꿇고 말씀하세요."},{"who":"핀","text":"…안 가. 거길 지나가다가 찰진 채찍 소리라도 들리면 내 의지와 상관없이 기어들어가게 되는 건 불가피하니까."}],"after":[{"who":"코그","text":"점호 완료! 핀 씨, 정화방 문앞에서 20분이나 침을 흘리며 서 계셨습니다!"},{"who":"핀","text":"신발끈 묶고 있었어! 변태처럼 훔쳐본 거 아니야!"},{"who":"이그니스","text":"신발끈 묶는 데 20분 걸리며 허벅지를 달달 떠는 꼴은 처음 보는구만."}],"stars":{"3":{"who":"코그","text":"점호 완벽! 핀 씨 정화방 앞 대기 시간 20분!"},"2":{"who":"코그","text":"점호 양호! 핀 씨 불평 횟수 12회!"},"1":{"who":"코그","text":"점호 지연! 핀 씨가 신발끈을 세 번 푸셨습니다!"}}},{"id":"M2-3","no":3,"title":"오크 용병 야간 순찰","boss":false,"before":[{"who":"코그","text":"야간 순찰은 오크 용병대원 오그 씨와 연방 신병이 합동으로 몸을 섞으며 돕니다!"},{"who":"오그","text":"그렇게 벌벌 떨며 굳을 필요 없어요. 난 생각보다 관절을 거칠게 다루지 않는다구."},{"who":"연방 여병사","text":"저…는 평범한 사람인데요. 오크님은 그 하반신의 「사이즈」가…… 제 골반이 부서질 것…… 꺄아앗! (털썩)"},{"who":"오그","text":"대장!!! 오크 여성 좀 잡아 달라구요!!! 제 압도적인 크기에 공포를 느끼고 기절한 암컷이 이번 달 벌써 다섯째라구요!!!"},{"who":"이그니스","text":"다섯째가 아니라 오늘 야간에만 둘째구만. 아주 물리적 흉기야."},{"who":"로제","text":"어머, 쾌락에 절어 기절하신 분은 제가 인공호흡으로 깨울게요. 수치스러운 사이즈 얘기는 접어 두죠."}],"after":[{"who":"코그","text":"기절 누적 7명! 기록입니다!"},{"who":"베르단","text":"그딴 기괴한 누적 숫자를 자랑스레 낭독하지 마라."},{"who":"오그","text":"죄송합니다. 저는 짐승처럼 쑤시지 않는데 정말로 억울합니다."},{"who":"이그니스","text":"테크닉 문제가 아니라, 그냥 숨이 막히는 압도적 크기가 문제구만."}],"stars":{"3":{"who":"코그","text":"기절자 응급 처치 100%, 누적 7명!"},"2":{"who":"코그","text":"기절 7명! 로제 씨가 3명 연속 인공호흡 대신 인공 호흡기를 쓰셨습니다!"},"1":{"who":"코그","text":"기절 8명! 이번 달 기록 경신!"}}},{"id":"M2-4","no":4,"title":"핀의 불평 일기","boss":false,"before":[{"who":"핀","text":"(일기장에 꾹꾹 쓰며) 오늘의 불평: 정화방 결박 의자가 묘하게 푹신해서 불쾌했다. 오늘의 불평 2: 코그의 신경 자극 도구가 너무 정교하게 파고들어서 화가 났다."},{"who":"로제","text":"어머, 불평이 아니라 완벽하게 쾌락에 굴복한 칭찬으로 읽히는데요."},{"who":"핀","text":"아니거든! 뼈저린 수치심의 불평이거든!"},{"who":"이그니스","text":"근데 일기 마지막 줄은 뭐냐."},{"who":"핀","text":"「내일도 내 하반신을 옥죄는 이 불평을 하러 갈 것」. …이상한 발정 문장이 들어갔네. 지울게."}],"after":[{"who":"핀","text":"일기 지우다가 들켰어. 내 점막이 원해서 간 게 아니라 전부 불평이야. 정말이야."},{"who":"코그","text":"관능적인 불평의 질이 아주 좋습니다! 제국 웰니스 서적에 출판해도 되겠습니다!"},{"who":"핀","text":"출판하지 마! 내 수치심을 활자화하지 마!"}],"stars":{"3":{"who":"코그","text":"일기 압수 성공, 불평 지수 최고치!"},"2":{"who":"코그","text":"일기 일부 훼손! 핀 씨의 얼굴이 새빨갛습니다!"},"1":{"who":"코그","text":"일기 분실! 핀 씨가 침대 밑을 뒤지고 계십니다!"}}},{"id":"M2-5","no":5,"title":"옥상 추적전","boss":false,"before":[{"who":"코그","text":"연방의 차가운 저격수가 옥상에서 우리 쪽 하반신을 겨누고 있습니다! 코드네임은 실비아!"},{"who":"실비아","text":"정중하게 말씀드립니다. 제국 여러분의 허리띠만 정확히 저격하겠습니다."},{"who":"이그니스","text":"허리띠를 쏜다는 건 전장 한복판에서 바지가 바닥까지 흘러내린다는 뜻이구만."},{"who":"실비아","text":"문자 그대로 강제 노출입니다. 한 발에 한 분씩, 아주 공평하게 쏴드리죠."},{"who":"베르단","text":"침착하라. 수치심을 가릴 방패를 앞세우고 접근한다."},{"who":"로제","text":"실비아 씨는 연방 때부터 존경하던 분인데요. 제 제복 단추를 쏘아서 맨살을 드러내 주시면 영광입니다."}],"after":[{"who":"실비아","text":"(옥상에서 내려와) 정중하게 사과드립니다. 제국군 허리띠 22개 파손하여 하반신을 무력화시켰습니다."},{"who":"이그니스","text":"무자비하게 하의를 벗겨놓고 사과를 하면서 입꼬리는 귀에 걸렸구만."},{"who":"실비아","text":"수치심을 조준하는 일을 완벽히 마쳤을 때 나오는 생리적 표정입니다."},{"who":"로제","text":"실비아 씨, 저도 제발 한 번 쏘아서 옷을 찢어 주시겠어요?"},{"who":"실비아","text":"아군 하의 실종이라면 얼마든지 허락됩니다."}],"stars":{"3":{"who":"코그","text":"실비아 격퇴! 허리띠 손실 22개, 아군 피해 0!"},"2":{"who":"코그","text":"격퇴 성공! 허리띠가 지붕 위에 흩어졌습니다!"},"1":{"who":"코그","text":"실비아 도주! 허리띠만 가져갔습니다!"}}},{"id":"M2-6","no":6,"title":"로제의 선점","boss":false,"before":[{"who":"로제","text":"정화방 고문 예약이 모두 찼네요. 제 피부가 먼저 갈라지도록 먼저 다녀오겠습니다."},{"who":"핀","text":"로제! 나도 맞아야 하는데 새치기야!"},{"who":"로제","text":"새치기가 아니라 피학의 선점입니다. 살점 뜯기는 순번표 1번은 이미 제 손에 있어요."},{"who":"이그니스","text":"먼저 묶이나 나중에 묶이나 수치스러운 건 똑같은데 뭔 차이냐."},{"who":"로제","text":"매는 먼저 맞는 게 좋죠. 선점은 일찍 발정 난 새가 하는 거고, 새치기는 욕망에 굼뜬 자가 하는 거예요."},{"who":"핀","text":"나도 내일은 눈 뜨자마자 발정해서 일찍 일어난다!"}],"after":[{"who":"로제","text":"다녀왔습니다. 신경이 타들어가서 얼굴이 환해졌죠."},{"who":"핀","text":"…전혀 부럽지 않아. 살 찢기는 게 뭐가 좋다고."},{"who":"로제","text":"핀 씨는 내일 저랑 같이 묶이러 가시죠."},{"who":"핀","text":"같이 안 가! (예약 차트를 만지작거리며)"}],"stars":{"3":{"who":"코그","text":"로제 씨 선점 성공! 핀 씨의 부러움 지수 최고!"},"2":{"who":"코그","text":"선점 성공! 핀 씨가 내일 예약을 걸었습니다!"},"1":{"who":"코그","text":"선점 지연! 이그니스 상사님이 새치기하셨습니다!"}}},{"id":"M2-7","no":7,"title":"깃털 시험","boss":false,"before":[{"who":"코그","text":"수집한 하피 깃털의 극강 신경 교란 시험을 할 시간입니다! 마루타 지원자는 앞으로!"},{"who":"이그니스","text":"제국의 장인은 그런 저급한 감각 시험 대상이 아니다."},{"who":"코그","text":"그럼 핀 씨의 허벅지 안쪽에 대보겠습니다!"},{"who":"핀","text":"왜 내가! 닿지 마! 내 맨살에 대지 마! 하지…… 으하하하하!! 흣! 미칠 것 같아, 하지 마!!"},{"who":"로제","text":"어머, 점막이 긁혀서 내는 청명하고 관능적인 웃음소리네요."},{"who":"핀","text":"아니거든! 쾌락의 웃음 아니거든! 하하하하!! 제발 멈춰!!"}],"after":[{"who":"코그","text":"시험 결과, 핀 씨의 간지럼 쾌감 감도 상위 3%입니다!"},{"who":"핀","text":"상위 3%라니, 부끄럽지 않아! 초마조히스트로서 오히려 자랑스럽다!"},{"who":"이그니스","text":"수치스러운 걸 수치스럽지 않다고 뇌내망상하며 자랑스럽다고 말하는 게, 이미 뼛속까지 썩어빠진 노예구만."}],"stars":{"3":{"who":"코그","text":"시험 성공! 핀 씨 웃음 120데시벨!"},"2":{"who":"코그","text":"시험 성공! 핀 씨가 중간에 기절하셨습니다!"},"1":{"who":"코그","text":"시험 중단! 깃털이 코에 들어가 재채기가 터졌습니다!"}}},{"id":"M2-8","no":8,"title":"야간 시장","boss":false,"before":[{"who":"코그","text":"야간 시장이 열렸습니다! 음탕한 제국과 연방 상인들이 섞여 있습니다!"},{"who":"상인","text":"오늘의 인기 상품은 피부에 착 감겨 살점을 뜯는 쫀득 채찍입니다! 두 개 사면 방울 달린 입마개 하나 덤!"},{"who":"이그니스","text":"전투 중에 고문 도구 장을 보는 미친놈들이 있구만."},{"who":"로제","text":"저는 약초 코너로 가겠습니다. 고통을 극한의 쾌락으로 증폭시키는 정화 보조 약초가 있어요."},{"who":"핀","text":"나는 가죽 구속복 옷 가게에 갈래. …물론 전술적으로 필요해서 가는 거야."},{"who":"베르단","text":"가서 사 오라. 구매 목록과 타격 부위 영수증 첨부."}],"after":[{"who":"코그","text":"야간 시장 방어 성공! 변태 상인 보호 완료!"},{"who":"상인","text":"감사합니다! 등가죽을 찢어버릴 채찍 한 개 서비스로 드리겠습니다!"},{"who":"핀","text":"서비스라면 기꺼이 묶여줄게. …전투에 필요해서 묶이는 거야."}],"stars":{"3":{"who":"코그","text":"시장 방어 대성공! 서비스 상품 획득 3종!"},"2":{"who":"코그","text":"방어 성공! 상인들이 감사 인사를 길게 하셨습니다!"},"1":{"who":"코그","text":"시장 일부 파손! 보상 협상이 필요합니다!"}}},{"id":"M2-9","no":9,"title":"전야","boss":false,"before":[{"who":"베르단","text":"내일은 뼈를 부술 보스전이다. 모두 하복부 긴장 풀고 쉬어라."},{"who":"로제","text":"주인님들, 묶이느라 긴장하신 근육을 눅진하게 풀 따뜻한 최음 차를 드릴게요."},{"who":"핀","text":"나도 한 잔 줘. …내장이 떨려서 그런 게 아니라 просто 심심해서 핑계 대고 마시는 거야."},{"who":"이그니스","text":"피학을 갈구하면서 필요하다는 핑계 대는 게 아주 입에 붙었구만."},{"who":"코그","text":"저도 한 잔! 흥분해서 잠이 안 와서요!"}],"after":[{"who":"로제","text":"오늘 밤하늘이 맑네요. 내일도 피부가 찢어지는 비명이 아주 청명하게 울리겠어요."},{"who":"핀","text":"별을 보다 보니 하복부가 찌릿하며 기분이 좋아졌어. 나를 묶은 사슬 때문이 아니라 분명 별 때문이야."},{"who":"베르단","text":"조용히 해라. 좋은 밤이다."}],"stars":{"3":{"who":"코그","text":"전야 점검 완벽! 전원 숙면!"},"2":{"who":"코그","text":"점검 양호! 핀 씨가 차를 두 잔 마셨습니다!"},"1":{"who":"코그","text":"점검 지연! 로제 씨의 차가 너무 맛있어서 아무도 안 잡니다!"}}},{"id":"M2-10","no":10,"title":"깃털 편대 모함","boss":true,"before":[{"who":"벨루가","text":"(확성기) 연방 깃털 편대 모함 발진! 오늘 밤은 감각을 미치게 할 깃털이 눈처럼 네놈들 피부에 쏟아질 거야!"},{"who":"코그","text":"수만 개의 깃털이 쏟아집니다! 교감신경을 완벽히 마비시키는 간지럼 최종병기입니다!"},{"who":"이그니스","text":"깃털 폭풍이라니, 맨살에 닿으면 피부가 다 뒤집어지는 큰일이구만."},{"who":"로제","text":"신경이 다 녹아내려도 괜찮아요. 제가 더 끔찍한 주사기로 치료해 드릴게요."},{"who":"핀","text":"걸리기 싫어! 깃털에 닿으면 미쳐버릴 텐데! 아니, 걸려도 내 점막 탓이니까 어쩔 수 없지만!"}],"after":[{"who":"벨루가","text":"졌다! 하지만 신경 자극은 최고로 재밌었어! 다음엔 더 크고 거친 깃털로 긁으러 올게!"},{"who":"베르단","text":"2장 종료다. 밤하늘을 무사히 지켜냈다."},{"who":"코그","text":"간지럼 깃털 총 수집량 800개! 거대한 고문 박물관을 열어도 되겠습니다!"},{"who":"핀","text":"나는 매일 그 박물관에 출근해서 묶이진 않는다. 절대 안 간다."}],"stars":{"3":{"who":"코그","text":"모함 격파! 깃털 800개 확보!"},"2":{"who":"코그","text":"격파! 벨루가 씨가 낙하하면서도 웃고 계셨습니다!"},"1":{"who":"코그","text":"모함 반파! 깃털이 도시 전체에 내렸습니다!"}}}]},"M3":{"chapter":"M3","title":"모래 먼지 구역","line":"male","episodes":[{"id":"M3-1","no":1,"title":"슬럼가의 아침 콜","boss":false,"before":[{"who":"이그니스","text":"오늘도 어김없이…… 뼈를 깎는 정화 시퀀스다!! 하복부 꽉 조이고 긴장하는 게 좋을 거다, 연방의 암노예들아!!!"},{"who":"로제·핀·벨루가","text":"(기다렸다는 듯 꼬리를 흔들며) 네~~~~~~~~!! 찢어주세요!! (하트 뿅뿅)"},{"who":"이그니스","text":"어, 이거 왜 이래. 이봐!! 덜덜 떨며 수치심에 겁먹으란 말이다! 내 손에 든 이 무시무시하고 두꺼운 쇳덩어리 기구가 안 보이냔 말이다!!"},{"who":"로제","text":"아주 잘 보이죠!! 그 크기를 보니까 벌써 점막이 떨리며 기분 좋아진 건데요. 어서 가죠! 강제 정화방으로……"},{"who":"핀","text":"가죠! 아니, 난 결박당하고 싶어서 가는 건 아니지만! …기꺼이 가 줄게!"},{"who":"베르단","text":"노예가 발정 나서 주인의 멱살을 잡고 고문실로 끌고 가는 것은 명백한 규정 위반이다. 그러나 오늘은 눈감아 주겠다."}],"after":[{"who":"코그","text":"슬럼가 아침 전투 종료! 다리가 풀려 엎어진 병사 30명 포획!"},{"who":"이그니스","text":"점호 콜이 점점 신경망이 타오르는 신나는 변태 파티 쪽으로 가는구만."},{"who":"로제","text":"이그니스 상사님의 이성이 점점 무너지며 당황하는 쪽으로 가시는 거죠."}],"stars":{"3":{"who":"코그","text":"콜 호응도 최고! 이그니스 상사님 당황도도 최고!"},"2":{"who":"코그","text":"콜 호응 양호! 핀 씨가 이번엔 먼저 외쳤습니다!"},"1":{"who":"코그","text":"콜 호응 저조! 목이 쉬었습니다!"}}},{"id":"M3-2","no":2,"title":"모래 먼지 배급","boss":false,"before":[{"who":"코그","text":"슬럼가 주민에게 쾌락 식량을 배급하는 날입니다! 연방 병사가 피학을 원하며 습격해 옵니다!"},{"who":"주민","text":"엉덩이 까고 대는 배급 줄이 길어서 짜증 나는데 전투까지 하냐!"},{"who":"연방 병사","text":"우리는 배급 줄이 아니라 제국의 무자비한 채찍을 뺏으러 왔다!"},{"who":"이그니스","text":"줄에 서라. 몽둥이 배급은 철저히 순서대로다."},{"who":"로제","text":"점막이 찢어진 부상자부터 우선 배급입니다."},{"who":"핀","text":"나는 배급 줄을 정리할게. …내가 먼저 맞으려고 새치기하는 거 아니야. 정리하는 거야."}],"after":[{"who":"코그","text":"배급 완료! 연방 병사도 3명이 줄에 끼어 고압 전류 간식을 받아 갔습니다!"},{"who":"베르단","text":"전류 간식은 적에게도 찌릿하게 평등하다."}],"stars":{"3":{"who":"코그","text":"배급 대성공! 새치기 0건!"},"2":{"who":"코그","text":"배급 양호! 새치기 2건!"},"1":{"who":"코그","text":"배급 지연! 줄이 골목을 두 바퀴 돌았습니다!"}}},{"id":"M3-3","no":3,"title":"오크 용병대의 출동","boss":false,"before":[{"who":"그로크","text":"오크 용병대장 그로크, 무식하게 도착했다. 내게 짓밟힐 연방 여병사들은 어디 있는가."},{"who":"오그","text":"대장!!! 오크 여성 좀 잡아 달라구요!!! 제 흉악한 무기를 보고 거품 물며 기절한 암컷이 이번 달 벌써 열둘째라구요!!!"},{"who":"그로크","text":"열둘째라니, 한 달에 열둘이나 쾌락 절정으로 기절했단 말이냐."},{"who":"이그니스","text":"열둘이다. 오늘도 하복부 터져서 둘 더 늘 것 같구만."},{"who":"그로크","text":"내가 직접 나서서 짓이기겠다. 연방 여병사들이여, 그렇게 바들바들 굳을 필요 없다. 난 생각보다 짐승처럼 거칠게 다루지 않는다."},{"who":"연방 여병사","text":"저…는 보통 사람이고 그쪽은 오크이신데 그 무식한 「사이즈」가…… 제 골반을 부술…… (털썩, 기절)"},{"who":"그로크","text":"대장도 하의를 벗자마자 기절시키면 어떡하냐!"}],"after":[{"who":"코그","text":"쾌락 기절 14명으로 월 기록 경신! 응급 처치반이 전원 출동했습니다!"},{"who":"로제","text":"응급 처치는 제가 총괄하겠습니다. 기절하신 분은 제 앞으로 눕혀서 하복부를 열어 주세요."},{"who":"그로크","text":"면목 없다. 나는 정말로 거칠게 쑤시지 않는데."},{"who":"이그니스","text":"테크닉이 문제가 아니라, 그냥 숨도 못 쉬게 꽉 차는 압도적인 크기가 문제구만, 크기가."}],"stars":{"3":{"who":"코그","text":"기절 14명! 응급 처치 성공률 100%!"},"2":{"who":"코그","text":"기절 14명! 로제 씨가 처치 도중 약품을 한 통 비웠습니다!"},"1":{"who":"코그","text":"기절 15명! 이번 달 신기록!"}}},{"id":"M3-4","no":4,"title":"벨루가의 포획","boss":false,"before":[{"who":"벨루가","text":"(상공에서) 안녕, 제국 여러분! 오늘은 신경 마비 깃털 비를 뿌릴게!"},{"who":"코그","text":"개조 간지럼 그물, 발사!"},{"who":"벨루가","text":"어어, 그물이다! 근데 이거 피부를 옭아매니까 엄청 재밌게 생겼네! 아하하하! 흣!"},{"who":"이그니스","text":"그물에 묶여서 쾌감에 젖어 웃고 있구만."},{"who":"벨루가","text":"묶여서 기분 좋아 웃으면 안 돼? 흥분해서 웃으면 규정 위반이야?"},{"who":"베르단","text":"발정 나서 웃는 것은 노예의 자유다."}],"after":[{"who":"벨루가","text":"꽉 잡혔네! 이제 엎드려서 뭐 하면 돼? 정화방이 피부를 찢어줘서 쾌감 최고라는 소문 들었어!"},{"who":"코그","text":"벨루가 씨, 이 음탕한 부대에 합류하시겠습니까?"},{"who":"벨루가","text":"합류! 근데 목이 졸리는 족쇄 3미터 규정은 날개가 있어서 어떻게 돼?"},{"who":"로제","text":"파닥거리는 날개 길이를 포함해서 3미터입니다."},{"who":"벨루가","text":"그럼 3미터까지만 날다가 콱 목이 졸려 떨어지면 되네! 완전 짜릿해!"}],"stars":{"3":{"who":"코그","text":"벨루가 씨 합류! 그물 반응 최고, 웃음 소리 140데시벨!"},"2":{"who":"코그","text":"합류! 벨루가 씨가 족쇄 위에서 곡예 비행을 하십니다!"},"1":{"who":"코그","text":"합류! 벨루가 씨가 천장에 걸려 내려오지 않습니다!"}}},{"id":"M3-5","no":5,"title":"자유분방한 하피","boss":false,"before":[{"who":"벨루가","text":"뼈가 깎이는 정화방 가는 길에 하늘 한 바퀴만 돌며 애태우고 올게!"},{"who":"이그니스","text":"족쇄 3미터 규정이다. 3미터 밖으로 나가면 목이 부러진다. 멀리 못 간다."},{"who":"벨루가","text":"3미터 안에서 최대한 멀리 돌면서 내 숨통을 팽팽하게 조일게!"},{"who":"핀","text":"목줄 차고 헐떡이며 날아다니는 걸 보니 부럽지는 않지만…… 엄청나게 부러워. 나도 결박당할래."},{"who":"로제","text":"핀 씨도 목줄 매고 날고 싶으세요?"},{"who":"핀","text":"아니! 그냥 높은 곳에서 주인의 발길질에 수치스럽게 불평하고 싶을 뿐이야!"}],"after":[{"who":"벨루가","text":"정화방에서 찢기고 다녀왔어! 쾌감에 날개가 가벼워졌어!"},{"who":"로제","text":"날개가 가벼워지는 아찔한 정화는 처음 봅니다."},{"who":"코그","text":"날개 무게 12% 감소 확인!"}],"stars":{"3":{"who":"코그","text":"비행 만족도 최상! 날개 무게 12% 감소!"},"2":{"who":"코그","text":"비행 양호! 벨루가 씨가 지붕 위로 올라가 내려오지 않습니다!"},"1":{"who":"코그","text":"비행 불안정! 날개가 족쇄에 걸렸습니다!"}}},{"id":"M3-6","no":6,"title":"이번 달 기절 수 폭증","boss":false,"before":[{"who":"코그","text":"오크 용병대가 합동으로 연방 여병사의 육체를 상대합니다! 이번 달 수치심 기절 수는 현재 18명!"},{"who":"그로크","text":"대원들! 무식하게 들이박지 말고 부드럽게 접근하라! 연방 여병사들의 점막이 놀라지 않도록!"},{"who":"오그 외 대원","text":"그렇게 굳을 필요 없어요. 난 생각보다 무식하고 거칠지 않다구."},{"who":"연방 여병사 다수","text":"(줄지어) 저…는 평범한 사람인데요 하복부를 찢을 그 무식한 「사이즈」가…… (연쇄 털썩)"},{"who":"그로크","text":"오크 여성 좀 잡아 달라구요!!! 이 거대 사이즈를 버틸 암컷을 제발!!!"},{"who":"이그니스","text":"크기를 들이밀자마자 한 번에 여섯이 거품 물고 쓰러졌구만. 이게 효율인가."}],"after":[{"who":"코그","text":"기절 총 24명! 쾌락 응급 처치반 인력 부족!"},{"who":"로제","text":"인원을 늘리겠습니다. 거대한 크기를 거뜬히 버틸 오크 여성 지원자를 모집하죠."},{"who":"그로크","text":"오크 여성이 오지 않는 건 사이즈 때문이 아니라 변태적인 조건 때문이다."},{"who":"이그니스","text":"조건이 뭐냐."},{"who":"그로크","text":"상대 남성의 흉악한 사이즈가 오크보다 훨씬 커야 만족한다는 조건이다."},{"who":"베르단","text":"…그런 변태 지원자는 평생 없을 것이다."}],"stars":{"3":{"who":"코그","text":"기절 24명! 응급 처치 성공! 오크 여성 지원 공고 완료!"},"2":{"who":"코그","text":"기절 24명! 응급 처치반 휴식 시간을 연장합니다!"},"1":{"who":"코그","text":"기절 25명! 병상이 부족합니다!"}}},{"id":"M3-7","no":7,"title":"자하라의 모래 함정","boss":false,"before":[{"who":"자하라","text":"안녕하세요, 제국 여러분. 통제 구역에 오신 걸 환영합니다. 결박 통행료는 금화 3닢입니다."},{"who":"이그니스","text":"이민 구역이 제국 영토 안에 있다니, 삥 뜯는 통행료는 대체 누구에게 내는 거냐."},{"who":"자하라","text":"저에게요. 연방 소속 음탕한 상인으로서 정당하게 받습니다."},{"who":"코그","text":"함정이 있습니다! 발밑이 끈적한 모래 늪입니다!"},{"who":"자하라","text":"아직 늪에 안 빠지셨네요. 하복부를 옥죄어 질식시키는 꼬리 감기 서비스는 별도 요금입니다."},{"who":"베르단","text":"교감신경을 끊어버릴 서비스 요금표를 달라."}],"after":[{"who":"자하라","text":"이번엔 제가 졌지만 강제 포획은 안 됩니다. 제 계약서엔 묶이는 포획 조항이 없거든요."},{"who":"이그니스","text":"포획 조항이 없으면 어떻게 결박하고 굴려야 하냐."},{"who":"자하라","text":"조항을 추가하시려면 협상하셔야 합니다. 제 비늘을 벗기는 수수료는 비쌉니다."},{"who":"코그","text":"수치심 협상은 아주 끈적한 장기전이겠습니다!"}],"stars":{"3":{"who":"코그","text":"모래 함정 돌파! 자하라 씨 협상 개시!"},"2":{"who":"코그","text":"돌파 성공! 자하라 씨가 요금표를 건넸습니다!"},"1":{"who":"코그","text":"돌파 지연! 병사 일부가 모래 늪에서 휴식 중입니다!"}}},{"id":"M3-8","no":8,"title":"핀의 루틴","boss":false,"before":[{"who":"핀","text":"오늘도 신경을 태우는 정화방 예약 걸었어. 실컷 불평하러 가는 거야. 매일 채찍 맞으며 불평해야 하니까."},{"who":"로제","text":"맞으면서 헐떡이며 불평하러 가는 게 완벽히 습관이 되셨네요."},{"who":"핀","text":"습관이 아니라 노예의 의무야!"},{"who":"벨루가","text":"맞는 게 의무라면 같이 묶이러 가자! 난 습관이야!"},{"who":"이그니스","text":"습관이든 의무든 엉덩이 까고 같이 줄 서는 건 좋구만."}],"after":[{"who":"핀","text":"다녀왔어. 타격에 대한 불평은 오늘도 아주 기분 좋게 헐떡거리며 충분히 했어."},{"who":"로제","text":"긴장이 풀려 얼굴이 아주 환하게 풀어지셨네요."},{"who":"핀","text":"이건 쾌감이 아니라 억눌린 분노가 풀린 거야."}],"stars":{"3":{"who":"코그","text":"루틴 안정! 핀 씨 불평 시간 정확히 5분!"},"2":{"who":"코그","text":"루틴 양호! 핀 씨 불평이 7분으로 늘었습니다!"},"1":{"who":"코그","text":"루틴 불안정! 핀 씨가 예약 날짜를 착각했습니다!"}}},{"id":"M3-9","no":9,"title":"전야","boss":false,"before":[{"who":"베르단","text":"내일은 연방 사막 전차 「모래 상어」와 맞붙는다. 모두 하복부 긴장 늦추지 말고 휴식하라."},{"who":"벨루가","text":"나는 휴식은 날개 포박당한 채로 하늘에서 해도 돼?"},{"who":"베르단","text":"마도 족쇄 3미터 이내라면 질식하는 걸 허락한다."},{"who":"로제","text":"오늘 밤은 제가 채찍을 들고 야간 근무를 서겠습니다."},{"who":"핀","text":"나도 같이 채찍 맞으며 서. …혼자 묶여 있으면 심심하니까."}],"after":[{"who":"코그","text":"마도 족쇄 점검 완료! 내일 살점 뜯길 준비 만전입니다!"},{"who":"이그니스","text":"모래 상어는 점막을 찢는 이빨이 아주 날카롭다더구만."},{"who":"로제","text":"이빨 걱정은 필요 없습니다. 갈기갈기 찢어지면 제가 더 고통스럽게 꿰매 치료해 드리겠습니다."}],"stars":{"3":{"who":"코그","text":"점검 완벽! 전원 숙면 준비 완료!"},"2":{"who":"코그","text":"점검 양호! 벨루가 씨가 천장에서 자고 있습니다!"},"1":{"who":"코그","text":"점검 지연! 핀 씨와 로제 씨가 새벽까지 수다를 떠셨습니다!"}}},{"id":"M3-10","no":10,"title":"모래 상어","boss":true,"before":[{"who":"자하라","text":"(전차 위에서) 안녕하세요, 제국 여러분. 이 무식한 전차 「모래 상어」의 조종은 제가 맡았습니다. 깔려 뭉개지는 요금은 승리 후 청구하겠습니다."},{"who":"이그니스","text":"변태 상인이 전차 조종까지 하냐."},{"who":"자하라","text":"쾌락에 다재다능한 것이 상인의 미덕입니다. 포신 앞에 얌전히 서 주세요. 짓이겨버릴 과녁이 필요합니다."},{"who":"베르단","text":"피투성이 고기 과녁이 되라는 말이냐."},{"who":"코그","text":"포신 구조가 대단한 도전입니다! 강제로 해체해서 그 안을 샅샅이 보고 싶습니다!"}],"after":[{"who":"자하라","text":"졌네요. 하지만 이번에도 강제 포획은 안 됩니다. 도망갈 수 있는 한 도망가겠습니다."},{"who":"이그니스","text":"전차는 박살 내서 완전히 완파했구만."},{"who":"자하라","text":"깔아뭉개는 쾌락 요금은 청구하지 않겠습니다. 다음엔 꼬리로 제가 이길 겁니다."},{"who":"베르단","text":"3장 종료다. 슬럼가 방어에 무사히 성공했다."}],"stars":{"3":{"who":"코그","text":"모래 상어 격파! 자하라 씨 도주 성공!"},"2":{"who":"코그","text":"격파! 자하라 씨가 꼬리 감기로 탈출했습니다!"},"1":{"who":"코그","text":"반파! 자하라 씨가 전차에서 내리지 않고 계십니다!"}}}]},"M4":{"chapter":"M4","title":"정화 대성당","line":"male","episodes":[{"id":"M4-1","no":1,"title":"폐허의 아침 콜","boss":false,"before":[{"who":"이그니스","text":"오늘도 어김없이…… 뼈와 살을 분리하는 정화 시퀀스다!! 하복부 꽉 조이고 긴장하는 게 좋을 거다, 암노예들아!!!"},{"who":"로제·핀·벨루가","text":"(꼬리를 흔들고 헐떡이며) 네~~~~~~~~!! 무자비하게 찢어주세요!! (하트 뿅뿅)"},{"who":"로제","text":"오늘은 제 살갗이 먼저입니다. 대기표 1번 확인했습니다."},{"who":"핀","text":"2번이야. …내가 원해서가 아니라 누가 억지로 밀어 넣었지만 어쨌든 내가 2번으로 묶일 거야."},{"who":"벨루가","text":"3번! 나 날개 묶인 채로 하늘에서 줄 서 있어도 돼?"},{"who":"이그니스","text":"어, 이거 왜 이래. 부들부들 떨며 겁먹으란 말이다! 이 무시무시한 기구가 안 보이냔 말이다!!"},{"who":"로제","text":"그 흉악한 크기가 너무 잘 보이니까 안달 나서 줄 서는 겁니다. 어서 가죠, 고문실로……"}],"after":[{"who":"코그","text":"다리가 풀린 병사 28명 포획! 노예들의 쾌락 예약 경쟁률은 3대 1입니다!"},{"who":"이그니스","text":"주인이 노예들 예약 경쟁에 밀려서 채찍을 못 드는 건 규정에 없는데."},{"who":"베르단","text":"규정집 제15조, 「노예의 피학적 기대와 발정은 존중한다」."}],"stars":{"3":{"who":"코그","text":"콜 호응 최고! 경쟁률 3대 1!"},"2":{"who":"코그","text":"호응 양호! 핀 씨가 새치기를 시도했습니다!"},"1":{"who":"코그","text":"호응 저조! 이그니스 상사님 목소리가 갈라졌습니다!"}}},{"id":"M4-2","no":2,"title":"순번표 경쟁","boss":false,"before":[{"who":"코그","text":"고전압 정화방 앞 대기열이 폭주합니다! 수치심 번호표 1~3번을 둘러싼 피 튀기는 암투가 벌어지고 있습니다!"},{"who":"로제","text":"번호표는 저와 핀 씨, 벨루가 씨가 얌전히 가위바위보로 정하죠."},{"who":"벨루가","text":"가위바위보는 내가 제일 잘해! 포박당할 날개로 가위를 만들 수 있거든!"},{"who":"핀","text":"깃털 달린 날개는 반칙이야!"},{"who":"베르단","text":"고문 순번 문제로 전투가 지연되고 있다. 신속히 결박 순서를 해결하라."},{"who":"연방 병사","text":"(바닥을 기며) 우리도 찢어질 번호표가 필요하다!"}],"after":[{"who":"코그","text":"번호표 문제 해결! 로제 씨 1번, 벨루가 씨 2번, 핀 씨 3번!"},{"who":"핀","text":"내가 3번이라니 제일 늦게 맞아야 해서 부당해! …하지만 3번 동안 애타게 기다리는 쾌감도 괜찮아."},{"who":"이그니스","text":"노예들의 변태적인 순번 다툼이 주인의 타격 일정을 결정하는 기괴한 구조구만."}],"stars":{"3":{"who":"코그","text":"순번 분쟁 해결! 가위바위보 대회 개최!"},"2":{"who":"코그","text":"분쟁 해결! 벨루가 씨의 날개 가위가 심판에게 걸렸습니다!"},"1":{"who":"코그","text":"분쟁 지속! 줄이 건물 하나를 감쌌습니다!"}}},{"id":"M4-3","no":3,"title":"폐허의 보급","boss":false,"before":[{"who":"코그","text":"대성당 주변 폐허에 보급 상자가 흩어져 있습니다! 연방도 쾌락 도구를 노리고 있습니다!"},{"who":"이그니스","text":"상자 안에 대체 무슨 흉악한 게 들었는지 아직 모른다."},{"who":"로제","text":"열어 보지 않으면 모르죠. 피부를 녹이는 부상자 치료 약품이면 좋겠는데."},{"who":"핀","text":"상자에 숨통을 조일 구속 도구가 들어 있으면 좋겠어. 아니 쾌락이 필요해서가 아니라 순전히 전술적인 전투 목적으로."},{"who":"벨루가","text":"나는 신경을 마비시킬 깃털이 들어 있으면 좋겠어!"}],"after":[{"who":"코그","text":"상자 개봉! 점막 약품 20, 살점 뜯는 쫀득 채찍 5, 극강 간지럼 깃털 100!"},{"who":"벨루가","text":"깃털이다! 발정 소원이 이뤄졌어!"},{"who":"로제","text":"위험한 약품은 제가 정리하겠습니다."},{"who":"핀","text":"채찍은…… 내 몸에 감아서 보관할게. 철저히 전투 목적으로."}],"stars":{"3":{"who":"코그","text":"보급 대성공! 상자 5개 전부 확보!"},"2":{"who":"코그","text":"확보! 상자 하나가 연방 쪽에 넘어갔습니다!"},"1":{"who":"코그","text":"확보 실패! 상자 대부분이 파손되었습니다!"}}},{"id":"M4-4","no":4,"title":"아네트의 대성당","boss":false,"before":[{"who":"아네트","text":"(대성당 첨탑 위에서) 제국 여러분, 연방 신경 교란 빔 첨탑에 접근하셨습니다. 입장은 예약제입니다."},{"who":"이그니스","text":"전투 중에 고문실 예약제를 적용하냐."},{"who":"아네트","text":"상담소 규정입니다. 빔 한 발에 하복부 정화 한 건. 대기 번호를 뽑아 주세요."},{"who":"코그","text":"대단한 가학 장비입니다! 당장 해체해서 그 구조를 파악하고 싶습니다!"},{"who":"베르단","text":"음탕한 해체는 전투 후에 하라."},{"who":"로제","text":"아네트 씨를 본 적이 있는 것 같은데, 연방의 악명 높은 의무 동료인가요."},{"who":"아네트","text":"로제 선배님, 오랜만입니다. 선배님을 묶을 차트를 가져왔습니다."}],"after":[{"who":"아네트","text":"(첨탑 위에서) 빔 출력 70%로 마무리하겠습니다. 전원 포획 대신 자발적 굴종 안내를 드리겠습니다."},{"who":"코그","text":"안내는 고전압 정화방 입구입니다!"},{"who":"로제","text":"후배의 솜씨가 너무 훌륭하게 잔혹해서 기쁨의 눈물이 나네요."}],"stars":{"3":{"who":"코그","text":"첨탑 돌파! 빔 피격 0, 아네트 씨 인사 완료!"},"2":{"who":"코그","text":"돌파! 빔에 맞은 병사 여럿이 행복한 얼굴로 쓰러졌습니다!"},"1":{"who":"코그","text":"돌파 지연! 빔의 아름다움에 눈이 팔렸습니다!"}}},{"id":"M4-5","no":5,"title":"자하라의 흥정","boss":false,"before":[{"who":"자하라","text":"안녕하세요, 제국 여러분. 또 뵙네요. 이번엔 대성당 안에 있는 연방 상인으로서 수치심 입장료를 받습니다."},{"who":"이그니스","text":"입장료를 또 삥 뜯냐."},{"who":"자하라","text":"음탕한 장사입니다. 그런데 이번엔 꼬리가 말려서 움직임이 둔합니다. 제가 묶이기 불리하군요."},{"who":"코그","text":"신경 마비 개조 그물 발사!"},{"who":"자하라","text":"이번엔 꽉 걸렸네요. 쾌락 흥정할까요. 저를 풀어 주시면 금화 100닢을 드리겠습니다."},{"who":"베르단","text":"거절한다."},{"who":"자하라","text":"200닢."}],"after":[{"who":"자하라","text":"졌습니다. 강제 포획 조항이 계약서에 없으니 협상해야 하는데요. 정화방 쾌락 이용 요금은 월정액이죠?"},{"who":"로제","text":"피 튀기는 월정액입니다."},{"who":"자하라","text":"월정액이면 이득이네요. 합류하겠습니다. 단, 월말 정산 때 타격 이용 횟수 할인을 요구합니다."},{"who":"이그니스","text":"맞는 이용 횟수 할인이라니, 더 많이 처맞을수록 이득이라는 얘기구만."}],"stars":{"3":{"who":"코그","text":"자하라 씨 합류! 월정액 계약 체결!"},"2":{"who":"코그","text":"합류! 요금 협상이 길어졌습니다!"},"1":{"who":"코그","text":"합류했는데 계약서 문구가 모호합니다!"}}},{"id":"M4-6","no":6,"title":"세뇌된 전우","boss":false,"before":[{"who":"코그","text":"연방 진영에서 목줄 찬 두 사람이 나왔습니다! 제국 출신 렌 중위와 카이단 씨!"},{"who":"이그니스","text":"렌! 카이단! 하복부 힘 꽉 주고 정신 차려라! 너희는 긍지 높은 제국군이다!"},{"who":"렌","text":"나는 연방의 완벽한 노예다. 이것은 내 신념이 무너진 게 아니라 몸이 채찍에 먼저 간 결과일 뿐이다."},{"who":"카이단","text":"주인님이 구두로 부르셨어요! 이그니스 상사님, 미안해요, 발정 난 꼬리가 말을 안 들어요!"},{"who":"베르단","text":"피학적 세뇌가 아주 깊다. 단순한 정화로 뇌를 풀 수는 없다."},{"who":"로제","text":"저는 이쪽이 더 부럽네요. 신경이 무너지는 세뇌 속도가 훌륭합니다."}],"after":[{"who":"렌","text":"…후퇴한다. 거듭 말하지만 몸이 먼저 갔을 뿐이다."},{"who":"카이단","text":"이그니스 상사님, 다음에 또 만나요! 목줄 매고 꼬리 흔들면서!"},{"who":"이그니스","text":"세뇌당해서 바닥을 기는 놈이 저렇게 쾌락에 절어 행복한 얼굴을 하다니."},{"who":"베르단","text":"다음 전투에서 반드시 목줄을 낚아채 되찾는다."}],"stars":{"3":{"who":"코그","text":"전우 격퇴! 렌 중위 도주, 카이단 씨 꼬리 반응 측정 완료!"},"2":{"who":"코그","text":"격퇴! 카이단 씨가 이그니스 상사님 손을 핥으려 했습니다!"},"1":{"who":"코그","text":"격퇴 지연! 렌 중위가 전술적으로 안전한 거리를 유지했습니다!"}}},{"id":"M4-7","no":7,"title":"폐허의 야식","boss":false,"before":[{"who":"로제","text":"야식 시간입니다. 폐허 한가운데서 체온을 덥힐 컵라면 드릴게요."},{"who":"핀","text":"컵라면이라니, 전투 중에 긴장 풀고 먹냐."},{"who":"벨루가","text":"나는 곱빼기!"},{"who":"자하라","text":"컵라면 한 컵에 금화 2닢입니다. 묶인 노예 할인 적용해서 1닢."},{"who":"이그니스","text":"노예 할인이란 것도 있구만."},{"who":"베르단","text":"군대를 이끄는 장군도 할인 대상인가."},{"who":"자하라","text":"대상입니다. 단, 서비스 시간 후에는 가학적인 추가 요금이 붙습니다."}],"after":[{"who":"코그","text":"야식 만족도 5점 만점!"},{"who":"핀","text":"국물이 따뜻해서 점막이 찌릿하고 기분이 좋아졌어. …수치심 때문이 아니라 분명 국물 때문이야."},{"who":"로제","text":"국물이 하복부를 덥히긴 하죠."}],"stars":{"3":{"who":"코그","text":"야식 대성공! 컵라면 재고 소진!"},"2":{"who":"코그","text":"성공! 벨루가 씨가 곱빼기 두 컵을 드셨습니다!"},"1":{"who":"코그","text":"야식 중단! 연방 병사가 컵라면을 훔쳐 갔습니다!"}}},{"id":"M4-8","no":8,"title":"로나의 방어선","boss":false,"before":[{"who":"로나","text":"(연방 장교) 제국의 무식한 주인들, 이 방어선은 제가 지킵니다. 방어선 너머는 연방의 완벽한 훈육 상담소 구역입니다."},{"who":"그로크","text":"로나 교관님! 오늘도 제 비루한 평가는 밑바닥 하로 부탁드립니다!"},{"who":"오그","text":"대장!!! 무릎 꿇고 어디 가시는 겁니까!!! 우리 거친 오크 용병대는 제국 소속이라구요!!!"},{"who":"그로크","text":"나는 이제 연방의 충실한 가축 소속이다. 로나 교관님의 무자비한 조련을 받는 중이다."},{"who":"이그니스","text":"대장 놈이 채찍 맛을 보더니 완전히 연방으로 넘어갔구만."},{"who":"오그","text":"오크 여성 좀 잡아 달라구요!!! 대장이 안 잡아주면 제 흉악한 크기는 누가 감당해요!!!"}],"after":[{"who":"로나","text":"방어선은 오늘까지입니다. 오크 용병대 여러분, 굴욕 반성문 5장씩."},{"who":"오그","text":"5장씩이라니! 대장님은 6장 쓰셨다던데!"},{"who":"그로크","text":"6장째는 끈적한 내 선물이다. 잔말 말고 받아라."},{"who":"로나","text":"더럽지만 일단 접수합니다."}],"stars":{"3":{"who":"코그","text":"방어선 돌파! 오크 용병대 반성문 접수 완료!"},"2":{"who":"코그","text":"돌파! 그로크 대장이 끝까지 로나 교관을 따라다녔습니다!"},"1":{"who":"코그","text":"돌파 지연! 오크 용병대가 대장을 되찾으려 했습니다!"}}},{"id":"M4-9","no":9,"title":"베르단 친위대","boss":false,"before":[{"who":"베르단","text":"친위대는 나를 따르라. 오늘은 대성당 중심부로 진입한다."},{"who":"친위대원","text":"장군님, 저희 숨통을 조일 족쇄 점검 시간입니다! 전투보다 목줄이 먼저 헐거워져서 숨이 안 쉬어집니다! 먼저 해도 되겠습니까!"},{"who":"베르단","text":"점검 시간은 전투 후다."},{"who":"친위대원","text":"지금 당장 조이지 않으면 안 됩니다! 장력이 헐거워서 심리적으로 불안합니다!"},{"who":"이그니스","text":"근엄한 친위대 놈들도 발정 난 노예 못지않구만."},{"who":"베르단","text":"규정집을 똑바로 읽어라. 목줄 점검은 월례다."}],"after":[{"who":"베르단","text":"점검을 시작한다. 호흡 압박 장력 확인."},{"who":"친위대원","text":"감사합니다! 장군님의 압박 확인이면 완벽히 안심됩니다!"},{"who":"로제","text":"친위대원 전원 피학 만족도 최상이네요."}],"stars":{"3":{"who":"코그","text":"친위대 점검 완료! 장력 전원 합격!"},"2":{"who":"코그","text":"점검 양호! 일부 대원이 장군님께 직접 점검을 요청했습니다!"},"1":{"who":"코그","text":"점검 지연! 대원들이 줄을 서서 기다립니다!"}}},{"id":"M4-10","no":10,"title":"정화 빔 첨탑 대성당 기체","boss":true,"before":[{"who":"아네트","text":"(성당 기체 위에서) 제국 여러분, 본 기체는 정화 빔 첨탑 대성당 기체입니다. 일제 하복부 정화를 시작하겠습니다."},{"who":"코그","text":"대단합니다! 신경 교란 빔이 사방으로 퍼집니다!"},{"who":"이그니스","text":"저 흉악한 빔에 맞으면 어떻게 되냐."},{"who":"로제","text":"쾌락에 절어 뇌가 녹고 미친 듯이 행복해집니다."},{"who":"베르단","text":"행복해지면 이성이 날아가 전투가 안 된다. 접근해서 파괴한다."},{"who":"핀","text":"억지로 행복해지는 건 싫어! …아니, 느껴서 싫은 게 아니라 전투 때문에!"}],"after":[{"who":"아네트","text":"기체가 파괴되었습니다. 오늘 점막 상담은 여기까지입니다."},{"who":"로제","text":"후배님, 유린하느라 수고했어요."},{"who":"베르단","text":"4장 종료다. 쾌락의 대성당을 점령했다."},{"who":"코그","text":"빔 장비 해체 완료! 다음 전투에서 제 몸에 쏴 써 보고 싶습니다!"}],"stars":{"3":{"who":"코그","text":"대성당 기체 파괴! 빔 장비 확보!"},"2":{"who":"코그","text":"파괴! 빔에 맞은 병사들이 행복하게 쓰러졌습니다!"},"1":{"who":"코그","text":"반파! 빔이 사방으로 퍼져 도심에 분홍빛이 드리웠습니다!"}}}]},"M5":{"chapter":"M5","title":"강철 군주의 결단","line":"male","episodes":[{"id":"M5-1","no":1,"title":"총공세의 아침, 거꾸로 콜","boss":false,"before":[{"who":"로제·핀·벨루가·자하라","text":"오늘도 어김없이…… 뼈와 살을 분리하는 정화 시퀀스다!! 하복부 꽉 조이고 긴장하는 게 좋을 거예요, 비루한 주인님들!!!"},{"who":"이그니스","text":"…그, 그건 내가 몽둥이를 들고 쳐야 할 대사다."},{"who":"핀","text":"내가 제일 먼저 외친 거야. 먼저 매 맞기 싫으면 불평하지 마."},{"who":"베르단","text":"발정 난 노예가 먼저 콜하는 것은 규정 위반이 아니다. 제17조, 「피학의 콜은 선착순」이다."},{"who":"이그니스","text":"그런 해괴하고 수치스러운 조항이 있었나."},{"who":"코그","text":"어제 제가 흥분해서 추가했습니다!"},{"who":"자하라","text":"먼저 맞는 선착순이면 쾌락의 이득이네요."}],"after":[{"who":"코그","text":"총공세 첫 방어 성공! 다리가 풀린 병사 45명 포획!"},{"who":"이그니스","text":"콜에서 밀려 수치당한 주인이 전투에서는 이기는구만."},{"who":"로제","text":"음탕한 콜은 노예의 몫, 거칠게 짓밟는 전투는 주인의 몫이죠."}],"stars":{"3":{"who":"코그","text":"첫 방어 대성공! 콜 호응도 폭발!"},"2":{"who":"코그","text":"방어 성공! 이그니스 상사님이 콜에서 밀리셨습니다!"},"1":{"who":"코그","text":"방어 지연! 콜 순서 다툼이 있었습니다!"}}},{"id":"M5-2","no":2,"title":"전선이 흔들린다","boss":false,"before":[{"who":"베르단","text":"연방 주력 부대가 평원에 집결했다. 가학적 사기가 몹시 높다."},{"who":"연방 병사","text":"우리는 제국을 정복한다! 아니, 포획되면 짜릿한 전극 간식을 준다고 들었다!"},{"who":"이그니스","text":"우리 쪽 고문실도 쾌감이 훌륭하다는 소문이 퍼졌구만."},{"who":"로제","text":"전극 간식은 사실입니다. 하의를 벗고 포획된 직후 바로 점막에 지급됩니다."},{"who":"연방 병사","text":"정말로 전류가 흐르는 간식이다! 당장 우리를 포획해 달라!"},{"who":"베르단","text":"스스로 결박당하길 부탁하는 적은 처음 본다."}],"after":[{"who":"코그","text":"전선 정리 완료! 간식 재고 전량 소진!"},{"who":"이그니스","text":"피 튀기는 전쟁이 아니라 단체 발정 야유회구만."},{"who":"핀","text":"나는 이 미친 야유회에서 바닥을 구르며 불평하는 게 일이야."}],"stars":{"3":{"who":"코그","text":"전선 정리! 간식 재고 완벽 배분!"},"2":{"who":"코그","text":"정리 양호! 간식이 부족해서 눈물 흘린 병사가 있습니다!"},"1":{"who":"코그","text":"정리 지연! 간식 줄이 평원을 가로지릅니다!"}}},{"id":"M5-3","no":3,"title":"자하라의 마지막 흥정","boss":false,"before":[{"who":"자하라","text":"제국 여러분, 사령부에 음탕한 보급품을 납품하러 왔습니다. 가격은 시가의 반값입니다."},{"who":"이그니스","text":"수치심을 팔아먹는 년이 반값이면 의심스럽구만."},{"who":"자하라","text":"고통을 즐기는 월정액 구독자 할인입니다. 저는 정화방 쾌락 월정액 구독자니까요."},{"who":"베르단","text":"노예 구독자 할인이 군수품에도 적용되는가."},{"who":"자하라","text":"적용됩니다. 대신 제 점막을 찢어줄 정화방 이용 횟수를 두 배로 늘려 주세요."},{"who":"코그","text":"그렇게 무자비한 요구는 협상 불가입니다! …아니 제 신경계 연구를 위해 협상 가능합니다!"}],"after":[{"who":"자하라","text":"계약 완료. 채찍질 이용 횟수는 두 배로, 요금은 반값."},{"who":"이그니스","text":"처맞는 횟수를 늘린 상인이 이기는 기괴한 구조구만."},{"who":"자하라","text":"뇌가 녹아내리는 이득이 되는 거래만 합니다."}],"stars":{"3":{"who":"코그","text":"납품 계약 체결! 이용 횟수 두 배!"},"2":{"who":"코그","text":"계약 체결! 자하라 씨가 추가 조항을 요구했습니다!"},"1":{"who":"코그","text":"계약 보류! 협상이 길어졌습니다!"}}},{"id":"M5-4","no":4,"title":"핀의 자진 대기","boss":false,"before":[{"who":"핀","text":"(고문 정화방 앞에서 대기 번호표를 꽉 쥐고) 오늘은 내가 먼저 얌전히 줄 섰어. 가장 찢기기 좋은 앞줄이야."},{"who":"로제","text":"어머, 핀 씨가 자진해서 엉덩이 까고 줄 서시다니."},{"who":"핀","text":"자진한 거 아니야! 앞줄에 서서 매를 맞아야 불평을 더 빨리 할 수 있으니까!"},{"who":"벨루가","text":"그럼 나도 앞줄! 포박당한 채로 하늘에서 줄 서도 되지?"},{"who":"이그니스","text":"공중에 매달린 채로 채찍 맞으려고 줄 서는 건 처음 보는구만."}],"after":[{"who":"핀","text":"(옷이 다 찢어진 채로) 불평 끝. …하복부가 짜릿하게 기분이 좋아졌어. 타격에 대한 불평 때문이야."},{"who":"로제","text":"핀 씨, 이제 불평과 쾌락의 경계가 완전히 녹아 없어지고 있어요."},{"who":"핀","text":"경계가 없어진 게 아니라 내 피학적 수용력이 넓어진 거야."}],"stars":{"3":{"who":"코그","text":"핀 씨 자진 대기 성공! 불평 시간 5분!"},"2":{"who":"코그","text":"대기 성공! 불평 시간이 9분으로 늘었습니다!"},"1":{"who":"코그","text":"대기 불안정! 핀 씨가 순서를 착각하고 뒷줄에 서셨습니다!"}}},{"id":"M5-5","no":5,"title":"구속 대전","boss":false,"before":[{"who":"베르단","text":"이번 전투는 「집단 구속 대전」이다. 쌍방이 서로를 무자비하게 묶는 방식이다."},{"who":"코그","text":"대단한 가학 전술입니다! 전원 사지가 묶이면 아무도 못 움직이며 쾌락에 절게 됩니다!"},{"who":"이그니스","text":"그게 목적이라니, 이건 전술이 아니라 변태들의 취향이구만."},{"who":"연방 병사","text":"우리도 구속 대전에 참가한다! 묶여서 유린당할 준비 완료!"},{"who":"제국 병사","text":"우리도다! 밧줄에 묶이러 달려간다!"}],"after":[{"who":"연방 병사","text":"(거꾸로 묶인 채로 헐떡이며) 이기고 있는지 지고 있는지 모르겠지만 점막이 터질 듯이 행복하다."},{"who":"제국 병사","text":"(묶인 채 몸을 비틀며) 저도 마찬가지다. 밧줄이 파고들고 있다."},{"who":"로제","text":"이 미친 쾌락의 승패 판정은 코그 씨가 맡으시죠."},{"who":"코그","text":"결박의 쌍방 승리입니다!"}],"stars":{"3":{"who":"코그","text":"구속 대전 대성공! 쌍방 만족도 100%!"},"2":{"who":"코그","text":"성공! 일부 병사가 묶인 채로 잠들었습니다!"},"1":{"who":"코그","text":"판정 불가! 쌍방 모두 즐거워서 기록이 어렵습니다!"}}},{"id":"M5-6","no":6,"title":"이그니스의 변화","boss":false,"before":[{"who":"이그니스","text":"오늘 살을 찢는 정화 시퀀스는 평소처럼 단호하게 하겠다. 로제, 오늘 타격 일정표를 다오."},{"who":"로제","text":"이그니스 상사님, 오늘은 하복부의 떨림도 없이 아주 담담하시네요."},{"who":"이그니스","text":"수치심과 당황은 이제 내게 필요 없구만. 철저한 업무다. 가학적 업무."},{"who":"핀","text":"이그니스 상사가 부들부들 당황하며 수치스러워하지 않는 건 재미없어."},{"who":"이그니스","text":"변태적인 재미는 내 무자비한 업무에 포함되지 않는다."},{"who":"벨루가","text":"그래도 귀끝부터 목덜미까지 얼굴이 새빨개졌는데!"},{"who":"이그니스","text":"이, 이건 용광로의 뜨거운 열기다."}],"after":[{"who":"이그니스","text":"타격 일정 종료. 피학 보고서 제출."},{"who":"코그","text":"상사님이 직접 쾌락 보고서를 쓰시다니! 내용이 몹시 궁금합니다!"},{"who":"이그니스","text":"내 은밀한 점막에 관한 기밀이다."}],"stars":{"3":{"who":"코그","text":"일정 완벽! 이그니스 상사님 업무 어조 100%!"},"2":{"who":"코그","text":"일정 양호! 보고서에 얼룩이 한 점 보입니다!"},"1":{"who":"코그","text":"일정 지연! 이그니스 상사님이 중간에 얼굴이 빨개졌습니다!"}}},{"id":"M5-7","no":7,"title":"루시안의 합류","boss":false,"before":[{"who":"코그","text":"연방에서 엘프 한 분이 스스로 기어서 이쪽으로 넘어왔습니다! 근위대장 루시안 씨!"},{"who":"루시안","text":"제국 여러분, 연방에서 해방된 동포라고 극진히 환영해 주셔서 감사합니다. 다만 한 가지 신경이 곤두서는 불편한 점이 있습니다."},{"who":"베르단","text":"말하라."},{"who":"루시안","text":"내 목을 조이는 목줄이 없습니다. 연방 시절에는 항상 차가운 가죽을 착용했는데, 지금은 목이 허전해서 호흡이 너무 편안해 미치게 힘듭니다."},{"who":"이그니스","text":"제 발로 걸어와서 숨통을 조여달라며 목줄을 달라는 놈은 처음 보는구만."},{"who":"루시안","text":"뼈에 새겨진 모범 노예로서의 생리적 습관입니다."}],"after":[{"who":"코그","text":"기도를 압박할 개조 목줄 제작 완료! 루시안 씨, 착용해 보세요!"},{"who":"루시안","text":"(철컥- 착용) …숨이 막히게 딱 맞습니다. 감사합니다. 이제 편안히 피학에 젖어 일할 수 있습니다."},{"who":"베르단","text":"루시안을 주인 팀에 편입한다. 마도사의 역할은 가학적 지원이다."},{"who":"루시안","text":"채찍을 쥐는 주인이 되는 것은 처음이라 몹시 어색합니다만, 모범적인 폭군 주인이 되겠습니다."}],"stars":{"3":{"who":"코그","text":"루시안 씨 합류! 개조 목줄 만족도 최상!"},"2":{"who":"코그","text":"합류! 루시안 씨가 주인 역할에 어색해하십니다!"},"1":{"who":"코그","text":"합류! 루시안 씨가 목줄을 두 개 요청하셨습니다!"}}},{"id":"M5-8","no":8,"title":"셀렌의 분노","boss":false,"before":[{"who":"셀렌","text":"(연방 마도사) 루시안! 당신이 목줄을 채워주는 제국으로 넘어갔다는 소문이 사실이었군요!"},{"who":"루시안","text":"셀렌. 오랜만입니다. 동료의 뼈를 부수며 싸우고 싶지는 않습니다."},{"who":"셀렌","text":"매일 발밑을 기던 모범 노예였던 당신이 어떻게 구두를 신은 주인이 될 수 있나요!"},{"who":"루시안","text":"규정집을 읽어 보면 가학적 자격 조건에 「본인의 비틀린 의지」가 있습니다."},{"who":"셀렌","text":"본인의 의지라니…… 그건 제 더러운 꿈이기도 했는데!"},{"who":"이그니스","text":"그 더러운 꿈이 뭐냐."},{"who":"셀렌","text":"무자비한 주인이 되는 거예요. …아니, 목줄 찬 노예인 채로 누군가를 짓밟는 주인도 되는 거요."}],"after":[{"who":"셀렌","text":"…졌습니다. 하지만 분하지 않습니다. 제국군의 압도적인 구속구에 묶이니 오히려 후련합니다."},{"who":"루시안","text":"셀렌, 이쪽으로 오시겠습니까. 제국 쪽 변태 규정집은 훨씬 더 유연합니다."},{"who":"셀렌","text":"진지하게 생각해 보겠습니다. 다만 오늘은 제 찢어진 하의를 부여잡고 돌아가야 합니다."},{"who":"베르단","text":"다음에 더 단단히 묶어주마, 만나자."}],"stars":{"3":{"who":"코그","text":"셀렌 씨 격퇴! 규정집 대화 성공!"},"2":{"who":"코그","text":"격퇴! 셀렌 씨의 눈이 약간 촉촉했습니다!"},"1":{"who":"코그","text":"격퇴 지연! 규정집 해석 논쟁이 길어졌습니다!"}}},{"id":"M5-9","no":9,"title":"전야의 거꾸로 점검","boss":false,"before":[{"who":"로제","text":"오늘은 제가 꿇어앉아 주인님들의 숨통을 죌 족쇄를 꽉꽉 점검할게요."},{"who":"이그니스","text":"비천한 노예가 감히 주인의 점막을 점검하다니."},{"who":"로제","text":"짜릿한 가학 역할 교대입니다. 규정집 제18조."},{"who":"핀","text":"나도 거칠게 점검해 볼래. 이그니스 상사의 목줄 장력은 어디 보자."},{"who":"이그니스","text":"만지지 마라. 읏, 아니, 내 목을 꽉 졸라도 된다."},{"who":"벨루가","text":"나는 베르단 장군님을 밧줄로 묶고 점검!"},{"who":"베르단","text":"점검은 나를 존중하며 꽉 조여 하라."}],"after":[{"who":"코그","text":"점검 완료! 전원 호흡이 곤란한 장력 98%!"},{"who":"루시안","text":"어느 쪽이 채찍을 쥔 주인이고 어느 쪽이 묶인 노예인지 완벽히 모호해졌습니다."},{"who":"로제","text":"뒤섞이고 모호해야 가장 음탕하고 평화롭죠."}],"stars":{"3":{"who":"코그","text":"거꾸로 점검 대성공! 장력 전원 합격!"},"2":{"who":"코그","text":"점검 양호! 역할이 뒤섞였습니다!"},"1":{"who":"코그","text":"점검 혼란! 아무도 누가 주인인지 모릅니다!"}}},{"id":"M5-10","no":10,"title":"총사령관 클레어 기체","boss":true,"before":[{"who":"클레어","text":"(기체 위에서) 제국 총사령관 베르단 장군님, 혈류를 덥힐 홍차를 준비했습니다. 뼈가 부서진 전투 후에 드시죠."},{"who":"베르단","text":"연방 총사령관 클레어. 귀하의 무자비한 족쇄 규정 개정안이 참으로 가학적이라 감동적이었다."},{"who":"클레어","text":"귀하의 행동을 옭아매는 3미터 족쇄 규정 개정안도 아주 잔혹하고 훌륭했습니다."},{"who":"이그니스","text":"사령관 둘이 서로의 변태적인 구속구 칭찬만 하고 있구만."},{"who":"코그","text":"집단 구속 대전 개시 신호를 보내겠습니다!"},{"who":"연방·제국 병사","text":"(전원 하의를 벗고 밧줄에 자진해서 묶이러 미친 듯이 달려간다)"},{"who":"로제","text":"전선이 흔들립니다. 피를 흘려서가 아니라, 양쪽 병사 모두 묶일 생각에 발정 나서 뿜어내는 열기 때문에 기뻐서요."}],"after":[{"who":"클레어","text":"제가 졌습니다. 기체가 완파되는 훌륭한 쾌락의 승부였어요."},{"who":"베르단","text":"귀하도 유린당하는 모습이 훌륭했다. 홍차는 묶인 채로 여기서 마시겠다."},{"who":"로제","text":"하늘을 보세요. 시공간의 점막을 찢어발긴 듯한 기괴한 분홍빛 균열이 보입니다."},{"who":"베르단","text":"…무엇을 토해낼지 정체를 알 수 없는 끈적한 빛이다. 하복부 경계 태세를 유지한다."},{"who":"이그니스","text":"5장 종료구만. 하지만 이 더러운 웰니스의 끝이 아닌 것 같다."},{"who":"핀","text":"하늘이 갈라졌어. …저 너머에서 더 끔찍한 채찍이 날아올 것 같아 왠지 설렌다."}],"stars":{"3":{"who":"코그","text":"클레어 기체 격파! 쌍방 병사 만족도 최상, 상공 균열 관측!"},"2":{"who":"코그","text":"격파! 균열이 일시적으로 확대되었습니다!"},"1":{"who":"코그","text":"반파! 균열의 정체를 파악하지 못했습니다!"}}}]},"C11":{"chapter":"C11","title":"마계","line":"demon","episodes":[{"id":"C11-1","no":1,"title":"균열의 문","boss":false,"before":[{"who":"클레어","text":"분홍빛 균열이 마계의 끈적한 문으로 열렸습니다. 베르단 장군, 우리끼리 살을 찢는 건 잠시 미루고 임시 휴전을 제안드립니다."},{"who":"베르단","text":"받아들이겠다. 정중하고 단호한 문서로 서명하자."},{"who":"클레어","text":"휴전 협정서입니다. 제3조 「족쇄 규정은 양측의 무자비한 규정집을 병기한다」."},{"who":"베르단","text":"병기하는 것은 좋으나 서명 위치가 문제다. 「서명자의 가장 짓밟기 편한 위치」."},{"who":"클레어","text":"…종이 문서 위치입니다. 오해 없으시길."},{"who":"몽마 병사","text":"(문 너머에서 채찍을 들고) 어서 오세요! 환영합니다! 입장과 하복부 고문은 철저한 예약제입니다!"}],"after":[{"who":"베르단","text":"문 앞 병력 무력화 격퇴. 양국 연합군이 정식으로 결성되었다."},{"who":"클레어","text":"연합 이름은 「정화 연합」으로 하죠. 상표는 이미 저희가 등록했습니다."},{"who":"베르단","text":"가학적 상표는 우리가 먼저였다."},{"who":"클레어","text":"결박과 연합 결성 후에 다투기로 합시다."}],"stars":{"3":{"who":"클레어","text":"연합 결성 완벽. 서명 위치 분쟁 없음."},"2":{"who":"베르단","text":"연합 결성. 서명 위치에 대한 이견이 있었다."},"1":{"who":"클레어","text":"결성은 했으나 상표 분쟁이 이어집니다."}}},{"id":"C11-2","no":2,"title":"마계 입국 심사","boss":false,"before":[{"who":"몽마 병사","text":"마계 쾌락 구역에 오신 것을 환영합니다. 입국 목적을 말씀해 주세요."},{"who":"클레어","text":"무자비한 정화입니다."},{"who":"몽마 병사","text":"정화는 저희도 대환영입니다. 피학적 방문 기간은?"},{"who":"베르단","text":"신경망을 교란한 원인이 해결될 때까지다."},{"who":"몽마 병사","text":"원인이라니, 무슨 원인이요?"},{"who":"클레어","text":"곧 뼈저리게 알게 되겠죠. 입국 도장 부탁드립니다."},{"who":"몽마 병사","text":"도장은 이쪽 맨살에 찍습니다. 화상을 입힐 분홍색 인두입니다."}],"after":[{"who":"몽마 병사","text":"(바닥에 널브러져) 입국 심사 통과! 근데 심사만 하는데 왜 전투가 되었죠? 하복부가 찢어질 것 같아요!"},{"who":"베르단","text":"맨살에 도장 찍는 과정에서 네놈이 뻣뻣하게 저항했기 때문이다."},{"who":"몽마 병사","text":"저항이라니, 저는 쾌락을 모르는 평범한 도장 찍는 직원입니다."},{"who":"클레어","text":"실례했습니다. 체온을 덥힐 사과 홍차를 드리겠습니다."}],"stars":{"3":{"who":"클레어","text":"입국 심사 완료. 도장 색상 분홍."},"2":{"who":"베르단","text":"심사 통과. 도장이 일부 번졌다."},"1":{"who":"클레어","text":"심사 지연. 직원의 질문이 길었습니다."}}},{"id":"C11-3","no":3,"title":"몽마 병사의 정체","boss":false,"before":[{"who":"몽마 병사","text":"저는 최하급 몽마입니다. 마계 방위를 맡고 있습니다. 근데 결박당하는 방위가 처음이라서요."},{"who":"베르단","text":"맞고 버티는 방위 경험이 없는 비루한 병사가 어떻게 방어하나."},{"who":"몽마 병사","text":"방어는 안 하고 하의를 벗고 환영합니다. 방어라는 걸 배운 적이 없어요."},{"who":"클레어","text":"수치심 없이 환영하는 병사를 짓밟는 것은 처음입니다."},{"who":"몽마 병사","text":"사실 우리 마계 병사들은 전부 구직자 알바생 출신이에요. 여왕님이 쾌락만 짜내고 월급을 안 주셔서."}],"after":[{"who":"클레어","text":"병사 전원 제압. 하지만 이분들은 발정 난 적이 아니라 불쌍한 노동자입니다."},{"who":"베르단","text":"노동자 대우를 개선해 주면 우리 발밑에서 짓밟히도록 협조할 것이다."},{"who":"몽마 병사","text":"월급 대신 주인의 무자비한 정화를 받으면 안 될까요? 고전압 간식 포함으로요."},{"who":"클레어","text":"협상하죠."}],"stars":{"3":{"who":"클레어","text":"병사 전원 협조 확보. 월급 협상 시작."},"2":{"who":"베르단","text":"협조 확보. 정화 대기 줄이 길어졌다."},"1":{"who":"클레어","text":"확보 지연. 병사들이 일하기 싫어합니다."}}},{"id":"C11-4","no":4,"title":"누가 누구를 정화하나","boss":false,"before":[{"who":"클레어","text":"몽마 병사 고문 정화는 연방 규정에 따라 제가 채찍을 듭니다."},{"who":"베르단","text":"육체를 찢는 정화는 제국 규정이 우선이다. 내가 짓밟는다."},{"who":"클레어","text":"우선 규정은 병기하기로 했습니다."},{"who":"베르단","text":"병기하면 두 가학 규정이 충돌한다. 무릎 꿇린 노예의 소유권도 어느 쪽에 귀속되는가."},{"who":"몽마 병사","text":"저는 어느 쪽 구두를 핥든 괜찮은데요. 엉덩이 까고 줄 서면 되죠?"},{"who":"클레어","text":"줄은 한 줄로 엄격하게 세우겠습니다."}],"after":[{"who":"베르단","text":"노예의 소유권은 병사 본인의 피학적 선택에 따르기로 했다."},{"who":"클레어","text":"가학 선택제. 합리적이네요. 발정 난 병사 여러분, 마음에 드는 주인의 발밑에 서세요."},{"who":"몽마 병사","text":"(전원 환호하며 두 줄로 나뉘어 기어간다) 어, 균형이 맞네요."},{"who":"베르단","text":"완벽한 굴종에 문제없다."}],"stars":{"3":{"who":"클레어","text":"소유권 분쟁 해결. 선택제 도입."},"2":{"who":"베르단","text":"해결. 일부 병사가 두 줄 모두에 섰다."},"1":{"who":"클레어","text":"해결 지연. 규정 해석이 갈렸습니다."}}},{"id":"C11-5","no":5,"title":"마계 식당","boss":false,"before":[{"who":"몽마 병사","text":"마계 식당입니다. 오늘의 최음 메뉴는 정기 스프와 분홍 파스타입니다."},{"who":"클레어","text":"정기 스프라니, 체액을 짜낸 듯한 이름이 대단히 수상한데요."},{"who":"몽마 병사","text":"이름만 음탕하고 평범한 닭고기 스프예요."},{"who":"베르단","text":"분홍 파스타는 혀가 마비될 정도로 매운가."},{"who":"몽마 병사","text":"뇌가 녹을 정도로 달아요. 신경 교란 딸기 소스입니다."},{"who":"클레어","text":"식사 후 위장이 꽉 찬 상태로 정화 구역으로 이동하죠."}],"after":[{"who":"몽마 병사","text":"후식은 마계 푸딩입니다. 점막에 닿으면 아주 쫀득해요."},{"who":"클레어","text":"쫀득한 식감은 타격만큼 대단히 중요한 쾌락 요소입니다."},{"who":"베르단","text":"레시피를 당장 확보하라."},{"who":"몽마 병사","text":"비법 레시피는 여왕님만 아십니다."}],"stars":{"3":{"who":"클레어","text":"식사 완료. 후식 만족도 최상."},"2":{"who":"베르단","text":"식사 양호. 푸딩 쟁탈전이 있었다."},"1":{"who":"클레어","text":"식사 중단. 파스타가 식었습니다."}}},{"id":"C11-6","no":6,"title":"마계 사무소","boss":false,"before":[{"who":"몽마 병사","text":"이쪽은 마계 사무소입니다. 피부를 찢어발길 여왕님 면담 신청서는 이쪽에서 받습니다."},{"who":"베르단","text":"대면 면담 신청서를 작성하겠다."},{"who":"클레어","text":"면담 사유는 「집단 발정 원인 규명 및 가학적 정화 협의」로 적죠."},{"who":"몽마 병사","text":"접수했습니다. 다만 고문 대기 번호가 3,000번입니다."},{"who":"클레어","text":"3,000번이라니, 마계에서도 피학 예약이 미친 듯이 밀리는군요."},{"who":"베르단","text":"노예의 새치기는 절대 허락되지 않는다. 하지만 주인의 폭력적인 전투는 허락된다."}],"after":[{"who":"몽마 병사","text":"(두들겨 맞은 채로) 여왕님께서 직접 나오신답니다. 번호표는 필요 없다고 하십니다."},{"who":"클레어","text":"직접 나오신다니, 채찍을 준비하겠습니다."},{"who":"베르단","text":"연합군 전원 하의 단속하고 정비하라."}],"stars":{"3":{"who":"클레어","text":"여왕 면담 확보. 연합군 사기 최고조."},"2":{"who":"베르단","text":"면담 확보. 일부 병사가 번호표를 버리지 않았다."},"1":{"who":"클레어","text":"확보 지연. 사무소가 혼잡했습니다."}}},{"id":"C11-7","no":7,"title":"비밀 공개, 첫 번째","boss":false,"before":[{"who":"여왕","text":"(요란하게 등장) 어서 오세요. 마계의 여왕입니다. 모두가 궁금해하시는 집단 발정 원인에 대해 설명드리겠습니다."},{"who":"클레어","text":"당신이 온 세상을 미치게 한 원인을 아십니까."},{"who":"여왕","text":"알다마다요. 제가 그 음탕한 원인이거든요."},{"who":"베르단","text":"…뭐라고."},{"who":"여왕","text":"말씀드리자면 이렇습니다. 선임 마왕께서는 연로하셨고, 제 이력서를 보시고 그 자리에서 끈적한 면접 겸 시연을 요청하셨어요."},{"who":"클레어","text":"가학적 시연이라 함은."},{"who":"여왕","text":"입에 담기 부끄러운 쾌락 내용이라 생략하겠습니다. 결론만 말씀드리면 그 교미 시연이 너무 훌륭해서 선임 마왕께서 그만 복상사하셨습니다."}],"after":[{"who":"여왕","text":"오해 마세요. 거친 호흡 문제였습니다. 저는 쾌락에 최선을 다했을 뿐이에요."},{"who":"베르단","text":"호흡 문제로 복상사한다는 건 군사적으로 일반적이지 않은 가학 표현이다."},{"who":"여왕","text":"일반적이지 않죠. 하지만 죽여주는 사실입니다."},{"who":"클레어","text":"더러운 이야기를 이어 주세요."}],"stars":{"3":{"who":"클레어","text":"첫 공개 성공. 여왕의 면접 경위 확보."},"2":{"who":"베르단","text":"공개 양호. 이야기가 샛길로 샜다."},"1":{"who":"클레어","text":"공개 지연. 여왕이 시연 장면을 상세히 설명하려 했습니다."}}},{"id":"C11-8","no":8,"title":"비밀 공개, 두 번째","boss":false,"before":[{"who":"여왕","text":"그 정기를 제가 얼떨결에 몽땅 흡수해서 새 마왕이 되었습니다. 취임 첫날 설정을 만지며 시험해 보다가 대형 사고가 생겼어요."},{"who":"클레어","text":"발정 설정이라고요."},{"who":"여왕","text":"「세상 모든 종족의 성향 설정」 화면이 있었는데, 재미있게 놀려고 모두 S로 콱 바꿨습니다. 그리고 해제 버튼을 못 찾았습니다."},{"who":"베르단","text":"…기계 사용 설명서는 읽지 않았나."},{"who":"여왕","text":"읽는 데 3,000쪽이 필요했습니다. 귀찮아서 읽지 못했어요."},{"who":"클레어","text":"그래서 온 세상이 도S로 각성해 채찍을 휘두르게 되었군요."}],"after":[{"who":"여왕","text":"잡혀서 고문당하면 피학적인 M이 된다는 건 제가 정한 게 아니에요. 극단적인 설정이 시스템 내에서 저절로 쾌락의 균형을 잡은 것 같습니다."},{"who":"베르단","text":"그 엉터리 시스템에서 균형이 맞은 것 자체가 끔찍한 기적이다."},{"who":"여왕","text":"덕분에 종족 번식도 하드코어하게 끊기지 않았죠. 저의 실수가 오히려 세상을 짜릿하게 구했다고 봅니다."},{"who":"클레어","text":"실수가 구했다는 말은 몹시 건방지고 위험한 표현입니다."}],"stars":{"3":{"who":"클레어","text":"원인 확보. 설정 화면 실수 기록 완료."},"2":{"who":"베르단","text":"원인 확보. 여왕의 변명이 길었다."},"1":{"who":"클레어","text":"확보 지연. 여왕이 사용 설명서 이야기를 반복했습니다."}}},{"id":"C11-9","no":9,"title":"코어의 정체","boss":false,"before":[{"who":"클레어","text":"하늘에 뚫린 저 음탕한 분홍빛 균열은 무엇입니까."},{"who":"여왕","text":"그건 제 방의 끈적한 환기구입니다. 문의 열쇠를 겸하고 있어요."},{"who":"베르단","text":"환기구가 세계 신경망에 균열을 일으키나."},{"who":"여왕","text":"코어가 쾌락으로 과열되면 열립니다. 코어를 무자비하게 파괴하면 문이 닫히고, 발정 저주는 해제되지 않지만 평화로워집니다."},{"who":"클레어","text":"신경 교란 저주는 영영 해제되지 않나요."},{"who":"여왕","text":"저도 해제하는 방법을 몰라요. 다만 여러분은 이 미친 사육 생태계를 이미 즐기고 계시잖아요."}],"after":[{"who":"베르단","text":"반박의 여지가 없이 정확한 통찰이다."},{"who":"클레어","text":"코어를 박살 내서 파괴하죠. 정중하게."},{"who":"여왕","text":"파괴당하기 전에 체온을 올릴 홍차 한 잔 드시겠어요?"},{"who":"클레어","text":"짓밟고 파괴한 후에 마시겠습니다."}],"stars":{"3":{"who":"클레어","text":"코어 위치 확보. 여왕의 협조적 태도 확인."},"2":{"who":"베르단","text":"확보. 환기구 열쇠 설명이 장황했다."},"1":{"who":"클레어","text":"확보 지연. 여왕이 코어 보호를 시도했습니다."}}},{"id":"C11-10","no":10,"title":"서큐버스 여왕","boss":true,"before":[{"who":"여왕","text":"여러분, 최종 쾌락 시연을 시작하겠습니다. 오늘 시연은 저의 마지막 가학 쇼입니다."},{"who":"클레어","text":"가장 정중하고 자비 없이 뼈를 부숴 상대해 드리겠습니다."},{"who":"베르단","text":"연합군 전원, 사지를 묶는 구속 대전 개시."},{"who":"여왕","text":"구속 대전이라니, 저를 꽁꽁 묶고 유린하시려고요? 참으로 좋은 취향이시네요."},{"who":"몽마 병사","text":"여왕님을 응원합니다! 하지만 무참히 구속당해서 발버둥 치시길 기대합니다!"},{"who":"여왕","text":"병사들이 쾌락에 눈이 멀어 배신하다니, 감동적이네요."}],"after":[{"who":"여왕","text":"(밧줄에 묶인 채 헐떡이며) 졌습니다. 완패입니다. 살을 파고드는 여러분의 정화는 훌륭해요."},{"who":"클레어","text":"코어를 완벽히 파괴했습니다. 끈적한 문이 닫힙니다."},{"who":"여왕","text":"문이 닫히면 저희는 이제 결박당한 채 무엇을 해야 하나요. 월급도 없는데."},{"who":"베르단","text":"전원 연방과 제국 소속 영웅들의 비천한 노예로 편입한다. 월급 대신 24시간 가동되는 쾌락 정화를 지급한다."},{"who":"몽마 병사","text":"꺄아아악! 감사합니다! 저희 서큐버스·인큐버스 전원 당장 엎드려서 노예 신청서를 제출합니다!"},{"who":"여왕","text":"(바닥을 기며) 제 가학 신청서가 제일 먼저 접수되어야 합니다. 제가 1번입니다."},{"who":"클레어","text":"1번은 저입니다. 아니, 비루한 노예를 밟을 주인의 신청서 번호가 1번이라는 뜻입니다."},{"who":"베르단","text":"쓸데없는 다툼은 버리고 절대적인 굴종의 서열을 정하자."},{"who":"여왕","text":"(영웅들을 향해 엉덩이를 치켜들고 일렬로 서며) 전원, 크게 비명 지르며 함께 외치시죠."},{"who":"모두","text":"오늘도 어김없이…… 뼈를 깎는 정화 시퀀스다!! 하복부 꽉 조이고 긴장하는 게 좋을 거다, 이 비루한 노예들아!!!"},{"who":"서큐버스·인큐버스 전원","text":"네~~~~~~~~!! 무자비하게 찢어주세요!! (하트 뿅뿅)"},{"who":"클레어","text":"11장 종료. 신경망이 완벽히 통제된 평화로운 해결입니다."}],"stars":{"3":{"who":"클레어","text":"여왕 포획. 신청서 1번 접수, 전원 노예 편입 완료."},"2":{"who":"베르단","text":"여왕 포획. 신청서 번호 분쟁이 이어진다."},"1":{"who":"클레어","text":"여왕 도주 후 재접수. 코어 파괴는 성공했습니다."}}}]},"C11_reactions":{"클레어":["홍차는 식기 전에 마시고, 뼈와 살을 분리하는 정화는 점막이 식기 전에 당장 시작합니다.","마계의 가학적 고문 서식도 연방과 같네요. 아주 훌륭하고 무자비한 점입니다."],"그레타":["살점을 두들겨 패서 신경을 고치는 건 이 마계 구석에서도 통하는구만.","명색이 여왕이란 년이 엉덩이 까고 맞겠다고 순번표 뽑고 헐떡이는 건 처음 본다니까."],"실비아":["정중하게 말씀드립니다. 마계 병사들의 허리띠를 조준해 강제로 하반신을 개방시키겠습니다.","허락하신다면 여왕님의 무자비한 채찍이 제 맨살을 파고드는 소리를 한 번 듣고 싶습니다."],"아네트":["마계의 피학 상담소도 철저한 예약제입니다. 여러분의 숨통을 조일 차트를 가져왔어요.","여왕님은 제 고전압 찜질 환자분 중 가장 쾌락 만족도가 높은 발정 난 분이 되시겠네요."],"톰":["마계에도 수치심을 가릴 구속 담요가 있을까요. 없으면 제 몸을 결박할 걸 직접 챙겨 오겠습니다.","딸이 애비가 목줄 차고 헐떡이는 이 꼴을 들으면 아주 어이없어서 웃을 것 같아요."],"렌":["마계의 독기에 노출되어도 나는 굴복하지 않았다. 그저 전립선이 반응해 몸이 먼저 갔을 뿐이다.","이번 쾌락 고문 예약은 수치를 무릅쓰고 내가 먼저 걸었다. 살이 찢어지도록 기록해 둬라."],"카이단":["주인님, 마계의 음탕한 냄새 좋아요! 흥분해서 꼬리가 프로펠러처럼 멈추질 않아요!","마계의 살점 뜯는 정화방이 궁금해요! 저기서 뒹굴게 목줄 당겨서 같이 가요!"],"그로크":["마계 병사 여러분, 제 비루한 육체에 대한 평가는 가장 쓰레기 보듯 가혹하게 매도해 부탁드립니다.","저를 짓밟아주시던 로나 교관님의 차가운 구두 굽이 몹시 보고 싶습니다. 오늘 제 굴욕 평가는 몇 점일까요."],"이그니스":["무자비한 업무다. 마계의 변태적인 고문 설비도 내 손으로 직접 뜯어 정비하겠다.","마계 갑주는 죄다 하반신을 깐 천 한 장이라, 때릴 맛이 안 나서 제국의 장인으로서 마음이 아프구만."],"베르단":["제국의 장군은 마계의 유린 앞에서도 무겁고 정중하다.","숨통을 조이는 족쇄 규정을 마계 생태계에도 도입하겠다. 제1조는 주인의 구두 굽 3미터 이내다."],"코그":["마계의 신경 교란 장비는 해체할 가학적 가치가 높습니다! 강제로 뜯어 설계도를 얻겠습니다!","점막을 녹이는 신제품 「마계 최음 연막탄」의 끔찍한 아이디어가 뇌관처럼 샘솟습니다!"],"루시안":["기도를 압박하는 차가운 목줄이 있어서 이 마계에서도 완벽히 안심입니다.","채찍을 쥐는 무자비한 주인이 되는 것도, 결국은 피학에 미친 모범 노예가 걷는 또 다른 길입니다."],"로제":["마계 병사 여러분, 점막과 혈류량 건강 검진을 받으세요. 강제 결박 접수는 제가 하겠습니다.","오늘도 제 살갗을 찢으러 다녀오겠습니다. 마계의 무자비한 정화방은 얼마나 아찔할까요."],"핀":["마계도 불평할 거리가 엄청 많아. 고문 의자가 너무 푹신해서 뼈가 안 울리잖아.","이 기괴하게 하늘이 갈라진 끈적한 풍경은 하복부를 찌릿하게 해서 왠지 설레. 불평할 구실은 이상 없어."],"벨루가":["마계 하늘은 날면서 묶이기 딱 좋아! 신경을 마비시킬 내 깃털이 음탕한 분홍색이 됐어!","여왕님 날개는 나보다 훨씬 크네! 같이 묶여서 쾌락에 허덕이며 날자!"],"자하라":["마계의 쾌락 환율은 어떻게 되나요. 뼈를 부수는 고문 월정액 구독 신청받습니다.","저 변태 여왕님과 계약해서 피학 횟수를 늘리면 제 점막에 이득이 얼마일지 철저히 계산해 보겠습니다."]}};